window.__D("text/torat-chaim/c034",{"p":[[2300550596,"<b>וזהו</b> ועשית ציץ זהב טהור כו', ומבואר למעלה שיש בזה ב' תנאים, הא' שיעשנו משה דוקא כמ\"ש ועשית ציץ כו', והב' שיהי' הציץ הזה על מצח אהרן דוקא. והנה מה שתנאי הא' הוא שיהי' מעשה הציץ ע\"י משה דוקא, הטעם הוא כי הנה צ\"ל ב' דברים בתיקון המשכת האור דרך המסך והמחיצה, א' שיעש[ה] פרצה וסדק במחיצה זו, והב' שיאיר האור בפרצות וסדקים הללו מבחי' אור העצמות דוקא, וב\"ד<sup data-n=\"5830\">340</sup> הללו הוא שנכללו בענין הציץ כשנעשה ע\"י משה דוקא כמ\"ש ועשית ציץ והעיקר הוא מה שיאיר האור בו הוא שעשה משה דוקא. והטעם הוא לפי שעיקר כח המנגד לבטל ולשבר קליפה הגסה דעמלק לא הי' אלא ע\"י משה דוקא מב' טעמים שהן א', לפי ששרש נשמת משה הי' מבחי' אין ומה בעצם שזהו בחי' הביטול ה\"פ ב\"ע<sup data-n=\"5831\">341</sup> ממש שלמעלה מבחי' ביטול היש לאין כמש\"א ונחנו מ\"ה מ\"ה בעצם<sup data-n=\"5832\">342</sup> (נישטקייט בעצם), שאינו מרגיש א\"ע בעצם כלל כאלו אינו במציאות כלל וע\"כ הי' עניו מכל האדם<sup data-n=\"5833\">343</sup> כו', שהענווה הוא רק העדר הרגשת עצמו בתכלית עד שהוא נבזה בעיניו ונמאס כמותר בעולם והכל טובים ממנו אפילו הפחות שבפחותים ממש וע\"כ נפשו כעפר לכל כו'. וזהו מצד שרש נשמתו בעצם שהוא בבחי' אין האלקי [ב]בחי' מ\"ה דחכ' כמו שהיא בבחי' הכתר פ'<sup data-n=\"5834\">344</sup> שנק' אין בעצם שהוא בבחי' ביטול במציאות לגמרי מכל וכל דוקא, כידוע במ\"ש כי מן המים משיתיהו<sup data-n=\"5835\">345</sup> ממ\"ע דח\"ע הפנימי' שבה שורה בחי' עצמו' א\"ס ממש, כידוע דאין עצמות [א]א\"ס שורה כ\"א בבחי' אי\"ן<sup data-n=\"5836\">346</sup> ומ\"ה בתכלית הקצה <span data-k=\"pg\">1096</span> ּ דוקא כמשה וכה\"ג ע\"כ ידעו ה' פא\"פ<sup data-n=\"5837\">347</sup> כו'. והוא עצמו [ה]טעם שהתורה ניתנה ע\"י משה דוקא וכל התורה לא נק' רק ע\"ש משה דוקא בשם תורת משה<sup data-n=\"5838\">348</sup> כמ\"ש תורה צוה לנו משה<sup data-n=\"5839\">349</sup> כו', ובכמה מקומות נאמר[ו] המצות ע\"ש משה כאלו הוא המצוה ממש כמו פ' ק\"ש שמע ישראל ואהבת כו', וכן והא\"ש כו' לאהבה עד ונתתי מטר<sup data-n=\"5840\">350</sup> כו', וכן אם בחוקתי תלכו<sup data-n=\"5841\">351</sup> כו', וכה\"ג רבות בכתובים שמורה הדבר שהתורה הזאת של משה עצמו הוא ממש כאלו הוא מעצמו צוה אותה כו' כמ\"ש תורה צוה לנו משה כו'. והלא באמת כל דבור ודבור שיצא מפי משה הכל הי' ממה שקיבל ושמע מפי הגבורה עצמו בכ[ל] ד[יבור] וד[יבור] בפרט שהי' מדבר ומצוה לישראל כמבואר בכמה פ' שאומר ויאמר ה' אל משה<sup data-n=\"5842\">352</sup> לאמר לבנ\"י כו' ואפילו ההלכות דתושבע\"פ קיבל משה מסיני כו' ואין דבר שמצוה מעצמו ח\"ו. ועכ\"ז נק' תורת משה משה<sup data-n=\"5843\">353</sup> דוקא ונאמר הכל על שמו כאלו הוא המצוה לעשות כו'.",[["5830","340","<b>וב\"ד</b>: אכא: (כנ\"ל) וב' דברים."],["5831","341","<b>ה\"פ ב\"ע</b>: שם: הפנימי' בעצמו'."],["5832","342","<b>ונחנו מ\"ה מ\"ה בעצם</b>: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["5833","343","<b>עניו מכל האדם</b>: בהעלותך יב, ג. ראה גם לקמן פ' פקודי תנח, א."],["5834","344","<b>הכתר פ'</b>: א: פנימי' הכתר. כא: הכתר בפנימי'."],["5835","345","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה לעיל פ' שמות מג, א. וש\"נ."],["5836","346","<b>דאין עצמות. . בבחי' אי\"ן</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>."],["5837","347","<b>כמשה. . ידעו ה' פא\"פ</b>: ברכה לד, י."],["5838","348","<b>תורת משה</b>: יהושע ח, לא. לב. כג, ו. ועוד."],["5839","349","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["5840","350","<b>והא\"ש. . ונתתי מטר</b>: עקב יא, יג. יד."],["5841","351","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["5842","352","<b>ויאמר ה' אל משה</b>: ראה גם לעיל פ' וארא נט, א ובהערה 30."],["5843","353","<b>משה</b>: אכא: ליתא."]]],[2300550607,"<b>אך</b> הענין הוא דאדרבה היא הנותנת דמפני שהי' נשמת משה מבחי' מ\"ה ואין האמיתי בבחי' הביטול במציאות בתכלית הקצה עד שלא הי' מרגיש ויודע מעצמו כלום כאלו אינו ממש מחמת גודל שפלותו וענוותנותו ביותר עד שלא הי' תופס מקום בפ\"ע כלל, וע\"כ הי' רק בחי' כלי לבד בבחי' בטל וטפל לגילוי אור ה' שהי' מאיר בנשמתו בתמידית כענין שא' שכינה מדברת מתוך גרונו<sup data-n=\"5844\">354</sup> של משה כו' (כמש\"א ולא קם נביא<sup data-n=\"5845\">355</sup> עוד כמשה אשר ידעו ה' פא\"פ שכל הנביאים נתנבאו בכ\"ה<sup data-n=\"5846\">357</sup> בכ\"ף הדמיון שזהו בחי' מל' דאצי' שמלובש בבריאה ויצי'<sup data-n=\"5847\">358</sup> כו' שנק' מראה דמות כבוד הוי'<sup data-n=\"5848\">359</sup> דאצי' כמש\"א הן במראה אליו אתוודע<sup data-n=\"5849\">360</sup>, אבל משה נבואתו הי' באצי' ממש כמו שהוא טרם ירידת האור ע\"י מסך בבחי' זה<sup data-n=\"5850\">361</sup> שהי' מתנבא בזה<sup data-n=\"5851\">356</sup> לנוכח כו', דמטעם זה הי' אור הוי' מאיר בנשמתו בבחי'<sup data-n=\"5852\">362</sup> פנימי' אור הכתר שבח\"ע דאצי' בתמידית והי' מדבר עמו פא\"פ<sup data-n=\"5853\">363</sup> כאשר ידבר איש כו', לפי שלא הי' תופס מקום כלל מצד בחי' הביטול דמ\"ה בעצם כמו שהוא באצי'). ומזה הטעם עצמו הוא שנק' התורה על שמו כאלו הוא המצוה ממש<sup data-n=\"5854\">364</sup> כו' כנ\"ל, לפי שאינו תופס מקום כלל וכלל כאלו<sup data-n=\"5855\">*365</sup> הי' רק כמו בחי' כלי בעלמא לגילוי אור דתורה שהוא דבר ה' שנאמר למשה כו' ואינו בחי' יש ודבר בפ\"ע כלל ואינו נתפס בשם ומציאות בפ\"ע כלל להיותו בבחי' מ\"ה בעצם האי\"ן, וע\"כ נק' עבד הוי'<sup data-n=\"5856\">365</sup> ממש כעבד לגמרי שבטל וטפל<sup data-n=\"5857\">366</sup> לשם הוי' (וזהו לא כן עבדי משה<sup data-n=\"5858\">367</sup> בכל ביתי נאמן הוא דהיינו בכל הון ביתו העליון שהוא בחי' הון החכמה דתורה שנק' בית הוי' כו' שנאמן הוא בכל ביתו כמו [ש]הוא עצמו כביכול שיכול לצוות לעשות בכל הנהגת ביתו כרצונו כו' כמ\"ש במ\"א). וזש\"א ויאמינו בהוי' ובמשה עבדו<sup data-n=\"5859\">368</sup> שהכל א' מצד שאינו רק בחי' כלי וטפל ממש לשם הוי' המדבר בו בתמידות, וז\"ש אשר ידעו ה' פא\"פ כו' ע\"כ א' תורה צוה לנו משה דנק' על שמו אע\"פ שדבר ה' הוא שדיבר בפי משה. אך מצד עוצם ביטול בתכלית זהו כאומר מפי עצמו ואינו נבדל בזה מן הע[צמו'] דא\"ס כלל לפי שאור א\"ס שורה בבחי' מ\"ה ואין האמיתי ביחוד האמיתי כנ\"ל וד\"ל.\n<span data-k=\"pg\">תקמח</span> ּ<b>והנה</b> מזה יובן ג\"כ שרש מצות ת\"ת גם עתה בכל דור ודור בכל מי שיושב ושונה [וקורא] ומדבר דבר ה' זו",[["5844","354","<b>שכינה מדברת מתוך גרונו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא</a> פל\"ד. לעיל פ' בשלח קצד, ד הערה 540."],["5845","355","<b>ולא קם נביא</b>: ברכה לד, י [בדילוג]."],["5846","357","<b>בכ\"ה. . מל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת כה. מאמרי אדה\"ז תקס\"ד ע' קצ. תקס\"ח ח\"א ע' קפז. מאמרי אדה\"א בראשית ע' שכא וע' תכב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת נצבים מז, ב</a>."],["5847","358","<b>בבריאה ויצי'</b>: א: בבי\"ע."],["5848","359","<b>מל'. . מראה דמות כבוד הוי'</b>: יחזקאל א, כח. ראה זהר ויקהל רטו, א ובהגהות מהרח\"ו שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שעד."],["5849","360","<b>הן במראה אליו אתוודע</b>: בהעלותך יב, ו [בהוספת תיבת ”הן\" — נסמן לעיל פ' בשלח קמד, א הערה 24]."],["5850","361","<b>בבחי' זה</b>: א: בבריאה וזה. כא: דבריאה וזהו."],["5851","356","<b>שכל הנביאים נתנבאו בכ\"ה. . בזה</b>: ראה ספרי ר\"פ מטות הובאה ברש\"י שם. לעיל פ' בשלח קמד, ב הערה 29."],["5852","362","<b>בבחי'</b>: כא: מבחי'."],["5853","363","<b>והי' מדבר עמו פא\"פ</b>: תשא לג, יא."],["5854","364","<b>ממש</b>: כא: ליתא."],["5855","*365","<b>כאלו</b>: יגכג: כי לא. כא: כתב כאלו וממעל לתיבה זו כתב כי לא."],["5856","365","<b>עבד הוי'</b>: ברכה לד, ה."],["5857","366","<b>לגמרי שבטל וטפל</b>: א: שבטל וטפל לגמרי. כא: שבטל וטפל."],["5858","367","<b>לא כן עבדי משה</b>: בהעלותך יב, ז. ראה לעיל פ' בשלח קנה, ד. וש\"נ."],["5859","368","<b>ויאמינו בהוי' ובמשה עבדו</b>: בשלח יד, לא."]]],[2300550616,"הלכה<sup data-n=\"5860\">369</sup> כו' שזהו ג\"כ בבחי' ומדרגה דמשה כו' דאתפשטות[א] דמשה בכל דרא<sup data-n=\"5861\">370</sup> בעוסקי' בתו\"מ<sup data-n=\"5862\">371</sup> בתושב\"כ ושבע\"פ כו', דהיינו שאינו רק בחי' כלי בעלמא לדבר ה' זו הלכה או מקרא שלומד ומדבר בפיו ואינו דבר עצמו כלל וכמ\"ש ודברי אשר שמתי בפיך<sup data-n=\"5863\">372</sup> כו', וכתיב למען תהי' תורת ה' בפיך<sup data-n=\"5864\">373</sup> כו' ואינו תופס מקום בפ\"ע כלל רק כמו הנביא שמדבר בו דבר ה' שאינו רק כלי [להכיל] לדבר ה' בפה שלו שמדבר<sup data-n=\"5865\">374</sup> בפיו, וכך דבר ה' זו הלכה ומשנה שמדבר בפיו וכן במקרא אינו אלא כעונה אחר הקורא כענין תען לשוני אמרתיך<sup data-n=\"5866\">375</sup> כו'. וכענין שא' בק\"ש השמע לאזניך מה שאתה מוציא מפיך<sup data-n=\"5867\">376</sup> שצריך גם הוא לשמוע בקול ה' שדיבר בו מאחר שנק' דברי ממש אשר שמתי בפיך כו' ובפי המדבר דבר ה' הרי שורה אור א\"ס ב\"ה עצמו שלמעלה מכל ההשתל' דס[ובב] וממ[לא] כנ\"ל. כי אין השראת והמשכת אוא\"ס עצמו ממש כמו שהוא בלי שינוי מקודם ההשתלשלו' לאח\"כ כלל רק בבחי' חכ' שבאותיות התורה שהוא בבחי' מ\"ה ואין ממש כמ\"ש והחכ' מאין תמצא<sup data-n=\"5868\">377</sup>, ונק' כח מ\"ה<sup data-n=\"5869\">378</sup> ממש כמו שהוא בבחי' פנימי' ועצמי' דא\"ס ממש שנק' חכים ולא בחכ' ידיעא<sup data-n=\"5870\">379</sup> כלל וע\"כ אינו שורה רק בבחי' ביטול במציאות בהעדר הרגשת עצמו ליש ודבר כלל כמו הקורא בתורה שאינו רק כלי לדבר ה' כו' ואז ה' יושב ושונה כנגדו<sup data-n=\"5871\">380</sup> (כמשי\"ת). משא\"כ האומר אין ל[י] אלא תורה<sup data-n=\"5872\">381</sup> שעושה מלמודו יש ודבר אף שאוהב את התורה מצד עצמה שהיא חכמה יקרה בעיניו ובאהבתה ישגה תמיד<sup data-n=\"5873\">382</sup> וע\"כ או' אין ל[י] אלא תורה, אבל בזה נעשה בבחי' נפרד גם עם התורה שלומד מעצמות אור א\"ס ששורה בתורה כי בבחי' יש ולגרמי' שעושה במ[ה] שא' אין ל[י] אלא תורה, הרי גם התורה שלומד מפריד מאור א\"ס ב\"ה שלא ישכון בבחי' יש ודבר, ואין דבר חוץ ממנו ית' אפי' החכ' דתורה מתייחדת בעצמות כי הוא המדע<sup data-n=\"5874\">383</sup> כו' ואורייתא וקוב\"ה כולא חד<sup data-n=\"5875\">384</sup> ממש, והוא או' אין ל[י] אלא תורה לבד בלי גילוי אוא\"ס שבה שאינו חפץ בתורה רק מצד עצמה לבד ולא מצד שהיא תורת ה' וא\"כ מפריד בזה החכ' דתורה מאוא\"ס ב\"ה, ואז<sup data-n=\"5876\">385</sup> אפילו תורה אין לו שלא יצליח בלימודו ואין התורה מתקיימת בלבו כלל. והטעם הוא כי בהסתלקות והסתר אור א\"ס שבתורה אין לחכ' דתורה קיום במציאות כלל מצד שמתייחדת בבחי' כלי",[["5860","369","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["5861","370","<b>דאתפשטות[א] דמשה בכל דרא</b>: ראה ת\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א-ס\"א). הנסמן לעיל פ' וארא פ, ג."],["5862","371","<b>בתו\"מ</b>: כא: בתורת משה."],["5863","372","<b>ודברי </b>[כא: ניתוסף: ממש]<b> אשר שמתי בפיך</b>: ישעי' נט, כא."],["5864","373","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["5865","374","<b>בו. . שמדבר</b>: א: ליתא. וכנראה שנשמט מפני תיבות הדומות: שמדבר. . שמדבר."],["5866","375","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב."],["5867","376","<b>השמע לאזניך מה שאתה מוציא מפיך</b>: ברכות יג, א."],["5868","377","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["5869","378","<b>והחכ'. . כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["5870","379","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב)."],["5871","380","<b>הקורא. . ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג. וש\"נ."],["5872","381","<b>האומר אין ל[י] אלא תורה</b>: ראה יבמות קט, ב."],["5873","382","<b>ובאהבתה ישגה תמיד</b>: ע\"פ משלי ה, יט."],["5874","383","<b>כי הוא המדע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י."],["5875","384","<b>ואורייתא וקוב\"ה כולא חד</b>: נסמן לעיל פ' משפטים רצ, ג."],["5876","385","<b>בלי גילוי. . ואז</b>: כא: ליתא."]]],[2300550623,"פ[נימי'] בביטול דבחי' מ\"ה דוקא כו', ואם [הוא] בבחי' יש ודבר בפ\"ע כמו שאר החכמות אין אור א\"ס שורה בה כלל, וממילא אין לה קיום כלל כי אין לתורה קיום רק מבחי' גילוי אור א\"ס שבה (ולא כשאר חכ' שיש לה קיום בפ\"ע בפירוד). ואע\"פ שהן אותיות ושמות שלו כי כל הקורא בתורה קורא בשמותיו<sup data-n=\"5877\">386</sup> כו', אבל אינו מתלבש בשמות שאינן נאמרין באוי\"ר ונשארי' למטה בעולם הפירוד, ולא נק' קורא בשמותיו כלל מאחר שאומר אין לו אלא תורה שאין ה' שונה כנגדו כו'. ואע\"פ שגם בע\"ק מותר בד\"ת שאין ד\"ת מקבלי' טומאה<sup data-n=\"5878\">387</sup> כו', זהו כשהוא לומד באוי\"ר לפי שחפצו בתורת ה' להיות כלי לדבר ה' (וע\"י טבילה <span data-k=\"pg\">1098</span> ּ בנה\"ד יתעלו עם הנשמה בעלותה לג\"ע), וזש\"א דאין התורה מתקיימת<sup data-n=\"5879\">388</sup> אלא במי שממית עצמו עליה פי' שממית כל בחי' עצמו' ואינו בבחי' יש לומר אין ל[י] אלא תורה (שזהו כמו עד\"מ החפץ לידבק עצמו בלבוש המלך להתלבש ולהתפאר בעונג רב<sup data-n=\"5880\">389</sup> רק מצד עצם הלבוש ולא מצד שהוא לבוש המלך כלל שזהו כמו שנושק ללבוש המלך ולא מכוין למלך עצמו כלל (וכמבואר במ\"א בענין מפני מה נחרב בהמ\"ק לפי שלא ברכו בתורה תחלה<sup data-n=\"5881\">390</sup> כו' וד\"ל).\n<b>וזהו</b> ועשית ציץ כו' שציווי זה הי' למשה דוקא שהוא יעשנו דוקא לפי שע\"י משה נמשך בחי' האור דעצמות אור א\"ס ששורה בדבר ה' דתורה כנ\"ל, שהוא למעלה מכל ההשתל' דהיינו למעלה גם מצמצום הראשון שלפני הקו\"ח כו' דקמי' גם חשך לא יחשיך כו' שבוקע ומאיר גם בהעלם וצמצום כו', וכמ\"ש דהתורה קדמה לעולם<sup data-n=\"5882\">391</sup> אלפים שנה כמ\"ש ואהי' אצלו כו' שעשועי' יום יום<sup data-n=\"5883\">392</sup> בבחי' שעשועי' העצמי' בעצמות התענוג הפנימי' שבא\"ס<sup data-n=\"5884\">393</sup> עצמו (שמשם מאיר האור דבחי' רעדכ\"ר<sup data-n=\"5885\">394</sup> במצח אהרן בציץ זה (כמשי\"ת) וכתי' בראשית ברא ואו' בשביל התורה שנק' ראשית<sup data-n=\"5886\">395</sup> כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"5887\">396</sup> והוא מבחי' אותיות התו' הקדומה שבעצמות א\"ס ממש (שנק' [אותיו'] עצמיי' דג' קשרין הן<sup data-n=\"5888\">397</sup> בבחי' סתים אורייתא סתים בקוב\"ה דלמחת\"ב כמבואר במ\"א). ומטעם זה א\"ר<sup data-n=\"5889\">398</sup> שגם עכשיו אחר כל ההשתל' דאבי\"ע מקו\"ח שעיקר קיום כולם אינו רק מאותיות דתורה כמ\"ש ואשים דברי בפיך ובצל ידי כסיתיך לנטוע<sup data-n=\"5890\">399</sup> שמים וליסוד ארץ, פי' ע\"י דבר ה' שבתורה שאו' בפיך זהו יסוד מוסד לכל ההשתל' דע\"ס דאצי' באו\"כ במקום פנוי<sup data-n=\"5891\">400</sup> עד מקור כל המקיפים בטה\"ע כו', כי ע\"י התורה הקדומה שבעצמות א\"ס ממש הוא שמתחבר גילוי האור א\"ס בקו\"ח שעובר בכל האצי'",[["5877","386","<b>הקורא בתורה קורא בשמותיו</b>: נסמן לעיל שנט, ד."],["5878","387","<b>שגם בע\"ק. . טומאה</b>: ברכות כב, א. ראה גם לעיל פ' יתרו רנד, א הערה 204."],["5879","388","<b>דאין התורה מתקיימת</b>: ראה שבת פג, סע\"ב. הנסמן לעיל פ' שמות ד, א."],["5880","389","<b>בעונג רב</b>: א: ליתא. כא: בעונג."],["5881","390","<b>מפני מה נחרב. . בתורה תחלה</b>: ראה ב\"מ פה, ב. נדרים פא, א. דרך חיים פא, א. ע\"ד הלשון כאן ראה גם מאמרי אדה\"ז תקס\"ט ס\"ע רל. מאמרי אדה\"א דרושי חתונה ח\"א ע' קעג."],["5882","391","<b>דהתורה קדמה לעולם</b>: נסמן לעיל פ' משפטים רצא, ב."],["5883","392","<b>ואהי'. . יום יום</b>: משלי ח, ל."],["5884","393","<b>התענוג הפנימי' שבא\"ס</b>: א: התענוג הפשוט שבא\"ס. כא: התעה\"פ."],["5885","394","<b>רעדכ\"ר</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> הערה 23."],["5886","395","<b>בראשית. . בשביל התורה שנק' ראשית</b>: בראשית א, א וברש\"י שם. הנסמן בלקו\"ש נח כרך ג' ע' 755."],["5887","396","<b>ה' קנני ראשית דרכו</b>: משלי יח, כב."],["5888","397","<b>דג' קשרין הן</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד. וש\"נ."],["5889","398","<b>א\"ר</b>: אכא: אנו רואים."],["5890","399","<b>ואשים דברי. . לנטוע</b>: ישעי' נא, טז."],["5891","400","<b>במקום פנוי</b>: א: במקיפי' ופנימי'. כא: במקו\"פ."]]],[2300550629,"כו'. ולפי\"ז הרי כל המקיפי' עליונים שנק' שמים העליונים והוא עולם האצי' בכלל שהוא בבחי' מקיף לכל העולמות דבי\"ע הנפרדי', וגם כל ההשתל' דעולם הנפרדי' שבאים מצמצום האצי' בבי\"ע ע\"י שם אלקי' המצמצם<sup data-n=\"5892\">401</sup> כידוע, הכל הוא מתקיים רק ע\"י התורה דוקא. וזש\"א לנטוע שמים בבחי' מקיף וליסוד ארץ בבחי' או\"פ שהוא ס[ובב] וממ[לא] בכלל כנ\"ל, וכ\"ז רק מדברי אשר שמתי בפיך שמזה נמשך בחי' האו\"פ בכלים מכלים שונים באותיות וצירופי' עליונים, ובצל ידי כסיתיך זהו שנעשה בחי' אורות המקיפים העליונים שנמשך ממקיפי' העצמיי' שבתורה שנק' צל ידי ממש, וכמ\"ש ה' צלך<sup data-n=\"5893\">402</sup> כו' שע\"ז אמר [ד]כל היושב ושונה הקב\"ה יושב וקורא ושונה כנגדו כצל<sup data-n=\"5894\">403</sup> הנוטה לפי אופן הדבר שעומד לנגדו, כך בקריאת אותיות התו' נוטה בחי' צל הוי' מלמעלה ע\"ז והוא מ\"ש ה' צלך שזהו מה ששונה כנגדו ממש לפי שקורא בשמותיו הע[צמי'] ממש שהוא בחי' אותיות דתוה\"ק וכנ\"ל, וכמ\"ש אשר יקראוהו באמת דתורה<sup data-n=\"5895\">404</sup> דוקא לפי שבה שורה מבחי' אור אמיתי' מהו\"ע ית' בבחי' פנימי' ועצמי' שלו וע\"כ נק' [צל] הוי' ממש כמ\"ש ה' צלך וכן [וב]צל ידי וד\"ל.\n<b>והנה</b> מבואר למעלה שצ\"ל ב' דברים בתיקון להסיר [המסך] המבדיל דקליפת עמלק הנ\"ל, א' להאיר <span data-k=\"pg\">תקמט</span> ּ האור דרך הפרצה וסדק. והב' לעשות הפרצ[ה] וסדק. והנה ענין הארת אור דתורה מעצמות א\"ס ב\"ה זהו ע\"י משה דוקא שהוא בחי' הכלי לזה דוקא והוא בחי' הענוה ושפלות בעצם שנק' מ\"ה בהעדר הרגשת עצמו לגמרי כנ\"ל, וזהו שיש בכאו\"א שעוסק בתורה גם עתה בבחי' הביטול דמ\"ה זה כנ\"ל. והנה בחי' מ\"ה זה שבתורה וכמו ענוה וביטול דמשה דאתפשטותא בכל דרא כנ\"ל הוא עיקר כח המנגד לבחי' החוצפא והגסה\"ר דעמלק הנ\"ל, להיות[ו] תכלית היפוכו שהוא בחי' האין ומ\"ה בעצם שזהו תכלית מדת השפלות והענוה יתירה עד שנפשו כעפר לכל כו' כנ\"ל, שהוא היפך גמור ומנגד גדול לבחי' הגסות והחוצפא בחי' יש נפרד בתכלית. וע\"כ כל עיקר סיבת נפילת הגסות והחוצפא אינו בא רק מכח המנגדו שהוא השפלות והענוה שביכולתו להפילו ולשברו לחלקים כו', וכמו שמצינו במשה שעשה מופתים לפני פרעה במצרים אע\"פ שהכביד את לבו מאד מ\"מ הי' נופל ונשבר תיכף [ש]ה[י' רואה] פני משה איש האלקים שהוא היפוכו המנגדו בתכלי', כי הי' מבחי' מ\"ה בעצם שהוא המנגד לנגד גסות וחוצפא דפר\"ע<sup data-n=\"5896\">405</sup> שהי' בבחי' עורף דקליפה תכלית הגסות",[["5892","401","<b>אלקי' המצמצם</b>: ראה שער היחוד והאמונה רפ\"ו. לעיל פ' שמות לד, ד הערה 386."],["5893","402","<b>ה' צלך</b>: תהלים קכא, ה."],["5894","403","<b>ה' צלך. . כצל</b>: ראה לעיל פ' וארא סה, ד הערה 283."],["5895","404","<b>אשר יקראוהו באמת דתורה</b>: תהלים קמה, יח. ראה ירושלמי ר\"ה פ\"ג, ה\"ח. לעיל פ' שמות יא, ג הערה 513."],["5896","405","<b>דפר\"ע</b>: אכא: דפרעה."]]],[2300550635,"והקושי. ואין עצה רק במה שרואה בחי' אין ומה בתכלית שמזה דוקא יפול הגסות (וכמו המן כשהי' רואה את מרדכי<sup data-n=\"5897\">406</sup> היהודי יושב בשער המלך כו', שבחי' מרדכי הוא מירא דכיא<sup data-n=\"5898\">407</sup> מבחי' גבורות דאבא<sup data-n=\"5899\">408</sup> שהוא מ\"ה דחכמה בבחי' הביטול בתכלית ע\"כ מיד שראה אותו הי' נופל מגיאותו כמש\"א וכל זה איננו שוה לי<sup data-n=\"5900\">409</sup> ) וגם זה הוא הסימן לד[בר] ז[ה] שגדול כח השפלות וביטול אמיתי לשבר כח הגסות לפ\"ע ממש עד שכל שהוא בבחי' אין יותר יותר יוכל לבטל היש ביותר כו', ממה שמרדכי לא יכרע ולא ישתחוה<sup data-n=\"5901\">410</sup> להמן ולא קם ולא זע ממנו<sup data-n=\"5902\">411</sup> כלל שמזה נתמלא המן חימה<sup data-n=\"5903\">412</sup> כי הי' מרדכי היהודי מבטלו בלב[ו] לגמרי כאין וכתהו ממש, ומזה נפל המן בלבו מאד ולא הי' כח בגיאות המן לעמוד נגדו כלל כו'. ומה שהי' כח הזה במרדכי לבטל[ו] בלבו כ\"כ כא' הרקים הפחותים ולא בא לבחי' ביטול כלל לפני המן אע\"פ שגדלו המלך כו' וא\"ל מדוע אתה עובר<sup data-n=\"5904\">413</sup> כו', רק לפי שהי' מרדכי שפל ביותר והי' שונא מאד לגיאות וישות, ובכח השפלות והאין דוקא יש לבטל ולשבר ולהכניע לגסה\"ר עד שאין לגיאים מקום לפני הענוים ושפלים ונופלים מגיאותם מיד שרואים אותם. כמו\"כ הי' בפרעה שנפל מגיאותו וישותו מיד שראה פני משה שהי' עניו מכל האדם שמחמת זה יש בו גילוי אור האלקי שלפניו יושפלו כל הגאות כי רם ה' ושפל יראה<sup data-n=\"5905\">414</sup> ומשפיל גאים וע\"כ הי' משה עיקר המדבר אל פרעה<sup data-n=\"5906\">415</sup> ולא אהרן כמ\"ש במ\"א (והיינו רק מצד שאור א\"ס שורה בבחי' מ\"ה <span data-k=\"pg\">1100</span> ּ ואין והוא גאה על גוותניא<sup data-n=\"5907\">416</sup> להפילם כו').\n<b>והנה</b> מבואר במ\"א בענין הענוה דמשה<sup data-n=\"5908\">417</sup> כו' שיש ב' מיני שפלות, א' שפלות שנק' ענוה יתירה, שהוא בעצם טבעו שאינו נחשב לדבר מ\"ה בעצמו ומהותו כלל עד שהוא בלתי מרגיש א\"ע כלל שנק' (נישטקייט כנ\"ל). והב' שפלות שנק' הכנעת הלב ביותר, שהוא מצד מה שהוא בעצ[מו] בפחיתות הערך ביותר עד שהוא נבזה בעיניו נמאס [ב]יותר עד שנפשו כעפר לכל תהי' מצד שפלות ערכו בעיניו. וזה[ו] מצד החשבון שעושה בנפשו מכל מעשיו ומחשבותיו ומדותיו אשר מאד לא טובים בעיניו כאחד הרקים וקלים בעם (לבד מיעוט הערך בעצמו בדעת ושכל שזהו שנק' שפל ברך<sup data-n=\"5909\">418</sup> בטבעו), הוא שגורם מה שלבו נשבר ונדכה באמת מחמת פחיתות ערכו בחשבונו עם נפשו השפלה וריקני' כמש\"א דוד ואנכי איש רש ונקלה<sup data-n=\"5910\">419</sup> כו' (וה\"ז<sup data-n=\"5911\">420</sup> מצד שרואה חוב בעצמו ביותר על כל מה שעשה ומה שעושה טוב אינו מרגיש בעצמו כלל. והגם שמטבע האדם שאינו רואה חוב לעצמו<sup data-n=\"5912\">421</sup> כלל ה\"ז הוא מצד בחי' הרגשת עצמו ביותר כידוע, אבל מצד שפלותו וענוה שלו",[["5897","406","<b>המן כשהי' רואה את מרדכי</b>: אסתר ה, ט."],["5898","407","<b>מרדכי הוא מירא דכיא</b>: ראה תשא ל, כג ובת\"א. שערי אורה נז, ב הערה 46."],["5899","408","<b>מבחי' גבורות דאבא</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"ב ע' תכט. דר\"מ ר\"ע 318."],["5900","409","<b>וכל זה איננו שוה לי</b>: אסתר ה, יג."],["5901","410","<b>שמרדכי לא יכרע ולא ישתחוה</b>: אסתר ג, ב."],["5902","411","<b>ולא קם ולא זע ממנו</b>: אסתר ה, ט."],["5903","412","<b>שמזה נתמלא המן חימה</b>: אסתר ג, ה. ה, ט."],["5904","413","<b>מדוע אתה עובר</b>: אסתר ג, ג."],["5905","414","<b>כי רם ה' ושפל יראה</b>: תהלים קלח, ו."],["5906","415","<b>משה עיקר המדבר אל פרעה</b>: ראה לעיל פ' וארא פב, ב ואילך."],["5907","416","<b>גאה על גוותניא</b>: ראה ת\"א בשלח טו, א."],["5908","417","<b>בענין הענוה דמשה</b>: ראה לעיל פ' וארא פג, א."],["5909","418","<b>שפל ברך</b>: לשון תדא\"ר פכ\"ה. יל\"ש ואתחנן ה, ו (רמז תתל). אכא: שפל ברי'."],["5910","419","<b>ואנכי איש רש ונקלה</b>: שמו\"א יח, כג."],["5911","420","<b>(וה\"ז</b>: אכא: וכ\"ז."],["5912","421","<b>שמטבע האדם. . חוב לעצמו</b>: שבת קיט, א."]]],[2300550641,"בהעדר הרגשת עצמו ומצד בחי' לב נשבר ונדכה<sup data-n=\"5913\">422</sup> רואה הכל בעצמו לחוב גם חוט השערה כהר יחשב. ולזאת הוא מאד נבזה בעיניו נמאס וכל אדם יהי' מי שיהי' טוב ממנו ויש לו ביטול והכנעה עצמה<sup data-n=\"5914\">423</sup> לפני כל אדם כעפר ממש (וכמו העני המדוכא שהוא בתכלית השפלות לפני כל כי רוחו נשברה מאד). והנה בחי' שפלות זאת שבלב נשבר ונדכה עד שנבזה בעיניו כו' ומואס בחייו ממש כאלו הוא מותר בעולם ממש זהו שהי' במשה שהי' עניו מכל האדם כו', שהי' בו בחי' לב נשבר בתכלית בתמידות כמו בע\"ת אמיתי או עני ואביון מדוכא כו' שזהו תכלית המנגד ביותר לרוח גבוה דקליפות עמלק כחוצפא והתנשאות וגסות יתירה שחזק וקשה כברזל ממש כו'. וע\"י בחי' רוח ולב נשבר דמשה הי' נשבר גסות וגיאות דפרעה כמו ששוברים הברזל וסלע בפטיש חזק כו' שאין עצה לבטל הקשה כסלע וברזל רק בב' דברים, או בהכאה לחלקים כמו בי' מכות שהי' במצרים והוא שהי' נשבר לב פרעה ע\"י שפלות וענווה בלב נשבר דמשה, או ע\"י היפוכו המנגדו שהוא בחי' האין ומה בעצם דמשה, בלא טעם וחשבון בפחיתות הערך ממעשיו רק ממהותו השפל בעצם דנחשב בעצמו לשפל בריה בעצם שהוא הנק' נפש שפילה באמת לאמיתו כו' ורוח נמוכה ביותר, שמזה דוקא יפול הגסות והיש הקשה לגיאות דעמלק או פרעה מטעם הנ\"ל וד\"ל.\n<b>וכך</b> יובן גם בכללות נש\"י כאשר הן בבחי' שפלות זאת דלב נשבר ונדכה כמו בע\"ת אמיתי' כאביוני אדם שרוחם נשברה ביותר בחשבון פחיתות הערך בתכלית עי\"ז נשבר כח של הקליפה דעמלק שהוא המחיצה של ברזל המפסקת בין ישראל כו' [כ]נ\"ל, וסיבת שפלות זו באה רק מבחי' שפלות וענוה יתירה בעצם דבחי' מה דמשה שהוא <span data-k=\"pg\">תקנ</span> ּ בבחי' ביטול עצמי כנ\"ל, והוא בבחי' מה דחכ' דתורה כנ\"ל. והא בהא תליא, ומסיבת שניהם יש ביכולת בחי' מה לשבור ולעשות פרצות וסדקים רבים גם במחיצה ש\"ב הנ\"ל, והוא ע\"י בחי' לב נשבר ונדכה עד שנעשה נבזה בעיניו נמאס כו' שנעשה [זה] ע\"י סיבת בחי' ביטול העצמי'<sup data-n=\"5915\">424</sup> דמה בעצם כו'. ונמצא שע\"י בחי' עוצם לב נשבר הו[א] שנעשה הסדק והפרצה במחיצה ש\"ב זו דעמלק שהוא ביטול הגסות וחוצפא מפני שנופל ונשבר הגסות ע\"י עוצם בחי' לב ורוח נשברה (וראי' לזה כאשר יבא אדם בצרות גדולות שנוגע לחייו ממש או לחיי ב\"ב ישב[ו]ר גסות וחוצפא דעמלק שבלבו עד שנמס והי' למים ויעשה תשובה שלימה בכל לבו, כמו מנשה ששב לאל בכל לבו<sup data-n=\"5916\">425</sup> כו'). והתיקון הב' שהוא הארת אור האלקי דרך הפרצה ממילא יבא ע\"י סיבת בחי' מ\"ה",[["5913","422","<b>ונדכה</b>: א: ניתוסף: עד שנבזה בעיניו כו'."],["5914","423","<b>עצמה</b>: א: עצומה. כא: עצמי'."],["5915","424","<b>כנ\"ל. . ביטול העצמי'</b>: כא: ליתא. וכנראה נשמט מפני תיבות הדומות: ביטול עצמי. . ביטול העצמי'."],["5916","425","<b>מנשה ששב לאל בכל לבו</b>: דהי\"ב לג, יב ואילך."]]],[2300550647,"בעצם הנ\"ל שהוא בחי' כלי לזה האור דוקא ושניהם כא' באים משום דהא בהא תליא כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש משה ליהושע בחר לנו אנשים<sup data-n=\"5917\">426</sup> וצא הלחם בעמלק בחר לנו דוקא דהיינו אותן אנשים שהן מבחי' מ\"ה דחכמה דתורה בביטול עצמי כמו ת\"ח שלומדי' התורה לשמה ולא לגרמיה לומר אין לי אלא תורה כו', וזש\"א בחר לנו שזהו כשהתורה נק' ע\"ש משה תורת משה. ומש\"א לנו לשון רבים כי גם יהושע בכלל בחי' מ\"ה זה דתורה כי נק' נער לא ימיש<sup data-n=\"5918\">427</sup> כו' כמו תושבע\"פ שמקבל מתושב\"כ כפני לבנה<sup data-n=\"5919\">428</sup> כו' וד\"ל (והתורה נצחי' היא בכ\"ד וזמן<sup data-n=\"5920\">429</sup> שיש בחי' ביטול דמ\"ה ואין בעצם ושפלות בחשבון ביטול היש לאין הנ\"ל שזהו בחי' ח\"ע וח\"ת דמשה ויהושע בחי' תושב\"כ ושבע\"פ כפני חמה שמאיר בפני לבנה, וזש\"א יהיב חכ' לחכימין<sup data-n=\"5921\">430</sup> דוקא כידוע). וזהו כללות ענין הציץ שהוא בחי' האור המאיר דרך בקיעה מן ההעלם כמו יציץ נזרו, וגם הוא ענין הבטה כמו מציץ כו' שהוא כמו הבקיעה לעשות פרצה וסדק שזש\"א מציץ מן החרכים שחרכים הללו נעשים ע\"י ענין הרהורי תשובה בבחי' לב נשבר ונדכה שנעשי' ע\"י בחי' מ\"ה בעצם דמשה דאתפשטותי' בכל דור. וזהו שא' ועשית ציץ שיעשנו משה דוקא כדי שיהי' מציץ מן החרכים שלא יפסיק מחיצה ש\"ב דעמלק כלל ויהי' השם שלם והכסא שלם כנ\"ל, וזהו שא' שהציץ הי' מכפר על עז\"פ דוקא וד\"ל. אך הנה עדיין יש להבין ענין הפי' בציץ מלשון הבטה והסתכלות מה ענין הבטה זו כמו מציץ מן החרכים דוקא כנ\"ל, ואמנם ענין הבטה זו זהו הבא מחמת רוב תגבורת האה\"ר ותשוקה גדולה ביותר אשר ע\"כ מתצמצם בעצמו לראות ולהסתכל גם דרך סדק ופרצה קטנה ביותר, וכמו האב שנתרחק ממנו בנו או אוהבו כנפשו ורוצה לראותו אף מרחוק [מאד] הנה אף שיש כותל ומחיצה מפסקת יראה בכל עוז לעשות סדקים וחרכים לראות בדרך בקיעת אור הראי' בצמצום גדול בסדק קטן הזה אחר שמשגיח מן החלונות הפתוחים כו', מזה נראה גודל עוצם עוז חיבתו וגודל תשוקתו לראות ולהסתכל באוהבו עד שעי\"ז ימשיך אה\"ר והתעוררות תשוקה גדולה באוהבו או בנו שיתקרב <span data-k=\"pg\">1102</span> ּ אליו בכל לבו ונפשו בלי הפסק כלל כו'.\n<b>וכך</b> יובן למעלה באה\"ר העליונה<sup data-n=\"5922\">431</sup> של הקב\"ה לכנס\"י שנק' בני[ם] כמ\"ש כי בנים אתם לה'<sup data-n=\"5923\">432</sup> כו' כאשר הם בגלות",[["5917","426","<b>בחר לנו אנשים</b>: בשלח יז, ט."],["5918","427","<b>יהושע. . נער לא ימיש</b>: תשא לג, יא."],["5919","428","<b>יהושע. . כפני לבנה</b>: ב\"ב עה, א."],["5920","429","<b>בכ\"ד וזמן</b>: אכא: בכל דור ו[בכל] זמן."],["5921","430","<b>יהיב חכ' לחכימין</b>: דניאל ב, כא. ראה ד\"ה זה במאמרי אדה\"א נ\"ך ע' תקכא."],["5922","431","<b>העליונה</b>: אכא: העצמי'."],["5923","432","<b>כי </b>[א: ליתא]<b> בנים אתם לה'</b>: פ' ראה יד, א [בהוספת תיבת: כי — נסמן לעיל פ' וארא פה, ג הערה 840]"]]],[2300550653,"במקום רחוק וחושך דק\"נ ע\"י העוונות וקושי לבבם נעשה כמו מחיצה ש\"ב מפסקת בינם לאביהם שבשמים<sup data-n=\"5924\">433</sup> כו' כנ\"ל, וכמש\"א הנה הוא עומד אחר כתלינ\"ו<sup data-n=\"5925\">434</sup> כו' כותל שעשינו בעצמינו להסתיר אור האלקי כו'. אך עכ\"ז מגודל האה\"ר העליונה<sup data-n=\"5926\">436</sup> שלו לבניו מתצמצם מאד בעצמו לבא ולעמוד אחר כתלינו כו'<sup data-n=\"5927\">435</sup> לראות ולהסתכל בכנ\"י אף בהיותם ברחוק מקום דרך פרצות וסדקים קטנים<sup data-n=\"5928\">437</sup> כמש\"א מציץ מן החרכים, שהוא ע\"י התעוררות עליונה שמעורר לכנס\"י בתשובה שלימה בחי' לב נשבר כנ\"ל. והיינו ע\"י מה שמביט ומסתכל בחרכי' הללו שהוא ע\"י אה\"ר ברשפי אש התשוקה ביותר מבזמן הקירוב בבהמ\"ק שהי' משגיח מן החלונות כמו בצ\"ג כנ\"ל ועי\"ז ממשיך לב כנ\"י בתשוקה ורשפי אש האה\"ר לשוב אל ה' באמת בלי שום הפסק בעולם, כי ראי' מצומצמ' זו שרואה מן החרכים ע\"י תשובה כנ\"ל יותר היא עמוקה בעוז אה\"ר בהארת הפ[נימי'] והע[צמי'] מבחי' הראי' שבקירוב בבהמ\"ק כמו בראי' דג' רגלים דכתיב יראה כל זכורך את פני הוי'<sup data-n=\"5929\">438</sup> כו', וכמו ג' מועדים עכשיו שאין אנו יכולים לעלות ולראות כו' בראי' מקרוב, וגם מלמעלה למטה אינו רק מציץ מן החרכים זהו במעלה יתירה יותר מטעם [הנ\"ל], שבזמן הריחוק מחיצה מפסקת כמו בגלות השכינה בע\"ש דנוגה שנק' לבוש שק כו' אז יש רשפי אש האהבה מן המקבל אל המשפיע כמ\"ש רשפי' רשפי אש<sup data-n=\"5930\">439</sup> כו' בזמן הגלות דוקא כמש\"א הלואי כן בקדש חזיתיך<sup data-n=\"5931\">440</sup> (כמ\"ש במ\"א בענין יו\"ט של גליות<sup data-n=\"5932\">441</sup> כו'), והיינו מצד ההבטה והסתכלות דמשפיע למקבל דרך חרכים שממשיך לב המקבל אליו כמו עיניו כיונים<sup data-n=\"5933\">442</sup> כו' ועיניך יונים<sup data-n=\"5934\">443</sup> כו' כמבואר במ\"א וד\"ל.\n<b>ובזה</b> יובן מ\"ש ועשית ציץ זהב טהור דוקא למה נעשה מן הזהב ולא מן הכסף, הלא ידוע דהכסף שרשו בבחי' החסדי'<sup data-n=\"5935\">444</sup> והזהב בבחי' הגבורות<sup data-n=\"5936\">445</sup> וכה\"ג שרשו רק בבחי' החסד<sup data-n=\"5937\">446</sup> כידוע ואיך הי' הציץ במצחו שהי' לרצון של חסד דוקא מן הזהב שהוא בחי' הגבורות ולא מן הכסף, ולמה מזהב טהור דוקא. אך הנה מבואר למעלה בשרש ענין הציץ הוא להאיר ולהמשיך בנש\"י מבחי' הארת אה\"ר העצמי' שזהו כמו מציץ מן החרכים כנ\"ל שזהו ענין הארת אור הרצה\"פ של חסד וטוב שנק' רעדכ\"ר שבמצחא דע\"י כו' (כמשי\"ת). והנה ידוע שיש ב' מיני אהבה אף ברצון שלמעלה מן השכל והטעם, א' אה\"ר שנמשך כמים בבחי' קרירות שזהו בבחי' החסדים",[["5924","433","<b>שבשמים</b>: אכא: ליתא."],["5925","434","<b>הנה הוא עומד אחר כתלינ\"ו</b>: כ\"ה גם לעיל שסט, א על יד הערה 318."],["5926","436","<b>העליונה</b>: כא: העצמי'. א: ליתא כנ\"ל הערה 435."],["5927","435","<b>כותל. . אחר כתלינו כו'</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: אחר כתלינו כו'. . אחר כתלינו כו'."],["5928","437","<b>קטנים</b>: כא: שנק' חרכים קטנים."],["5929","438","<b>יראה כל זכורך את פני הוי'</b>: פ' ראה טז, טז."],["5930","439","<b>רשפי' רשפי אש</b>: שה\"ש ח, ו. ראה לעיל שלז, ד. מאמרי אדה\"א בראשית ע' תקג. וש\"נ."],["5931","440","<b>הלואי כן בקדש חזיתיך</b>: נסמן לעיל פ' משפטים רפח, ב."],["5932","441","<b>יו\"ט של גליות</b>: ראה מאמרי אדה\"ז תקס\"ד ע' רמה. לקו\"ת שמ\"ע צב, ב."],["5933","442","<b>עיניו כיונים</b>: שה\"ש ה, יב. ראה גם מאמרי אדה\"א בראשית ע' תקעג. לעיל של, ב."],["5934","443","<b>ועיניך יונים</b>: שה\"ש א, טו. ד, א."],["5935","444","<b>דהכסף. . החסדי'</b>: ראה זהר (רע\"מ) תצא רעז, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061170\" data-slug=\"likkutei-sichot\" data-id=\"1300061170\">לקו\"ש תרומה כרך ו ע' 159</a> הערה 51. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמג ובהנסמן במ\"מ לשם."],["5936","445","<b>והזהב בבחי' הגבורות</b>: ראה ת\"ז תכ\"ד (סט, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021361\" data-slug=\"likkutei-sichot\" data-id=\"1300021361\">לקו\"ש שם</a>. מאמרי אדה\"א שמות ח\"ב ע' תרלז. וש\"נ."],["5937","446","<b>וכה\"ג. . החסד</b>: ראה מגיד משרים פ' נצבים ד\"ה אבל רזא דמלתא דזרוע (קמג, א). פרדס (שער עה\"כ) שכ\"ג מערכת כהן גדול."]]],[2300550659,"שיורדים מגבוה לנמוך כמו אה\"ע אהבתיך ע\"כ משכתיך חסד, שמפני בחי' אה\"ע דרב חסד בחי' אה\"ר<sup data-n=\"5938\">447</sup> העצמי' משכתיך בחסד זה לעורר את האה\"ר בלב כנ\"י שזהו בחי' כח המושך את הלב באה\"ר שנמשך כמים דוקא, כמו אב הרחמן המדבר דברי אהבה וחסד וטוב בדברי ריצוי מאד בנקודת הלב שנק' המשכת הלב כמים הנמשכים שמזה ימשיך לב בנו האהוב אליו לקשרו בעבותות האהבה בל ימוט ממנו<sup data-n=\"5939\">448</sup> לעולם, וזהו משכתיך כו' וכן משכני אחריך נרוצה <span data-k=\"pg\">תקנא</span> ּ וכה\"ג. וזהו בחי' אה\"ר דכה\"ג שמעורר את האהבה והתשוקה בלב כנ\"י כנ\"ל, אבל הנה זהו בבחי' קרירות כמים בחסד ורצון הטוב שיש שיעור בכח המשכתו למטה לעשות רושם בלב כנ\"י, ויכול להיות שיופסק כח זה שלא יפעול לפעמים התעוררות האהבה או התשוקה בכנ\"י כמו שאמר<sup data-n=\"5940\">449</sup> שב\"ק מכרזת בכל יום שובו בנים כו' ולא הכל מתעוררים בתשובה כו'. ואמנם אה\"ר הב' הוא אה\"ר שבבחי' הגבורות שהוא בבחי' רשפי אש התשוקה בהתלהבות שעושה רושם גדול בלב האהוב השומע כמו דברים שיוצאים מן הלב ברשפי אש ולהב נכנסים [יותר] ללב השומע ועושה בכח<sup data-n=\"5941\">450</sup> המושך את הלב אשר יתלהב גם הוא בחשק ותשוקה ברשפי אש לצאת מכל כלי גופו ליכלל ולידבק במשפיע בלי שיעור והפסק כלל וכלל. וכך הוא למעלה בהמשכת אה\"ר שבבחי' גבורות, דזהו יתרון מעלת הזהב על הכסף שעושה התעוררות אה\"ר ברשפי אש בלב כנ\"י בלהב העולה תמיד למעלה במס\"נ ולא יופסק לעולם כי בבחי' אה\"ר שברצון הע[צמי] שברשפי אש אין לה שיעור<sup data-n=\"5942\">451</sup> והפסק כלל (וכמו שאין האשה כורתת ברית<sup data-n=\"5943\">452</sup> אלא למי שעשאה כלי ברוחא דשביק בגווה<sup data-n=\"5944\">453</sup> בבחי' הגבורות דרשפי אש הת\"ע<sup data-n=\"5945\">454</sup> כו' עד שאל אישה תשוקתה בתמידות בל[י] יופסק לעולם כו'. וכמו\"כ עיני\"ו כיוני\"ם ועיני\"ך יוני\"ם שמסתכלים זב\"ז ברשפי אש האהבה שאין לה שיעור להיות מבחי' הפנימי' ועצמי' ממש כו'.\n<b>וכך</b> הוא ג\"כ ענין וטעם בענין הציץ שהי' מזהב טהור דוקא ולא מכסף דבחי' הגבו' דזהב יש בו יתרון מעלה הרבה על החסד דכסף בקרירות כנ\"ל, וע\"כ הי' בחי' ההבטה והסתכלות הרצון הטוב מלמעלה למטה בכנס\"י בציץ זה בבחי' הגבורות ברשפי אש התלהבות האה\"ר בת\"ע<sup data-n=\"5946\">455</sup> שאין לה הפסק ושיעור כלל לעורר את האהבה רבה ברשפי אש בכנ\"י מלמטה למעלה כמ\"ש רשפיה רשפי אש שלהבת י\"ה [(ו]נק' אש\"ה א\"ש ה' שהוא שנק' עולת תמיד כו' לפי שמאיר מן המשפיע אל",[["5938","447","<b>דרב חסד בחי' אה\"ר</b>: כא: ליתא."],["5939","448","<b>ממנו</b>: אכא: ליתא."],["5940","449","<b>כמו שאמר</b>: א: כמ\"ש. כא: כמו שאנו רואים."],["5941","450","<b>בכח</b>: א: בו כח. כא: כמו כח."],["5942","451","<b>שיעור</b>: א: מיעוט."],["5943","452","<b>שאין האשה כורתת ברית</b>: סנהדרין כב, ב."],["5944","453","<b>ברוחא דשביק בגווה</b>: ראה זהר (סבא) משפטים צט, ב. מאמרי אדה\"א הנחות תקע\"ז ע' צט, וש\"נ. ש\"א כז, ב הערה 30."],["5945","454","<b>הת\"ע</b>: אכא: התענוג."],["5946","455","<b>בת\"ע</b>: א: בתשוקה עצומה. כא: בתענוגים."]]],[2300550665,"המקבל בבחי' רשפי אש שנק' אי\"ש א\"ש י'<sup data-n=\"5947\">456</sup> כו') ועל בחי' רשפי אש הנ\"ל<sup data-n=\"5948\">457</sup> האה\"ר בתענוגי'<sup data-n=\"5949\">458</sup> כזאת אמ\"ר<sup data-n=\"5950\">460</sup> לא יוכלו לכבות<sup data-n=\"5951\">461</sup> את האהבה כו' (ולפי שאינו בבחי' אש שיכבה אותו המים כי זהו בחי' אור הת\"ע באה\"ר בשעה<sup data-n=\"5952\">459</sup> שהן בבחי' גבורות שבעצמות התענוג ורצה\"פ) שאין לו מנגד כלל דהיינו שלא יש רצון המנגד לרצון העצמי הזה עד שלא יביט לדין וחוב כלל כמש\"א לא הביט און ביעקב<sup data-n=\"5953\">462</sup> כו' ה\"א עמו ממש ותרוע\"ת מלך בו מרעוא דכ\"ר כו'. וזהו בחי' זהב טהור דוקא שטהור מכל סיג לגמרי כמו טהור עינים מראות ברע<sup data-n=\"5954\">463</sup>, שלא חפץ לראות ברע כלל דהיינו שלא ירצה לשמוע למקטרג כלל ע\"כ א' ולא אבה ה' לשמוע אל בלעם<sup data-n=\"5955\">464</sup> ויהפוך הוי'<sup data-n=\"5956\">465</sup> את הקללה לברכה כי אהבך ה' אלקיך בבחי' אה\"ר בתענוגי' הע'<sup data-n=\"5957\">466</sup> כאהבת עצמו ממש, שאין אדם רואה חוב לעצמו כלל. ואף שיודע בעצמו חוב נעשה כזכות ממש עד שאינו רואה עליו חוב כלל, כך הוא במ\"ש לא הביט און ביעקב מצד אה\"ר העצמי' שמביט עליו רק בעין טובה ואינו רואה חוב כלל, וכמו הבן לגבי האב דאם אהבת אביו <span data-k=\"pg\">1104</span> ּ אליו בע[צמו'] נפשו וכמו ונפשו קשורה<sup data-n=\"5958\">467</sup> כו' ברשפי אש התענוג בעצם עד שתכלה נפשו אליו, אז אפילו הבן שעושה נגד רצונו בתכלית ומכעיסו במעשיו המכוערים ירבה לסלוח לו ולא יראה עליו חוב כלל, לפי שתמיד ירצה לו כמו כאב את בן ירצה<sup data-n=\"5959\">468</sup> בתמידות בלי ביטול מכל דבר כו'. וכך הוא כאן בענין ההבטה והסתכלות שמציץ מן החרכים ברשפי אש האה\"ר כו' מצד התקשרות כל עצמותו ית' בכנ\"י עד שהוא רק ברצון טוב להם ואין לו מנגד ברצון אחר לחוב כלל וכלל כנ\"ל במ\"ש לא הביט און כו' ולא כמ\"ש וירא און<sup data-n=\"5960\">469</sup> רק שלא יתבונן אלא הוא טהור עינים מראות ברע דישראל שאינו רואה אותו כלל. והיינו בחי' זהב טהור דציץ שעשה משה דוקא שיהי' על מצח אהרן כה\"ג דוקא שהוא הממשיך ומעורר את האהבה רבה בנש\"י ונק' שושבינא דמטרוניתא כו', שהי' מזהב טהור בבחי' הגבורות דרשפי אש העונג ורצה\"פ דבחי' רעדכ\"ר שהוא לרצון תמיד לפני ה' בלי שינוי והפסק לעולם כנ\"ל כמו שאב את בן ירצה תמיד, ולא יש שינוי רצון<sup data-n=\"5961\">470</sup> אחר כלל אף שעושה נגד רצונותיו תמיד מטעם הנ\"ל וד\"ל. ואמנם צ\"ל ציץ זה על מצח אהרן דוקא ואז יהי' לרצון תמיד דוקא כנ\"ל שזהו התנאי הב' הנ\"ל וא[ם] ל[א] הי' על מצח אהרן כה\"ר שהוא הכח המעורר וממשיך לב כנס\"י מלמטה למעלה לא הי' מועיל מעשה הציץ מצד עצמו אף ע\"י משה להיות לרצון תמיד על כנ\"י למטה ממש וד\"ל.",[["5947","456","<b>אש\"ה א\"ש ה'. . אי\"ש א\"ש י'</b>: ראה גם לעיל פ' בשלח רלח, ב. וש\"נ."],["5948","457","<b>הנ\"ל</b>: אכא: ליתא."],["5949","458","<b>בתענוגי'</b>: א: בתשוקה עצומה."],["5950","460","<b>אמ\"ר</b>: א: אמר מים רבים."],["5951","461","<b>מים רבים לא יוכלו לכבות</b>: שה\"ש ח, ז."],["5952","459","<b>כזאת. . בשעה</b>: כא: ליתא."],["5953","462","<b>לא הביט און ביעקב</b>: בלק כג, א."],["5954","463","<b>טהור עינים מראות ברע</b>: חבקוק א, יג. [ושם: רע — ראה לעיל פ' בא קכג, ד הערה 468]."],["5955","464","<b>ולא אבה ה' </b>[כא: ניתוסף: אלקיך]<b> לשמוע אל בלעם</b>: תצא כג, ו [בדילוג]."],["5956","465","<b>הוי'</b>: אכא: ליתא."],["5957","466","<b>הע'</b>: א: העצמי'. כא: ליתא."],["5958","467","<b>נפשו קשורה</b>: ויגש מד, ל."],["5959","468","<b>כמו </b>[כא: ליתא]<b> כאב את בן ירצה</b>: משלי ג, יב [ושם: וכאב — וכ\"ה לקמן שעח, ב]."],["5960","469","<b>וירא און</b>: איוב יא, יא. ראה מאמרי אדה\"א קונטרסים ע' שכב. וש\"נ."],["5961","470","<b>רצון</b>: כא: ליתא."]]],[2300550671,"ופתחת עליו פתוחי חותם<sup data-n=\"5962\">471</sup> קדש לה', הנה ממש\"א ופתחת עליו פתוחי חותם משמע<sup data-n=\"5963\">472</sup> פשוטו שלא היו האותיות הללו דקדש לה' בחקיקה ע'<sup data-n=\"5964\">473</sup> בתוך הציץ, דהיינו לא שנחקק ונחרץ בגופו ומהותו של הציץ אלא נחקק בו פתוחי חותם שהי' נחתם ונחקק בו אותיות הללו דקדש לה'. וזהו ופתחת עליו פתוחי חותם כמו שחותמי' בחותם הטבעת על השעוה שאותיות שבשעוה שנחקקו מאותיות של החותם עצמו הוא דבר נבדל מן העצם, כי [ה]אותיות שבגוף החותם הן אותיות ע[צמיי'] שנק' צלם וצורה ע[צמי'] אבל האותיות שנחקקו ממנו בשעוה הן מהות אחר נבדל ממנו<sup data-n=\"5965\">474</sup> לגמרי ונק' בשם דמות ולא צלם, כידוע בענין נעשה אדם בצלמנו כדמותנו שזהו ההפרש בין צלם ודמות<sup data-n=\"5966\">475</sup>. וגם כאן אותיות דקדש לה' שנחקק בציץ נפתחו עליו [כ]פתוחי אותיות החותם שנחקקו בו אותיות הללו בחריצה וחקיקה ע[צמי'], שנמצא קדש לה' שנכתב בציץ נק' דמות לבד שהן רק בדוגמא לבד לאותיות הע[צמי'] שבחותם עצמו. ובאמת מ\"ש ל' פתוחי חותם היינו ש[י]הי' חקיקה זו עצמית כחקיקת [אותי'] החותם, וזה[ו] פי' הפשוט ופתחת עליו כמו פתוחי חותם (שאם הי' ע\"י חקיקה מחותם או דפוס הרי הי' נעשה אותיות שקועים בציץ מבליטה של אותיות החותם או הדפוס [ו]כמו שימני כחותם על לבך<sup data-n=\"5967\">476</sup> כמבואר במ\"א, שזה צ\"ל ע\"י הכאה בציץ ממתכת קשה שהוא הי' פתוח בפתוחי חותם באותיות<sup data-n=\"5968\">477</sup> הללו באותיות בולטים כי א\"א להיות<sup data-n=\"5969\">478</sup> בהיפך מזה שאותיות שקועים יהיו אותיות בולטים בציץ (והיינו החילוק שבין דעת הרמב\"ם להראב\"ד עיין בפ\"ט מהל' כלי המקדש<sup data-n=\"5970\">479</sup> שהרמב\"ם כ[תב] <span data-k=\"pg\">תקנב</span> ּ שאותיות בולטות מלפניו ע\"י שחופר את האותיות מאחריו עד שבולט (שזהו כעין חקיקה עצמי' הנ\"ל), והראב\"ד כתב שם אינו חופר אלא מכה בדפוס צורות האותיות מאחריו עד שהאותיות בולטות מלפניו (שזהו כחותם הטבעת שחוקק בו באותיות בולטים בשעוה וכה\"ג). והנה ב' הדיעות וב' הפי' אמת, ויהי' איך שיהי' עכ\"פ באותיות הנחקקים מן החותם אין שום שינוי וגרעון בדבר שנחקק בו אפילו כקש\"י כי כל אות ואות כמו שהוא בחותם עצמו כך הוא ממש בדבר שנחקק בו כדמותו כצלמו ממש.\n<b>וכך</b> יובן ג\"כ במ\"ש ופתחת עליו פתוחי חותם כו' דהנה ארז\"ל חותמו של הקב\"ה אמת<sup data-n=\"5971\">480</sup> ואין אמת אלא תורה<sup data-n=\"5972\">481</sup> כו', והיינו שגופו של חותם העליון שחקוקים בו אותיות עצמי' היינו אותיות התורה דוקא שנק' אמת, שכללותם הן כ\"ב אותיות ובחי'",[["5962","471","<b>ופתחת עליו פתוחי חותם</b>: המשך הכתוב ועשית ציץ (תצוה כח, לו)."],["5963","472","<b>משמע</b>: כא: ליתא."],["5964","473","<b>ע'</b>: א: עצמה. כא: עצמי'."],["5965","474","<b>ממנו</b>: שם: ליתא."],["5966","475","<b>נעשה אדם. . צלם ודמות</b>: בראשית א, כו. ראה גם לעיל פ' בשלח קמא, ג."],["5967","476","<b>שימני כחותם על לבך</b>: שה\"ש ח, ו. ראה סידור שער התפילין טו, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381308\" data-slug=\"likkutei-torah\" data-id=\"4001381308\">לקו\"ת שה\"ש מה, א</a>. אמ\"ב שער התפילין צז, ג."],["5968","477","<b>חותם באותיות</b>: א: אותיות."],["5969","478","<b>להיות</b>: א: לומר."],["5970","479","<b>בפ\"ט מהל' כלי המקדש</b>: הלכה ב."],["5971","480","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["5972","481","<b>ואין אמת אלא תורה</b>: ראה ירושלמי ר\"ה פ\"ג, ה\"ח. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שסט."]]],[2300550676,"רת\"ס שבהן הוא אותיות אמת<sup data-n=\"5973\">482</sup> א' מ' ת' שכולל כל הכ\"ב אותיות שבחותם שנק' חותמו<sup data-n=\"5974\">483</sup> של הקב\"ה בכלל. וזש\"א שכל הקורא בתורה קורא בשמותיו של הקב\"ה זהו בבחי' שמותיו העצמיי' שהוא כמו החותם שבו נחקק שמו הע[צמי] לקיים כל דבר הנכתב ונעשה בפו\"מ הכל הוא ע\"י החותם דוקא. ולמעלה יובן מזה ששמו ית' העצמי הוא שם הוי' שבתורה דוקא שע\"ז א' ושמי הוי'<sup data-n=\"5975\">484</sup> כו' שנק' אמת, וזש\"א בראשית בשביל התורה כו' שנא' ה' קנני ראשית כו' דבחי' קנין שמים וארץ<sup data-n=\"5976\">485</sup> בכללות דמע\"ב הי' ע\"י בחי' החותם דשם הוי' שנחתם בתורה, כמו אותיות החותם שנחקק בדבר מה הנפרד כך הוא בבחי' צירופי אותיות במע\"ב ששרשם הוא מאותיות שבתו' שכללותם נק' אמת כנ\"ל וד\"ל. וכמו שאין שינוי כלל באותיות הנחקקי' שבשעוה שהן כדוגמא דאותיות החותם ממש כך אותיות די\"מ נמשכו מאותיות התורה (משם הוי' באלקי' כמ\"ש ביום עשות ה' אלקים<sup data-n=\"5977\">486</sup> כו' ) [כמו] המסתכל בלוח ובונה שבונה ממש כפי הציור הנעשה בלוח בלי שינוי (והיינו מה ששיער בעצמו בכח<sup data-n=\"5978\">487</sup> מה שעתיד להיות בפועל בע\"ס דאצי' ובי\"ע והוא מ\"ש דגליף גליפו בטה\"ע<sup data-n=\"5979\">488</sup> כו' כמבואר במ\"א). וזהו ואהי' אצלו אמון אומנא<sup data-n=\"5980\">489</sup> כו' וכתיב אם לא בריתי<sup data-n=\"5981\">490</sup> כו' חוקות שמים וארץ כו' וגם עכשיו אמר ודברי אשר שמתי<sup data-n=\"5982\">491</sup> בפיך כו' לנטוע שמים וליסוד ארץ כמ\"ש ה' בחכ' יסד ארץ<sup data-n=\"5983\">492</sup> בחכמה דתורה דוקא וד\"ל. וזהו שאומרים בקידוש הלבנה פועל אמת שפעולתו אמת, משום דאיהו אמת ואיהי אמונה<sup data-n=\"5984\">493</sup> דהיינו בחי' חותם באותיות העצמי' דתורה נק' אמת ופועל אמת להאציל ע\"ס בבחי' רת\"ס באו\"כ כו', כמו ששיער בעצמו בכח באותיות דטה\"ע שהן בבחי' אותיות דתוה\"ק הנ\"ל. ופעולתו אמת הוא בבחי' המל' בבי\"ע זהו דאיהי אמונה שזהו אתוון אתגליפו<sup data-n=\"5985\">494</sup> בדבר נבדל כפני לבנה שמקבל מפני חמה שזהו בצלמנו כדמותנו (כמשי\"ת).\n<b>אך</b> כ\"ז רק<sup data-n=\"5986\">495</sup> בבחי' חיצוני' השפע כמו משל בנין בית בחכמה כך מע\"ב נק' בשם עשי' שנעשי' בצירופי אותיות די\"מ<sup data-n=\"5987\">496</sup> כמו יהי אור יהי רקיע<sup data-n=\"5988\">497</sup> וכה\"ג כל ריבוי הצירופי' שכולם בחכמה עילאה<sup data-n=\"5989\">498</sup> בחכמה<sup data-n=\"5990\">499</sup> דתורה (ויש בזה ד' מדרגות מן המאציל לאצי'<sup data-n=\"5991\">500</sup> ומאצי' לבריאה ומבריאה ליצי' ומיצי' לעשי', שזהו <span data-k=\"pg\">1106</span> ּ כמו מאותיות החותם נחקק בדבר מה ומאותו דבר נחקק בדבר זולתו, כמו אותיות המחשבה שנחקקי' באוה\"ד ומאוה\"ד<sup data-n=\"5992\">501</sup> באותיות הכתב שנק' הארה דהארה מן המח', וכך צורה שני' מצורה [ה]ראשונה כמו שהוא מאין דאצי' ליש דבריאה במח' כך",[["5973","482","<b>רת\"ס. . אמת</b>: נסמן לעיל שלא, ג."],["5974","483","<b>שנק' חותמו</b>: כא: ליתא."],["5975","484","<b>ושמי הוי'</b>: וארא ו, ג."],["5976","485","<b>קנין שמים וארץ</b>: ראה אבות פ\"ו, י."],["5977","486","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד."],["5978","487","<b>ששיער בעצמו בכח</b>: נסמן לעיל שכה, ד."],["5979","488","<b>דגליף גליפו בטה\"ע</b>: זהר בראשית טו, א."],["5980","489","<b>ואהי' אצלו אמון אומנא</b>: משלי ח, ל. ב\"ר בתחלתו."],["5981","490","<b>אם לא בריתי</b>: ירמי' לג, כה."],["5982","491","<b>ודברי אשר שמתי</b>: כא: ואשים דברי."],["5983","492","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["5984","493","<b>דאיהו אמת ואיהי אמונה</b>: ראה זהר (רע\"מ) פינחס רל, א. בלק קצח, ב. לקו\"ת ואתחנן ה, רע\"ג. מאמרי אדה\"א ויקרא ח\"א ס\"ע צג ואילך."],["5985","494","<b>אתוון אתגליפו</b>: ראה זהר בראשית טו, ב. שעה\"י קמא, ב בהערה 46."],["5986","495","<b>רק</b>: כא: ליתא."],["5987","496","<b>די\"מ</b>: א: ליתא."],["5988","497","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["5989","498","<b>שכולם בחכמה עילאה </b>[כא: עשית]: תהלים קד, כד."],["5990","499","<b>בחכמה</b>: א: ליתא."],["5991","500","<b>לאצי'</b>: כא: לנאצלים."],["5992","501","<b>באוה\"ד ומאוה\"ד</b>: אכא: באותיות הדיבור ומאותיות הדיבור."]]],[2300550681,"הוא מן המאציל לאצי' בבחי' שמות דע\"ב ס\"ג כו'). אבל בבחי' פנימי' ועצמי' האור דא\"ס שלמעלה מן ההשתל' דעולמות ז\"ש נעשה אדם בצלמנו כדמותנו כו', דבאמת מצד עא\"ס<sup data-n=\"5993\">503</sup> לאו מכל אינון מדות כלל ולא<sup data-n=\"5994\">502</sup> נק' אדם כמ\"ש כי לא אדם<sup data-n=\"5995\">504</sup> הוא, רק שנאצל מן העצמות בציור אדם פ[נימי], והוא אותיות רת\"ס דאמת דתוה\"ק שנק' אדם כמ\"ש זאת תורת האדם<sup data-n=\"5996\">505</sup> בחכמה ומדות כו' בבחי' צורה עצמי' ממש כמו ושמי הוי' כו' שלמעלה מהיות מקור למדות דאצי' לאחזאה לאתנהגא<sup data-n=\"5997\">506</sup> כו', ומאדם זה נחקק אותיות בחו\"מ<sup data-n=\"5998\">507</sup> בבחי' יצי' כמ\"ש בראתי\"ו יצרתי\"ו<sup data-n=\"5999\">508</sup> והן נש\"י ש[הן] נק' אד\"ם בצלם אלקי'<sup data-n=\"6000\">509</sup>, ואח\"כ נמשך עוד בבחי' עשי' למטה ממש והן התו\"מ שהן בחי' החכמה שבראש ורמ\"ח אברים רמ\"ח מ\"ע<sup data-n=\"6001\">510</sup> באד\"ם דעשי' הנגלית לנו לעשות בפו\"מ ותורה דאצי' נק' אד\"ם דאצי' ובריאה נק' אד\"ם דבריאה כו', ובכלל בחי' א\"ק נק' אד\"ם דבריאה<sup data-n=\"6002\">511</sup> כידוע. אבל עצמות א\"ס ב\"ה ממש למעלה גם מבחי' פנימי' דחכ' ומדות דתוה\"ק הנ\"ל, וכמ\"ש ולאו מכא\"מ כלל כו'. רק עכ\"ז נק' חותמ\"ו ממש לפי שמתצמצם ומתלבש באותיות התו' שנק' אמ\"ת כנ\"ל [וכמ\"ש] נעשה אד\"ם בצלמנו כו' שנק' אדם דעשי' ואדם דיצי' ובריאה עד גם בחי' אדם דאצי' בפנימי' דחו\"מ<sup data-n=\"6003\">512</sup> דתורה אינו רק בחי' החותם שלו לבד, רק שהן בחי' אותיות משמותיו העצמיי' שבבחי' פ[נימי'] זו נשתלשלה התו\"מ למטה שהן ג' קשרי' דישראל מתקשראן באורייתא בבחי' סתים וגליא כמו שנחקקו בחותם כמ\"ש שימני כחותם על לבך שזהו כחותם שבשעוה בדוגמא לאותיות החותם הע' דתורה מאותיות דתורה<sup data-n=\"6004\">513</sup> מתקשראן בקוב\"ה עצמו שנק' סדכ\"ס כו', ובחי' חיצוניות השפע הוא שנמשך מזה שרש ההשתל' באותיות החותם העליון דתוה\"ק באבי\"ע להיות מקור להנהגת העולמות וקיומם התמידית מאין ליש כנ\"ל וד\"ל.\n<b>והנה</b> בכ\"ז יובן מ\"ש כאן ופתחת עליו פתוחי חותם דעליו משמע שעל הציץ נחקק באותיות החותם וא' פתוחי חותם סתם שזהו בחי' חותמו של הקב\"ה שנק' אמת כו', והוא בחי' החו\"מ דתוש\"מ והמצות שבאים בציור אדם ברמ\"ח אברי' שנק' רמ\"ח אברים דמלכא<sup data-n=\"6005\">514</sup> למעלה בבחי' אדה\"ע דאצי' כנ\"ל בענין נעשה אדם בצלמנו כדמותנו, שבד\"כ<sup data-n=\"6006\">515</sup> בחי' צל\"ם שהוא צורה הע[צמי'] בחקיקת א[ותי'] אותיות ע[צמיי'] זהו אותיות התוה\"ק שבמח' הקדומה וירדה באצי' בבחי' או\"כ שנק' רמ\"ח",[["5993","503","<b>עא\"ס</b>: כא: עצמות א\"ס."],["5994","502","<b>האור. . ולא</b>: א: ליתא."],["5995","504","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["5996","505","<b>זאת </b>[כא: וזאת]<b> תורת האדם</b>: נסמן לעיל פ' משפטים רפז, ג."],["5997","506","<b>לאחזאה לאתנהגא</b>: ראה ת\"ז בהקדמה (יז, ב)."],["5998","507","<b>בחו\"מ</b>: כא: בחכ' ומדות."],["5999","508","<b>בראתי\"ו יצרתי\"ו</b>: ישעי' מג, ז."],["6000","509","<b>נש\"י ש[הן] נק' אד\"ם בצלם אלקי'</b>: יבמות סא, א. בראשית א, כז. נח ט, ו."],["6001","510","<b>ורמ\"ח אברים רמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["6002","511","<b>א\"ק נק' אד\"ם דבריאה</b>: ראה גם לעיל פ' בשלח קמה, ג. וש\"נ."],["6003","512","<b>דחו\"מ</b>: א: דחכ' ומדות. כא: דתו\"מ(!)."],["6004","513","<b>הע'. . דתורה</b>: א: דתורה. כא: העצמי דתורה ומאותיות דתורה."],["6005","514","<b>רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["6006","515","<b>שבד\"כ</b>: א: ליתא. כא: שבדרך כלל."]]],[2300550686,"אברים כו', וכאשר יורדים ונמשכים למטה ממש בכנ\"י<sup data-n=\"6007\">516</sup> זהו כמו ענין החקיקה מגופו של חותם שחותמי' בדבר [נבדל] זולתו שהן בדוגמא ממש לאותיות החותם, והיינו בחי' ך\"ב אותיות התורה בכלל שבאו באותיות<sup data-n=\"6008\">517</sup> בכתב למטה ממש וברמ\"ח מ\"ע שבאים למעשה בפו\"מ בפרט (שנק' אדם דעשי' בחיצוניות כמ\"ש אף <span data-k=\"pg\">תקנג</span> ּ עשיתיו<sup data-n=\"6009\">518</sup>, וזהו אמ\"ת רת\"ס ג' מיני אדם פנימי א[מצעי] וח[יצון] שנמשך מלמעלה גם מבחי' אדם פ[נימי] דתו\"מ מעצמו' א\"ס ממש כנ\"ל) (אבל כ\"ז הוא דוקא בבחי' פנימי' ועצמי' דאד\"ם אדמ\"ה לעליון<sup data-n=\"6010\">519</sup> ממש בצלם ודמות כו' שבזה נכלל כל בחי' עצמו' ממש, וכמו שמו הע[צמי] שבחותם שלו שמקיים כל אשר ברצונו ותו\"מ<sup data-n=\"6011\">520</sup> הע[צמי'] והן ג' קשרים הנ\"ל דישראל ואוריי' וקוב\"ה בב' מדרגות דסתים וגליא פו\"ח<sup data-n=\"6012\">521</sup> והממוצע שנכלל באמ\"ת זה כנ\"ל. והן כמו<sup data-n=\"6013\">522</sup> יוה\"ד<sup data-n=\"6014\">523</sup> שהיו בדבור בבחי' יצי' שהוא בחי' הגילוי מן ההעלם דמחה\"ק דתוה\"ק הנ\"ל ובאו הדברות בכתב חרות על הלוחות<sup data-n=\"6015\">524</sup> כו' בבחי' עשי' שזהו ג\"כ ענין ג' מיני אדם דבי\"ע בכלל עד עצמו' א\"ס שלמעלה מבחי' אד\"ם לגמרי כנ\"ל (והיינו מה שנסתם<sup data-n=\"6016\">525</sup> על הציץ בפתוחי חותם הזה רק ב' תיבות הללו דקד\"ש להוי' דוקא שהוא שם הוי' דתו\"מ (שלא נודע גם לאבות<sup data-n=\"6017\">526</sup> שהן המרכבה לחג\"ת<sup data-n=\"6018\">527</sup> דז\"א עד חג\"ת דע\"י וא\"ק<sup data-n=\"6019\">528</sup> כו' וד\"ל), שז[הו] שא' בזהר עמ\"ש אין קדוש כהוי'<sup data-n=\"6020\">529</sup> ישראל קדישין ואורייתא קדישא דבישראל א' קדש [ישראל] להוי'<sup data-n=\"6021\">530</sup> כו', ובתורה יש קדושת שם הוי' בעצם ונק' תורת הוי'<sup data-n=\"6022\">531</sup> ממש וכן<sup data-n=\"6023\">532</sup> מצות הוי'<sup data-n=\"6024\">533</sup>, ועכ\"ז אין קדוש כהוי' עצמו שכלולי' בו ב' קדושות הללו דאורייתא וישראל משום דג' קשרין הן שמתקשראן כחדא ממש כנ\"ל בג' מיני אדם שזהו בחי' רת\"ס דאמ\"ת (כמ\"ש דאיהו אמ\"ת ואיהי אמונ\"ה שמקבל לבחי' האמ\"ת כנ\"ל), והיינו שנפתח בפתוחי חותם רק קד\"ש להוי' שכולל לג' קדושות דישראל ואורייתא וקוב\"ה, שזהו עיקר בחי' החותם שהוא בחי' ההבדלה בין פנימי' לחיצוניות להבדיל בין קדש לחול שזהו עיקר בחי' אד\"ם בתו\"מ למעו\"ט<sup data-n=\"6025\">534</sup> שהוא בדומה לעליון ממש כנ\"ל, משא\"כ בחי' חיצוני' השפע שנמשך בשביל בנין העולמות בכלל ובפרט ע\"י האותיות דחותם דתורה וישראל כמו בראשית בשביל התורה כנ\"ל שנבדל מן הפנימי' וד\"ל). ואע\"פ שגם בתו\"מ שלמעלה באצי' וכ\"ש למטה בכנ\"י בא ע\"י חקיקה מגופו של חותם בבחי' דמות כמו אדם בחיצוניות כנ\"ל, עכ\"ז הכל הוא מתאחד כא' בבחי' הפנימי' ועצמי' דאדם כולל רת\"ס כא' [ממש] כו' וכמ\"ש כל הנק' בשמי ולכבודי<sup data-n=\"6026\">535</sup>",[["6007","516","<b>ממש בכנ\"י</b>: כא: בפו\"מ."],["6008","517","<b>באותיות</b>: שם: ליתא."],["6009","518","<b>אף עשיתיו</b>: ישעי' מג, ז."],["6010","519","<b>דאד\"ם אדמ\"ה לעליון</b>: נסמן לעיל פ' יתרו רסב, א."],["6011","520","<b>ותו\"מ</b>: אכא: וחכמתו ומדותיו."],["6012","521","<b>פו\"ח</b>: שם: פנימי' וחיצוני'."],["6013","522","<b>כמו</b>: כא: ליתא."],["6014","523","<b>יוה\"ד</b>: אכא: יו\"ד הדברות."],["6015","524","<b>חרות על הלוחות</b>: תשא לב, טז."],["6016","525","<b>שנסתם</b>: אכא: שנכתב."],["6017","526","<b>שם הוי'. . שלא נודע גם לאבות</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. לעיל פ' יתרו רנא, ב הערה 16."],["6018","527","<b>לאבות. . לחג\"ת</b>: ראה גם לעיל פ' וארא סא, ד. וש\"נ."],["6019","528","<b>לאבות. . חג\"ת דע\"י וא\"ק</b>: ראה גם לעיל פ' בשלח קנח, ב. הערה 405."],["6020","529","<b>אין קדוש כהוי'</b>: שמו\"א ב, ב. ראה זהר תזריע מד, א. לעיל פ' בשלח קנט, ג. וש\"נ."],["6021","530","<b>קדש [ישראל] להוי'</b>: ירמי' ב, ג."],["6022","531","<b>תורת הוי'</b>: בא יג, ט."],["6023","532","<b>וכן. . ממש</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: ממש. . ממש."],["6024","533","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["6025","534","<b>למעו\"ט</b>: אכא: למעלה ולמטה."],["6026","535","<b>כל הנק' בשמי ולכבודי</b>: ישעי' מג, ז."]]],[2300550691,"ממש בראתי\"ו יצרתי\"ו אף עשיתיו, דגם בעשי' הוא כמו בבריאה ובעצמו' שמו ממש שאין להבדיל ולחלק בבחי' אד\"ם בין פנימי' לחיצוניות כמ\"ש בצלמנו כדמותנ\"ו שהכל א'. וכמו שרואים בחוש באדם התחתון בפנימי' אדם שבו בחו\"מ שנמשך עד בחי' חיצוני' שבו ברמ\"ח אברים אין חילוק כלל (וכמו שמרגיש האדם א\"ע מפנימי' הרצון [עד סוף] מעשה ברגל כו') (משא\"כ בחיצוניות דאד\"ם במעשה לבד נבדל הוא מן הפנימי' שבו בחו\"מ שבלב, וזהו דוקא לענין [ה]השתלשלו' דמע\"ב שנמשך מחיצוניו' דחו\"מ הנגבל<sup data-n=\"6027\">536</sup> בערך מן הפנימי' כנ\"ל וד\"ל) (ולא עוד אלא שבסומ\"ע<sup data-n=\"6028\">537</sup> דאדם חיצוני בתו\"מ הנגלית לנו כו' שורה מתחלת התחלת דעצמי' א\"ס שבפנימי' דח\"ע כמ\"ש סוף דבר כו' כי זה כל האד\"ם<sup data-n=\"6029\">538</sup> הע[ליון] יותר וז\"ש אף עשיתיו לרבותא<sup data-n=\"6030\">539</sup> כידוע).\n<b>ומעתה</b> יתורץ ענין הב' הדיעות הנ\"ל באופן החקיקה דקדש לה' בציץ אם שחופר <span data-k=\"pg\">1108</span> ּ באחוריו עד שבולט[ו]ת האותיות (כדעת הרמב\"ם כנ\"ל) או שמכה בדפוס בצורת האותיות מאחוריו עד שבולטי' האותיות מלפניו (כדעת הראב\"ד כנ\"ל). דהנה מבואר למעלה [בעיקר] ענין הציץ שכולל ב\"ד<sup data-n=\"6031\">540</sup>, א' ענין הארה בדרך בקיעה מן ההעלם כו' (והב' כמו ענין הבטה והסתכלות דרך פרצה כו' כנ\"ל<sup data-n=\"6032\">541</sup> ), וזהו ענין הארת אור דתורה שנמשך מעצמו' א\"ס ממש דקמי' גם חושך לא יחשיך כו' (שבוקע ההעלם והחושך דקליפת עמלק שהוא עזות פנים שבמצח כמו ומצחך נחושה<sup data-n=\"6033\">542</sup> וכמו ומצח אשה זונה<sup data-n=\"6034\">543</sup> כו' [ומ]טעם הנ\"ל שהוא בבחי' מ\"ה ואין וגם שפלות בלב נשבר כו'). והוא ענין מה שנחתם<sup data-n=\"6035\">544</sup> בציץ מחותמו של הוי' בתו\"מ שנק' אמת מקדושת העצמית ממש, וא\"כ צ\"ל חקיקה זו ע\"י חותם כמו שמאותיות החותם נחקק בשעוה כו'. וזהו שמכה בדפוס בצורת אותיות מאחוריו דוקא עד שיהי' בולט[י'] מלפניו דהיינו כמו דרך בקיעה מן ההעלם ולא שיחקוק בפניו (וכמציץ מן החרכים דרך פרצה כו'), ודעת [ה]אומר שחופר מאחוריו כו' שצ\"ל חקיקה בעצם הציץ עכ\"פ רק שהוא מאחוריו עד שיהי' בולט מלפניו כו', וזהו מטעם שהארת אור זה דמ\"ה דחכמה דתו\"מ באים למטה ממש בכנ\"י בבחי' חקיקה ע[צמי'] בגופו של חותם אמ\"ת דתו' ממש כנ\"ל, כמו אם בחוקותי תלכו כו' כי התו\"מ נק' חקוקים<sup data-n=\"6036\">545</sup> באותיות החקיקה עצמי' (וכמו יוה\"ד שהיו חקוקים בלוחות בחקיקה עצמי' כמ\"ש והמכתב מכתב אלקים<sup data-n=\"6037\">547</sup> חרות על הלוחות [ו]הי' גבוה במעלה מיו\"ד הדברות<sup data-n=\"6038\">546</sup>, אע\"פ שבדבור בא בגילוי אור העצמי' ובכתב חרות אינו רק גילוי האותיות מצד עצמן. אבל כתב חקיקה זו נעשה לזכרון",[["6027","536","<b>הנגבל</b>: אכא: הנבדל."],["6028","537","<b>שבסומ\"ע</b>: שם: שבסוף מעשה."],["6029","538","<b>סוף דבר. . כל האד\"ם</b>: קהלת יב, יג."],["6030","539","<b>אף עשיתיו לרבותא</b>: נסמן לעיל פ' יתרו רנב, ד הערה 133."],["6031","540","<b>ב\"ד</b>: אכא: ב' דברים."],["6032","541","<b>(והב'. . כנ\"ל)</b>: כא: והב'. . כנ\"ל."],["6033","542","<b>ומצחך נחושה</b>: ישעי' מח, ד."],["6034","543","<b>ומצח אשה זונה</b>: ירמי' ג, ג."],["6035","544","<b>שנחתם</b>: אכא: שנכתב."],["6036","545","<b>חקוקים</b>: כא: חוקי\"ם."],["6037","547","<b>והמכתב מכתב אלקים</b>: תשא לב, טז [בדילוג]."],["6038","546","<b>יוה\"ד שהיו חקוקים. . גבוה במעלה מיו\"ד הדברות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670492\" data-slug=\"torat-chaim\" data-id=\"2300670492\">תו\"ח נח נה, ג</a>. אמ\"ב פתח השער יא, א."]]],[2300550695,"עולם ע\"ד סומ\"ע שעלה במחשבה תחלה<sup data-n=\"6039\">548</sup> שעולה למעלה מן הרצון והחכמה שבתורה, לפי שיש יתרון [מעלה] במעשה יותר מן התחלה דעונג ורצון. כך במצות מעשיות ממש<sup data-n=\"6040\">549</sup> דבחי' אדם דעשי' הנ\"ל עולה למעלה יותר מעצמות [האור] דתורה בשרשו, והוא ענין החותם שבא בכתב דאותיות החקיקה דוקא שאין האותיות דבר נבדל כלל מן העצם, משא\"כ חותמות<sup data-n=\"6041\">550</sup> הנכתבים בדיו על הקלף כידוע. וכך יתרון מעלה במע[שה] המ[צות] יותר מלימוד התורה שהוא דבר ה' בפה ביו\"ד הדברות כו'. ולפ\"ז גם כאן באותיות קדש לה' שבציץ שהי' בדרך כתיבה וגם בדרך חקיקה (כמ\"ש בפ' ויקהל) ויכתבו עליו מכתב<sup data-n=\"6042\">551</sup> פתוחי [חותם] כו' ע\"כ הי' חופר מאחוריו בציור מעשה הכתב ולא בהכאה בדפוס שאינו נק' כתיבה כדי שיוכל להיות גילוי האור באותיות בתשב\"כ דוקא, אבל כתיבה זאת בא בדרך חקיקה וחפירה וד\"ל). (והטעם שהי' חופר או מכה בדפוס<sup data-n=\"6043\">552</sup> מאחוריו ולא בפניו כי הי' צריך שיהיו האותיות בפניו בולטות ולא שקועות וא\"א ל[היות] בולטות בפניו ע\"י חקיקה רק בחק תוכות<sup data-n=\"6044\">553</sup> דוקא והציץ נזר הקדש<sup data-n=\"6045\">554</sup> הי' שלא יפגום בו כלום (כי הנזר הזה הוא בבחי' כתר ועטרה בראש כה\"ג שנק' כתר כהונה<sup data-n=\"6046\">*555</sup> והוא בבחי' קוה\"ק וע\"כ הי' לרצון תמיד כו' והי' מכפר על עון הקדשים<sup data-n=\"6047\">555</sup> דוקא <span data-k=\"pg\">תקנד</span> ּ (כמשי\"ת). וכן לא ע\"י הכאה בדפוס בפניו שא\"כ היו האותיות בציץ שקועות ולא בולטות שהאותיות בדפוס היו בולטות, ולפי שבא ממילא מן ההעלם בדרך בקיעה ע\"כ הי' חופר או מכה מאחוריו כו').\n<b>ומעתה</b> יובן מ\"ש עוד והי' על מצח אהרן כו' והי' על מצחו תמיד לרצון להם לפני ה' כו', כי מבואר למעלה שתיבות אלו קדש לה' כוללים כל קדושת אותיות התו\"מ שלמעלה שנחקקו משם כמו שנחקק מן החותם וכמ\"ש ופתחת עליו פתוחי חותם, שזהו מבחי' חותמו של הקב\"ה שהוא אמ\"ת דתורה שבאים ונמשכים למטה בתושב\"כ ובמצות ברמ\"ח מצות עשה בפרט, הנה ע\"י בחי' חקיקה זו שנק' פתוחי חותם העליון יהיו לזכרון לרצון תמיד לפני הוי' על ישראל כמ\"ש והי' על מצחו תמיד לרצון להם דוקא לפני ה'. וענין תמיד לרצון היינו לזכרון רצון בתמידות בלי ישכח לעולם כלל וכלל, כי ע\"י שהחותם העליון נחקק בו בדוגמא ממש לאותיות החותם העליון שיחתום בו שמו הפ[נימי'] והעצמי' עי\"ז יהי' לזכרון פנימי' ועצמי' הרצון תמיד בלי ישונה ויוחלף כלל. ויובן [זה] עד\"מ אדם שנגמר בדעתו והוחלט ברצונו איזה דבר מה שיהי' כך וכך דוקא מאיזה טעם הכמוס עמדו, לא למעלה מן הטעם הכמוס רק בחירה רצ\"פ<sup data-n=\"6048\">556</sup> וע[צמי] שהוסכם והוחלט כך",[["6039","548","<b>סומ\"ע </b>[אכא: סוף מעשה]<b> שעלה במחשבה תחלה</b>: ע\"פ פיוט לכה דודי."],["6040","549","<b>ממש</b>: כא: ליתא."],["6041","550","<b>חותמות</b>: אכא: אותיות."],["6042","551","<b>בפ' ויקהל) ויכתבו עליו מכתב </b>[א: ליתא]: פקודי לט, ל."],["6043","552","<b>שאינו נק'. . מכה בדפוס</b>: כא: ליתא. וכנראה נשמט מפני תיבות הדומות: בדפוס. . בדפוס."],["6044","553","<b>בחק תוכות</b>: גיטין כ, א."],["6045","554","<b>והציץ נזר הקדש</b>: פקודי שם. צו ח, ט."],["6046","*555","<b>והציץ. . כתר כהונה</b>: ראה חדא\"ג מהרש\"א גיטין סו, א. יומא ח, א."],["6047","555","<b>מכפר על עון הקדשים</b>: תצוה כח, לח. ראה יומא ז, א. לקמן שפ, א."],["6048","556","<b>רצ\"פ</b>: א: רצון פנימי. כא: רצון פשוט."]]],[2300550699,"ברצונו<sup data-n=\"6049\">557</sup> בלי ישונה לרצון אחר, הגם שיכול לשנות, ומפני שירא שבהמשך הזמן ישכח על ההחלט הזה יסכים ויעשה היפוך רצונו המוחלט כבר, עושה בעצמו חותם ואות לזכרון לרצון זה המוחלט שירצה ברצון זה שהוחלט בענין ודבר זה לעולם ולא ישתנה מכל סיבה וכל טעם שבעולם כו'. וענין החותם והאות הזה שעושה לזכרון הוא מה שיחתום בטבעת באותיות החקוקים בו שהוא שמו בשעוה, או רושם אותיות בדבר זה שיזכור על הרצון המוחלט מיד בראותו חותמו ורישומו להיות לו לרצון ולא ישתנה, ואז הרצון הזה תמידי הוא בלי שינוי לעולם כלל. אבל א[ם] ל[א] הי' רושם או חותם בטבעתו הי' נשכח ממנו החלט הרצון הזה והי' מתחלף ברצון אחר היפוכו כו' וד\"ל.\n<b>והנמשל</b> מזה יובן למעלה בענין חותמו של הקב\"ה שהוא בחי' אמ\"ת דתורה שהי' מאיר ונמשך בבחי'<sup data-n=\"6050\">558</sup> אותיות דקד\"ש לה' בציץ על מצח אהרן כנ\"ל<sup data-n=\"6051\">559</sup>, זהו ענין פתוחי חותם שנעשה לאות ולזכרון עולם ע\"ד הרצון הפנימי ועצמי שהוחלט מכבר בישראל כמאמר ישראל עבמ\"ח<sup data-n=\"6052\">560</sup> ורצ[ון] הק[דום] בבחירה פנימי' ועצמי' כמו כי יעקב בחר לו י\"ה<sup data-n=\"6053\">561</sup> כו' וכן אמר יבחר לנו<sup data-n=\"6054\">562</sup> כו' (כמו ביו\"כ בגורלות<sup data-n=\"6055\">563</sup> שנבחרו ישראל בגורל לה' כו' בבחירה שלמעלה מן השכל והטעם וגם למעלה מן הרצון, כידוע בענין הגורל שתולה הרצון כמו שיפול הגורל כו' שזהו בעצמי' מקור הרצון כו') שיהי' לרצון תמיד בלי שינוי וחילוף כלל לעולם משום צד אף שירבו המקטרגים כו'. או מצד בחי' הסתלקות ועליות הרצון והחכמה שלמעלה ברוממות העצמות דא\"ס ב\"ה שלמעלה גם מן הרצון וחכמה דתו\"מ שלמעלה מבחי' אדם כנ\"ל, ושוין שם הכל רחוק כקרוב פנימי' <span data-k=\"pg\">1110</span> ּ וחיצוניות כמ\"ש כחשיכ\"ה כאור\"ה שמפני זה הטעם ביקש משה ונפלינו אני ועמך<sup data-n=\"6056\">564</sup> שלא תשרה שכינה כו' כידוע. ואמנם גם ברוממות העצמות עד אין שיעור למעלה שם דוקא נבחרו ישראל ותורה בבחי' פנימי' הרצון ותענוג<sup data-n=\"6057\">565</sup> שנק' אד\"ם אדמ\"ה לעליו\"ן ממש. אך כדי שלא ישכח על זה הרצון המוחלט מכבר בעצמותו ממש שזהו ענין החות\"ם דתורה אמ\"ת כמו הלא הוא כמוס עמדי חתו\"ם<sup data-n=\"6058\">566</sup> כו' וכתיב חתו\"ם תורה בלמוד\"י<sup data-n=\"6059\">567</sup> כו', וכמו בחותם שבטבעת שנז' עי\"ז לזכרון ע\"ד הרצון המוחלט כך יזכור ה' על הרצון הנבחר לישראל שהן קדש לה' ע\"י קיום התו\"מ כמ\"ש קד\"ש ישראל להוי' ממ\"ש ונק' ראשית תבואת\"ו<sup data-n=\"6060\">568</sup> כו'. וזה הזכרון הוא בחקיק[ת] אותיות דקדש לה' שבציץ שנק' פתוחי חותם העליון כנ\"ל שלא יהי' בו שינוי וחילוף לרצון אחר, ולזה הי'",[["6049","557","<b>ברצונו</b>: כא: ליתא."],["6050","558","<b>בבחי'</b>: אכא: בחקיקה."],["6051","559","<b>כנ\"ל</b>: כא: כו'."],["6052","560","<b>ישראל עבמ\"ח</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, א הערה 248."],["6053","561","<b>כי יעקב בחר לו י\"ה</b>: תהלים קלה, ד."],["6054","562","<b>יבחר לנו</b>: תהלים מז, ה."],["6055","563","<b>ביו\"כ בגורלות</b>: ראה מאמרי אדה\"א נ\"ך ע' שסז ואילך. וש\"נ."],["6056","564","<b>ונפלינו אני ועמך</b>: תשא לג, טז. ראה ברכות ז, א. לעיל פ' שמות לא, א הערה 185."],["6057","565","<b>ותענוג</b>: כא: והטעם."],["6058","566","<b>הלא הוא כמוס עמדי חתו\"ם</b>: האזינו לב, לד."],["6059","567","<b>חתו\"ם תורה בלמוד\"י</b>: ישעי' ח, טז."],["6060","568","<b>תבואת\"ו</b>: ראה מאמרי אדה\"א שמות ח\"א ע' א ואילך. וש\"נ."]]],[2300550703,"כל עיקר הכוונה במצוה זו שצוה למשה ועשית ציץ זהב טהור ופתחת עליו כו' עד והי' על מצחו תמיד לרצון להם דוקא בתמידית בלי ישונה לעולם. והוא מה שיהי' לו לרצון תמיד במעשיהם שהוא מעשה המצות שיעשו בכל דור ובכל זמן שיהי' עולה לרצון לפני ה' תמיד ולא ישכח עליהם, דאע\"פ שמצד מעשה המצות עצמן שהן פנימי' רצונו כידוע הי' ראוי שיהי' לרצון מאליהם, אך יכול להיות שלא ירצה לפניו גם מעשיהם במצות, עד שיעורר בזכרון ע\"ד בחירה הרצון המוחלט מכבר בעצמו בענין הבחירה בפנימי' ועצמי' הרצון בתו\"מ וישראל שהן ג' קשרים הנ\"ל מצד העלי' ברוממות העצמי' ששם למעלה מן הרצון והכל שוים כנ\"ל. אך ע\"י בחי' החותם שנעשה באותיות התורה בכלל שנחקק בציץ באותיות הללו דקדש לה' הוא שמעורר הזכרון ברית שהוחלט והוברר מכבר להיות תו\"מ וישראל קד\"ש לה' בפנימי' ועצמי' הרצון בלי שינוי וחילוף לעולם, והי' זה ע\"י מה שרואה בציץ שעל מצח אהרן דוקא קד\"ש לה' שזהו כמו בחי' החותם העליון שנעשה לזכרון עולם. וזהו והי' על מצחו תמיד לרצון כו' דתיבת תמיד קאי אדסמיך לי' שיהי' על מצחו תמיד [כדי] שיראנו תמיד ומחמתו יהי' לרצון תמיד לפני ה' גם במעשה המצות שישראל עושין כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין יש להבין מהיכן יש כח ועוז [כ]זה באותיות הללו דקד\"ש להוי' שבציץ שנחקקו בו ד\"א<sup data-n=\"6061\">569</sup> לעורר הזכרון העצמי ופנימי תמיד לפני ה' כנ\"ל, כי מאחר שמעורר הזכרון בעצמות א\"ס ממש להיות לו לרצון בישראל ומצות שלהם זהו בהכרח יבא ממדרגה הגבוה גם מן הרצה\"ע שבתו\"מ ואיך יהי' זה ע\"י פתוחי החותם הזה דציץ בב' תיבות דקדש לה' שאינו רק מחותם דתורה שנק' אמ\"ת כנ\"ל וד\"ל.\n<b>אך</b> להבין זה ילה\"ק בטעם שא' שהי' כתוב קד\"ש למ\"ד מלמטה והוי' מלמעלה דוקא, ויל\"ת<sup data-n=\"6062\">570</sup> מהו ענין ב' תיבות הללו דקדש להוי', דהנה מבואר למעלה בשרש ענין המצות שהן בבחי' אד\"ם אדמ\"ה לעליו\"ן ממש וכמ\"ש נעשה אד\"ם בצלמנו כדמותנ\"ו בצלמנו בחי' צורה עצמי' זהו בחי' אדם פנימי [דתו\"מ<sup data-n=\"6063\">571</sup> שבה כו' דמח\"ע נפקת<sup data-n=\"6064\">572</sup> שהיא בחי' פנימי' חכ' העצמי' ממש וגם המצות הרי הן בבחי' פנימי'] רצונותיו<sup data-n=\"6065\">574</sup> ית' העצמ[י'] ממש דאיהו ורצונו<sup data-n=\"6066\">573</sup> וחכמתו העצמי' אחד הוא ממש, <span data-k=\"pg\">תקנה</span> ּ אך אהבה רבה<sup data-n=\"6067\">*576</sup> שבחי' פנימי' רצונו וחכמה<sup data-n=\"6068\">575</sup> שלמעלה בעצמו' (שהן בבחי' א\"ס ממש כמו בתורה א' ארוכה מארץ [מדה]<sup data-n=\"6069\">576</sup> כו' ובמצות א' רחבה מצותך מאד<sup data-n=\"6070\">577</sup> ונק' ארחות",[["6061","569","<b>בו ד\"א</b>: אכא: בידי אדם."],["6062","570","<b>ויל\"ת</b>: אכא: ויש להבין (וי\"ל) תחלה."],["6063","571","<b>דתו\"מ</b>: א: דתו' ומדות. יג: דתורה בחכ' ומדות."],["6064","572","<b>דתו'. . דמח\"ע נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."],["6065","574","<b>רצונותיו</b>: א: חכ' העצמי'."],["6066","573","<b>חכ' העצמי'. . דאיהו ורצונו</b>: כא: רצונו."],["6067","*576","<b>אך אהבה רבה</b>: יגכג: ביח\"ע העצמי ממש אך אנו רואים."],["6068","575","<b>אחד. . וחכמה</b>: אכא: ליתא."],["6069","576","<b>ארוכה מארץ [מדה]</b>: איוב יא, יט."],["6070","577","<b>רחבה מצותך מאד</b>: תהלים קיט, צו."]]],[2300550706,"הוי'<sup data-n=\"6071\">578</sup> ממש) הוא שירדו למטה מטה בהתלבשות חיצוני' מאד בדברים גשמיי' ממש, כמו בחי' רצה\"ע ממש שבמצות ציצית נתלבש בצמר גשמי דטלית וכן רצה\"ע ממש שבתפילין בקלף ודיו גשמי כו' וכה\"ג בכל המצות. ועכ\"ז נק' מצות[י] ממש כמ\"ש והי' אם שמוע [כו'] אל מצותי כו' ואו' על מעשה המצות בגשמיות אקב\"מ<sup data-n=\"6072\">579</sup> ממש כידוע, וכל בחי' יחו\"ע שבאצי' עד רום המעלות בעצמות המאציל ממש הוא שנעשה למעלה ע\"י המצות שלמטה שנעשה בדברים גשמיי' דוקא. והטעם הוא כי אע\"פ שירד הרצה\"ע ונתלבש למטה אין בזה שינוי המהות כלל מכמו שהוא למעלה ממש ונק' מצות הוי' ממש רק שבא ירידת אור הרצה\"ע כמו בדרך חקיקה וגליפה דאותיות החותם בדבר נבדל שנק' דמות [כמ\"ש] כדמותנו (שנק' אדם דעשי' בציור רמ\"ח אברים כו' ואותיות התורה שלמעלה נק' צלמינו כחותם עצמו). אך הנה ידוע דבאתעדל\"ת נעשה אתעדל\"ע ממש כפי אופן ההעלאה דוקא כמ\"ש<sup data-n=\"6073\">580</sup> אייתי רוח כו', והיינו כשישראל עושין רצונו של מקום במעשה המצות למטה בדברי' גשמיי' דוקא בציצית ותפילין בגשמיות וכה\"ג מעוררי' אתעדל\"ע דרוח אייתי רוח כו', דהיינו שמעוררי' לבחי' רצה\"ע שבמצוה זו שעושי' כמו שהוא למעלה במהו\"ע ית' ממש שנק' מצות[י] ממש כנ\"ל (דכתיב כמים הפא\"פ<sup data-n=\"6074\">581</sup> כו' דבחי' התעוררות לב אדם חיצוני דעשי' במצות גשמיות מעורר ללב אדם פנימי העליון<sup data-n=\"6075\">582</sup> שבאצי' ולמעלה מעלה בעצמות ממש משום דכתי' סוף דבר הכל<sup data-n=\"6076\">583</sup> כו' כי זה כל האדם משום דנתחב\"ס<sup data-n=\"6077\">584</sup> כו' וכנ\"ל בענין הציץ שהוא מציץ מן החרכים כרשפי<sup data-n=\"6078\">585</sup> אש ע\"י אתעדל\"ת באהבה ותשוקה כו', והיינו ג\"כ מה שצופה ומביט במעשה המצות דישראל למטה שיעלה לרצון לפניו כמו שהן בעצמו' ממש בעצם הרצון כנ\"ל).\n<b>אך</b> הנה זה גופא י\"ל מהיכן יהי' כח באתעדל\"ת במצות גשמיי' לעורר אתעדל\"ע ברצה\"ע שלמעלה ממש שאין ערוך כלל ביניהם, ואיך יתכן לומר בזה דרוח אייתי רוח כו' לעורר אתעדל\"ע כו'. ואמנם באמת עיקר כח המחבר לעורר אתעדל\"ע ברצה\"ע ע\"י המצות שלמטה הוא בא בתנאי א' שהוא ענין ק[ב]עומ\"ש [שיש במצות קודם שעושה המצוה, שזהו ענין הכנעות הלב ביותר לקבל עומ\"ש] בביטול כל עצמותו רק לעשות רצון ה' וגזירותיו כמו שום תשים עליך מלך<sup data-n=\"6079\">586</sup> וכמא' למה קדמה [פ'] שמע<sup data-n=\"6080\">587</sup> כו' [כדי] ש[י]קבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עול מצות כו', דמשמע מזה דאע\"פ שמקיים",[["6071","578","<b>ובמצות. . ארחות הוי'</b>: תהלים כה, י. ראה לעיל פ' וארא סט, ד. וש\"נ."],["6072","579","<b>אקב\"מ</b>: א: אשר קדשנו במצותיו — נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא."],["6073","580","<b>כמ\"ש</b>: אכא: כמאמר."],["6074","581","<b>כמים הפא\"פ</b>: משלי כז, יט [ושם: לפנים — נסמן לעיל פ' בא קב, ב]."],["6075","582","<b>העליון</b>: א: רצון העליון."],["6076","583","<b>הכל</b>: א: ניתוסף: נשמע. כא: ליתא."],["6077","584","<b>דנתחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["6078","585","<b>כרשפי</b>: איג: באהבה כרשפי. כא: ברשפי."],["6079","586","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["6080","587","<b>למה קדמה [פ'] שמע</b>: ברכות יג, א (במשנה). ראה גם לקמן פ' ויקהל תלג, ב."]]],[2300550709,"המצות בפו\"מ רק שאינו ע\"פ קבלת עומ\"ש בהכנעה וביטול רצון כו', אעפ\"י שאינו בפר\"ע לגמרי מ\"מ לא יעלה מע[שה] המצ[ות] לרצון למעלה לעורר בחי' אתעדל\"ע הנ\"ל וד\"ל. והטעם הוא כי אע\"פ שצריך לעשות המצות בשמחה וטוב לבב דוקא כמ\"ש עבדו את ה' בשמחה<sup data-n=\"6081\">588</sup> וכתי' תחת אשר לא עבדת ה' בשמחה וטוב לבב<sup data-n=\"6082\">589</sup> כו', זהו לאחר מעשה המצות או <span data-k=\"pg\">1112</span> ּ בשעה שאו' אשר קדשנו במצותיו שישמח בשש\"מ<sup data-n=\"6083\">590</sup> שקדשנו בקדושת עצמי'<sup data-n=\"6084\">591</sup> במצותיו כו' שהוא מקיף העליון כו' (כמשי\"ת). אבל קודם שיעשה המצוה צריך שיקבל עליו עומ\"ש דוקא שהוא לקיים גזירת מלך לבד מצד שאמ\"ר ונע\"ר<sup data-n=\"6085\">592</sup> לבד שזהו כענין שא' שמצות צריכות כוונה<sup data-n=\"6086\">593</sup> דהיינו כוונה לצאת י\"ח עכ\"פ, ואף בק\"ש שהיא רק יחו\"ע למס\"נ באחד<sup data-n=\"6087\">594</sup> צ\"ל הכוונה קודם רק לצאת י\"ח לבד שהוא לקיים מצות המלך שצוה כך כו', ואם אין לו בחי' ביטול והכנעה זו בקבלת עומ\"ש אע\"פ שעושה ומקיים המצות בפו\"מ כמצותה וכדינה אין גילוי והשראת אלקות במצוה זו כלל. כי אין<sup data-n=\"6088\">595</sup> ישכון אור הוי' שברצה\"ע במצוה זו למטה כלל ולא נשאר רק המעשה עצמה למטה ולא יעלה למעלה וכמש\"א ותהי יראתם אותי<sup data-n=\"6089\">596</sup> מצות אנשים מלומדה כו' (כ\"א ע\"י קבלת עומ\"ש באוי\"ר לפרקים בק\"ש ותפלה או ע\"י תפלת [ה]צדיקים<sup data-n=\"6090\">*597</sup> שבדור יעלה כל המצות שעשה למעלה (וכידוע שכמה משך זמן רב לא עלו מצות דב[נ]\"י למעלה<sup data-n=\"6091\">597</sup> כלל כו').\n<b>ושרש</b> הענין הוא להיות ששרש המצות הוא בפנימי' רצה\"ע שהוא בחי' מקיף דאור הכתר (שהן תרי\"ג מצות דאורייתא וז' מצות דרבנן<sup data-n=\"6092\">598</sup> שהן תר\"ך עמודי אור<sup data-n=\"6093\">599</sup> ) שבו שורה מפנימי' ועצמו' דאור א\"ס ב\"ה ממש כנ\"ל, וידוע שהמצות נק' לבושי' כמ\"ש בזוהר ע\"פ ואברהם [זקן] בא בימים<sup data-n=\"6094\">600</sup> באינון לבושין שנק' יומין עילאין כו', והיינו שנק' לבוש מל' דוקא כמ\"ש ותלבש אסתר מל'<sup data-n=\"6095\">601</sup> וזהו להודיע לבני האדם<sup data-n=\"6096\">602</sup> כו' וכבוד הדר מל[כותו], ויופי הדר הזה הוא בבחי' לבוש מל' דוקא מל'<sup data-n=\"6097\">603</sup> שהן המצות שנעשי' בקעומ\"ש דוקא אז נעשי' בחי' הוד לבוש מל' למעלה ונק' יפ\"ת<sup data-n=\"6098\">604</sup> כו' שמייפים אותו בהוד לבוש מל'. והיינו כאשר ישראל מקבלים עליהם עומ\"ש שלימה ולקיים כל אשר יגזור אומר כמו במ\"ת [שא'] כל אשר דיבר ה' נעשה<sup data-n=\"6099\">605</sup> כו', שעי\"ז יורד בחי' המקיף דכ\"ע שנק' כתר מל' שהוא בחי' המקיפים דרצה\"ע שבמצות למעלה כידוע שהמקיפי' שורים על הלבושים דוקא, וזהו שרש ענין בגדי",[["6081","588","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["6082","589","<b>תחת. . וטוב לבב</b>: תבוא כח, מז [ושם: ה\"א. ובטוב — נסמן לעיל פ' בשלח רה, ג הערה 1091]."],["6083","590","<b>בשש\"מ</b>: אכא: בשמחה של מצוה."],["6084","591","<b>עצמי'</b>: א: עצמו. כא: עצמותו ממש."],["6085","592","<b>ונע\"ר</b>: שם: ונעשה רצונו."],["6086","593","<b>שמצות צריכות כוונה</b>: ראה ערובין צה, ב."],["6087","594","<b>למס\"נ באחד</b>: נסמן לעיל פ' תרומה שטז, ג."],["6088","595","<b>אין</b>: אכא: לא."],["6089","596","<b>ותהי יראתם אותי</b>: ישעי' כט, יג."],["6090","*597","<b>תפלת [ה]צדיקים</b>: ראה גם לעיל שלח, ד."],["6091","597","<b>שכמה משך זמן. . למעלה</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תמח (בשם הבעש\"ט). וראה גם לעיל שלח, ד."],["6092","598","<b>הכתר. . תרי\"ג. . וז' מצות דרבנן</b>: נסמן לעיל פ' משפטים שא, סע\"א ואילך הערה 425."],["6093","599","<b>תר\"ך עמודי אור</b>: ראה פרדס (שער מהות והנהגה) ש\"ח, פ\"ג. לעיל פ' שמות ח, א הערה 341."],["6094","600","<b>ואברהם [זקן] בא בימים</b>: ח\"ש כד, א. ראה זהר שם קכט, א. ויחי רכד, סע\"א. לעיל פ' בשלח קעו, א. וש\"נ."],["6095","601","<b>ותלבש אסתר מל'</b>: אסתר ה, א."],["6096","602","<b>להודיע לבני האדם</b>: תהלים קמה, יב."],["6097","603","<b>מל'</b>: אכא: ליתא."],["6098","604","<b>ונק' יפ\"ת</b>: כא: וזהו שנק' יפה תואר."],["6099","605","<b>כל אשר דיבר ה' נעשה</b>: יתרו יט, ח. משפטים כד, ז."]]],[2300550712,"אהרן כמ\"ש ועשית בגדי קדש<sup data-n=\"6100\">606</sup> לאהרן אחיך לקדשו לכהנו לי כו' לכבוד ולת\"ת<sup data-n=\"6101\">607</sup> כו' וכמבואר במ\"א וד\"ל. ולפי שבחי' מקיף דאור הכתר [עליון] שורה במע[שה] המצ[ות] צריך שלא יהי' באדם העושה המצוה שום דבר המסתיר ומנגד לאור הקדושה הזאת, שהוא שלא יהא נראה לבחי' יש ודבר מה בבחי' גסות והתנשאות הלב בבחי' נפרד כלל וכלל אלא אדרבה צריך שיהי' בבחי' הכנעה וביטול מאד בלב נשבר ובשפלות יתירה לקבל עליו עומ\"ש כעבד לאדוניו כנ\"ל. ואף שגבה לבו בדרכי ה' גם בחיצוניות הגסות שזהו מה שעושה המצות להתייהר ויתנשא בזה לעיני הבריות שיאמרו עליו כמה טובים מעשיו כו', או גם שגבה לבו בהתנשאות הלב על קרבתו בקדושה האלקי' שגבה לבו רק<sup data-n=\"6102\">608</sup> בדרכי ה' עצמם עכ\"ז נק' גבהות הלב עכ\"פ, ודוד א' לא גבה לבי<sup data-n=\"6103\">609</sup> כו' וכתי' תועבת ה' כל גבה לב כו' אותו לא אוכל<sup data-n=\"6104\">610</sup> וארז\"ל אין אני והוא יכולים לדור כא'<sup data-n=\"6105\">611</sup> [כו'], וזה פלאי מאין יש מקום שידור עמו עד שאמר אין אני יכול <span data-k=\"pg\">תקנו</span> ּ לדור עמו יחד<sup data-n=\"6106\">612</sup> כו'. אך הענין הוא דכוונתו בזה דגם במע[שה] המצ[ות] שעושה שזהו שנק' דירה והשראה שישרה וישכון אור ה' במעשה זו כמאמר נתאוה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"6107\">613</sup> דירה ממש. ואמנם אם גבה לב כו' אותו לא אוכל שאינו יכול לדור עמו גם במע[שה] המצ[ות] שלו, לפי שכל בחי' ישות וגסות שבא בהתפשטות והתנשאות גדולה זה לא יוכל לסבול כלל כי תועבה היא לפניו להיותה תכלית המנגד לקדושה האלקית שאינה אלא בבחי' אין ומ\"ה בתכלית הביטול במציאות לבלי יראה לבחי' יש ודבר מה כלל כמו בחי' מ\"ה דמשה שהי' עניו מכל כו' כנ\"ל וד\"ל).\n<b>והנה</b> מ\"ש כל גבה לב כל זה בא לרבותא<sup data-n=\"6108\">614</sup> אף בחי' הגבהת דלב בחיצוני' ביותר, אע\"פ שאין בלבו בפנימי' שום גסות וגבהות הלב כלל, והיינו כמו באנשים המתנהגי' בלבושי כבוד ודירות רחבים ונאים וכלי כסף וזהב ומרגליות וכה\"ג (שזהו בחי' חיצוני' הקליפה דעמלק כו' ), אע\"פ שאינו נראה לגסות וגבהות רק בחיצוני' לבד. ומכ\"ש כאשר הגסות וגבהות הלב הוא בבחי' הפנימי' שבלב כדי להתגדל לבד שאז ודאי א' אין אני והוא יכולים לדור כא', דהיינו אף במע[שה] המצ[ות] שעושה שראוי שישרה שם שם הוי', לפי שצריך שיהי' המצות כלי לבחי' או\"מ דכ\"ע שהוא בבחי' קדושה עליונה דעצמות א\"ס ב\"ה שאינו שורה רק בבחי' אין ושפלות והכנעה יתירה בבחי' ביטול המציאות דוקא, והיינו בקבלת עומ\"ש קודם מע[שה]",[["6100","606","<b>ועשית בגדי קדש</b>: תצוה כח, ד. ראה ד\"ה זה במאמרי אדה\"א שמות ח\"ב ע' שלח ואילך ובהנסמן בריש המאמר שם."],["6101","607","<b>לכבוד ולת\"ת</b>: תצוה כח, ב."],["6102","608","<b>רק</b>: אכא: ליתא."],["6103","609","<b>לא גבה לבי</b>: תהלים קלא, א. ראה מאמרי אדה\"א בראשית ע' צז."],["6104","610","<b>אותו לא אוכל</b>: תהלים קא, ה."],["6105","611","<b>אין אני והוא יכולים לדור כא'</b>: ראה סוטה ה, א. ערכין טו, ב."],["6106","612","<b>יחד</b>: כא: ליתא."],["6107","613","<b>נתאוה. . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא</a> רפל\"ו. לעיל פ' וארא ע, ג הערה 67."],["6108","614","<b>כל זה בא לרבותא </b>[כא: לרבות]: ראה גם לעיל שנח, א."]]],[2300550715,"המצ[ות] כנ\"ל בכדי שיהי' לו דירה בתחתונים עמו<sup data-n=\"6109\">615</sup> ביחד בשעה שעושה המצוה או בא[מרו] אקב\"מ ממש כנ\"ל וד\"ל. ובכ\"ז יובן ויתורץ הקושיא הנ\"ל שמהיכן יש כח ועוז באתעדל\"ת במע[שה] המצ[ות] לעורר את אתעדל\"ע בבחי' רצה\"ע ממש שאין ערך כלל ביניהם כו', כי ע\"י קבלת עומ\"ש בביטול והכנעה דוקא הרי יכול לדור עמו יחד כנ\"ל, שהוא השראת אור המקיף דמצות כמו שהוא למעלה ברצה\"פ<sup data-n=\"6110\">616</sup> כו' שיומשך למטה במעשה זו משום דמקיפי' שורים על הלבושי' שהן המצות שנק' לבוש מל' אם הן בבחי' ביטול היפך הגסות שלא יסבול לדור עמו יחד וד\"ל. וזהו כמו שמבואר למעלה בענין גוף הציץ שעשה משה דוקא לפי שמשה הוא בבחי' מ\"ה דחכ' דתורה כמו תורה צוה לנו משה בבחי' הביטול דוקא היפוך הגסות כו' ועי\"ז מציץ מן החרכים כו' שהוא אור מקיף דכת\"ר כו' וד\"ל.\n<b>ועם</b> כל הנ\"ל יובן מארז\"ל על ב' תיבות הללו דקדש לה' שהי' כתוב קד\"ש ל' למטה והוי' למעלה כו', דהנה פי' קדש לה' כפשוטו זהו בחי' הקדושה העולה מלמטה למעלה דוקא כידוע דכל למ\"ד מורה בחי' ההעלאה שעולה מלמטה<sup data-n=\"6111\">617</sup> כלפי מעלה כמו נברך לאלקינו<sup data-n=\"6112\">618</sup> כו'. וגם כאן קד\"ש לה' שזהו מורה ענין העלאה הקדושה מלמטה למעלה, שזהו כמש\"א שיהי' דבר זה קד\"ש לה' כמו שמקדשי' קדשי' כקרבנות שא' זה יהי' קד\"ש לעולה<sup data-n=\"6113\">619</sup> וכה\"ג בכ\"ד<sup data-n=\"6114\">620</sup> חול שמקדשי' אותו בקדשי בדק הבית וכקדשים בתרומות ומעשרות ומעשר בהמה שהעשירי יהי' קדש<sup data-n=\"6115\">621</sup> כו', שכ\"ז הרי נעשה קדושה מן החול דוקא, שדבר חול נתעלה להיות קדש לה' (שהוא <span data-k=\"pg\">1114</span> ּ בבחי' או\"ח), וע\"י העלאה זו נמשך [בחי'] קדושה עליונה עד\"ז<sup data-n=\"6116\">622</sup> ונעשה קדש בקדש העליון ממש (ש[הוא] נק' מקיף דאו\"י) כקדושת כה\"ג וכלי המקדש שנמשחו בשמן משחת קדש כו'), שכל העלאה גורם המשכה<sup data-n=\"6117\">623</sup> כידוע וד\"ל (וכמבואר במ\"א בענין נקדיש\"ך<sup data-n=\"6118\">624</sup> כו' שיש קדושה הנעשה למעלה מאתעדל\"ת והוא בחי' העלאה דאו\"ח שבבחי' או\"ח הנ\"ל<sup data-n=\"6119\">625</sup> הוא בחי' כ[ת\"ר]<sup data-n=\"6120\">626</sup>, וזהו העשירי דוקא יהי' קדש בקדושת מעשר וכך בכל העלאה קדושה מלמטה למעלה). וכך יובן ג\"כ בענין המצות שנעשים בדברי' גשמיי' שנק' חול גמור ונעשי' קדש לה' במע[שה] המצ[ות] בא[מרו] אקב\"מ<sup data-n=\"6121\">627</sup> כו' שנמשך בהם שם הוי' מקדש העליון והוא בחי' קדושת או\"מ<sup data-n=\"6122\">628</sup> דמצות כנ\"ל, וא\"כ הרי יש כאן בחי' העלאה דקדושה שעולה מלמטה למעלה מן המצות בבחי' או\"ח כקדושת הקרבנות ומעשרות כנ\"ל, והוא בחי' אתעדל\"ת במעהמ\"צ בכוונה ורעו\"ד",[["6109","615","<b>בתחתונים עמו</b>: א: עמו. כא: ליתא."],["6110","616","<b>ברצה\"פ</b>: אכא: ברצה\"ע."],["6111","617","<b>דכל למ\"ד. . ההעלאה שעולה מלמטה</b>: ראה גם לעיל שנח, א. וש\"נ."],["6112","618","<b>נברך לאלקינו</b>: נסמן לעיל שם."],["6113","619","<b>לעולה</b>: א: ניתוסף: כו'. כא: כו' שכ\"ז יהי' קדש לעולה."],["6114","620","<b>בכ\"ד</b>: אכד: בכל דבר."],["6115","621","<b>שהעשירי יהי' קדש</b>: בחוקותי כז, לב."],["6116","622","<b>עד\"ז</b>: כא: על דבר זה."],["6117","623","<b>שכל העלאה גורם המשכה</b>: ראה גם לעיל פ' בשלח ריט, א. וש\"נ. וראה גם לעיל שסד, א. שעד, ג."],["6118","624","<b>בענין נקדיש\"ך</b>: ראה גם בענין נקדישך מאמרי אדה\"א שמות ח\"ב ע' תקצד ואילך."],["6119","625","<b>הנ\"ל</b>: א: ליתא. כא: המל'."],["6120","626","<b>או\"ח המל'. . כ[ת\"ר]</b>: ראה מאמרי אדה\"ז תקע\"א ע' לח. וש\"נ [ושם: צ\"ל: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381210\" data-slug=\"likkutei-torah\" data-id=\"4001381210\">לקו\"ת שה\"ש כ, רע\"ב</a>]. לקמן פ' ויקהל תב, ד."],["6121","627","<b>אקב\"מ</b>: א: אקב\"ו אשר קדשנו במצותיו וציונו. כא: אק\"ב."],["6122","628","<b>או\"מ</b>: כא: אור המקיף."]]],[2300550718,"ובקבלת עומ\"ש בביטול והכנעה כנ\"ל, ועי\"ז בא[מרו] א\"ק<sup data-n=\"6123\">629</sup> כו' רוח אייתי רוח כו' ומעורר לבחי' הקה\"ע<sup data-n=\"6124\">630</sup> שברצה\"ע שבמצות למעלה שהוא קדוש[ת] או\"מ דכתר שבמצות למעלה שיהא נמשך למטה. ולפי\"ז אין ירידת אור מקיף דקדושה זו מלמעלה רק ע\"י בחי' העלאה דקדושה מלמטה למעלה ע\"י אתעדל\"ת במע[שה] המצ[ות] בביטול והכנעה כנ\"ל<sup data-n=\"6125\">631</sup>, ע\"כ נחקק בציץ שהוא לאות וזכרון על הבחירה ברצון המוחלט בעצמי' ופנימי' על המצות וישראל כנ\"ל אותיות אלה קדש להוי' דוקא, והוא מה שנכתב קדש ל' מלמטה כלומר מפני<sup data-n=\"6126\">632</sup> שע\"י העלאה מלמטלמ\"ע מתעורר קדושה הזאת להוי' העליון שיומשך למטה כנ\"ל<sup data-n=\"6127\">633</sup> כי כל למ\"ד מורה ענין העלאה מלמטה למעלה דוקא כנ\"ל וד\"ל (וז\"ש קד\"ש ישראל לה' כו' שהוא קדושה שמלמטה למעלה, שזהו מ\"ש ראשית תבואתו כמו שראשית התבואה שנעשית קד\"ש לה' כתרומות ומעשרות לכהן ולוי כו', וקדושה העליונה שנמשך מלמעלה למטה היינו קדושת התו\"מ כמו שהן למעלה בפנימית רצונו וחכ' כנ\"ל שנחקקו באותיות הללו דקדש להוי' בבחי' פתוחי חותם כנ\"ל, ובחי' הקדושה הג' שלמעלה משניהם היא קדושת העצמי' ממש דאין קדוש כהוי' עצמו שמחבר לב' קדושות הללו (והוא שם הוי' שלמעלה שהוא בחי' רעדכ\"ר (וכמשי\"ת), ובחי' כח זה יש במחבר מלמטה למעלה והוא ענין קבעומ\"ש שבמצות שא' ונע\"ר שמגיע בע[צמו'] בעה\"ר<sup data-n=\"6128\">634</sup> ממש שנק' כת\"ר שבכתר מקור כל הרצונות<sup data-n=\"6129\">635</sup> שבתו\"מ שעי\"ז נמשך ממילא בחי' קדו[שה] הע[ליונה] דתו\"מ העליונים מלמעלה למטה, וכמ\"ש במ\"א בענין הקים על עול\"ה של תו\"מ<sup data-n=\"6130\">636</sup> שלמעלה מגופו של תומ\"צ שזה יהי' בחי' כתר שם טוב דמשיח<sup data-n=\"6131\">637</sup> כו' שהוא בחי' עצם הרצון שלמעלה מן הטעם הכמוס לרצה\"ע, כמו קבלת עומ\"ש שהוא למעלה מן הטעם רק ברצ\"פ ועצמי'<sup data-n=\"6132\">638</sup> והוא [בחי'] ביטול העצמי' הנ\"ל בהכנעה ושפלות לבטל לכל עצמ[ותו] לבד, כמו במ\"ת שא' נעשה כו' שעי\"ז נמשך מבחי' עצמו' אור א\"ס שבפנימי' הכת\"ר שזהו אנכי מי שאנכי<sup data-n=\"6133\">639</sup> בחי' סדכ\"ס<sup data-n=\"6134\">640</sup> דלמחת\"ב כלל שבא בגילוי דוקא מן ההעלם ולהיות הוי' אלקיך ממש. וזפ\"י<sup data-n=\"6135\">641</sup> דקדש להוי' מלמטה למעלה שעושה אתעדל\"ע מקדושה דאור הכתר בחכ' דתומ\"צ כו' (משא\"כ מדרגה הב' דשם הוי' שבציץ <span data-k=\"pg\">תקנז</span> ּ שהי' כתוב למעלה שלא בא לגילוי מן ההעלם עדיין ונק' עונג ורצון הנעלם בעצמי' ממש כמשי\"ת וד\"ל.\n<b>והנה</b> מעתה י\"ל ענין שם הוי' שכתוב מלמעלה בשיטה העליונה והוא שם הוי' בלבד ולמה לא חלקו לב' תיבות הללו בשלימותן כמו שהן שקדש יהי' כתוב למטה ותיבת לה'",[["6123","629","<b>א\"ק</b>: ראה הערה 627."],["6124","630","<b>הקה\"ע</b>: אכא: (ה)קדושה העליונה."],["6125","631","<b>כנ\"ל</b>: כא: בלב."],["6126","632","<b>מפני</b>: שם: ליתא."],["6127","633","<b>כנ\"ל</b>: שם: ליתא."],["6128","634","<b>בעה\"ר</b>: א: הרצון. כא: בעהר\"צ בעל הרצון."],["6129","635","<b>כת\"ר שבכתר מקור כל הרצונות</b>: ראה אלימה רבתי עין הבדולח תמר א פ\"ח."],["6130","636","<b>הקים על עול\"ה של תו\"מ</b>: שמו\"ב כג, א. ראה במדב\"ר פי\"ח, כא. מאמרי אדה\"א שמות ח\"א ע' רכה. וש\"נ."],["6131","637","<b>כתר שם טוב דמשיח</b>: ראה גם לעיל פ' בשלח קנו, ב הערה 303."],["6132","638","<b>ועצמי'</b>: א: ועצמי. כא: ליתא."],["6133","639","<b>אנכי מי שאנכי</b>: נסמן לעיל פ' יתרו רנד, ג."],["6134","640","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["6135","641","<b>וזפ\"י</b>: אכא: וזהו פי'."]]],[2300550721,"למעלה, אלא כתבו קדש למ\"ד למטה ושם הוי' בלבד למעלה (ואף שהי' כתוב קדש למ\"ד בתחלת שטה התחתונה ושם הוי' בסוף שטה הראשונה<sup data-n=\"6136\">642</sup> שאל\"כ [לא] הי' נק' כסדרן קדש להוי' כו'). אך הנה ידוע בענין בפנימי'<sup data-n=\"6137\">643</sup> הוי' בענין יגמה\"ר שא' ויקרא הוי' הוי'<sup data-n=\"6138\">644</sup> אל רחום כו' דפסיק טעמא בגווייהו<sup data-n=\"6139\">645</sup> לפי שאין ערך כלל לשם הוי' הב' לגבי שם הוי' הא' כו'. וביאור הענין הנה ידוע שבבחי' אור הכתר יש ב' מדרגות פנימי' וחיצוני' שנק' או\"כ, הגם שבבחי' הכתר למעלה מבחי' כלים מגבילים עכ\"ז יש בו בחי' העלם וגילוי עכ\"פ דהיינו כמו ענין גילוי הרצון מהעלם<sup data-n=\"6140\">646</sup> הרצון כמ[ו] שאו' יהי רצון מלפניך<sup data-n=\"6141\">647</sup> כו' כמשא\"ר<sup data-n=\"6142\">648</sup> באדם למטה שיש ב' מדרגות ברצון, א' רצון הבא בגילוי בדבר מה שרוצה בו באופן פרטי כך וכך, ואמנם יהי' [ב]רצון זה הנגלה שינויים וחילופי' רבים שלפעמים ירצה כך וכך ולפעמים כך וכך ויכול להתחלף כמו מחסד לדין ומדין לחסד בריבוי שינוי אופנים שונים. וכמו\"כ יש כמה מיני רצון הנובעים באדם תמיד שמתגלים מבחי' ההעלם בשינויים משעה לשעה כו', כמו שנובע השכל במוח האדם מן ההעלם שהוא מקור השכל שמשכיל כל שכל לגילוי אור שכל וסברא כך וכך, ולפעמים יטה השכל כלפי חסד דוקא ולפעמים יטה כלפי דין ובאופנים שונים ובשינויים לפעמים כך ו[ל]פעמים כך, שכ\"ז אופן השינוי הבא בגילוי שכל הוא נובע ממקור השכל שלפעמים נובע ממקור מיוחד לחסד מן ההעלם לגילוי ולפעמים נובע מן ההעלם [ו]מקור השכל [ל]היפוכו, א\"כ בהכרח לומר דכמו שא[נו] ר[ואים] התחלקות אופני השכל והסברא בגילוי לחסד או לדין כך יהי' התחלקות אופנים אלה במקור השכל, שבשביל גילוי אותיות השכל להטות כלפי חסד נובע ממקור מיוחד שמשפיע מן ההעלם לגילוי בבחי' הטיה לחסד וכן להיפוך בהעלם השכל שבא לגילוי לדין וחוב, וזהו שנק' פנימי' וחיצוני' בחכ' ושכל.\n<b>וכך</b> הוא באור הכתר שהוא בחי' הרצון שלמעלה מן השכל והחכ' לגמרי כידוע שאין טעם לרצון כלל<sup data-n=\"6143\">649</sup> אפילו טעם כמוס בהעלם כו'. ולפי\"ז גם בגילוי אור הרצון שנובע מלמעלה מן ההעלם, שהוא מקור המוליד המשכת הרצון כמו שיש מקור להמשכת אור השכל כנ\"ל, שיש בו התחלקו' להמשיך רצון של חסד או להמשיך רצון של דין וחו\"ב כנ\"ל בחו\"ג דחכמה. וזהו סיבת השינוי רצון שרואי' באדם שלפעמים ירצה כך ולפעמים בהיפוך שכ\"ז נמשך מלמעלה מגילוי רצון, דהיינו בכח והעלם הרצון שמתחלק גם הוא לב' הטיות, דהיינו שלפעמים נובע מהעלם הרצון להיות גילוי רצון של חסד שזהו מקור מיוחד לרצון של חסד ולפעמים ימשיך מן ההעלם הרצון בבחי' מקור",[["6136","642","<b>קדש למ\"ד. . הראשונה</b>: תוד\"ה קדש סוכה ה, א."],["6137","643","<b>בפנימי'</b>: א: ב' פעמים. כא: ב\"פ."],["6138","644","<b>ויקרא הוי' הוי'</b>: תשא לד, ו."],["6139","645","<b>דפסיק טעמא בגווייהו</b>: ראה זהר (אד\"ר) נשא קלח, רע\"א. לעיל פ' בשלח קנז, ב הערה 361."],["6140","646","<b>מהעלם</b>: א: והעלם."],["6141","647","<b>יהי רצון מלפניך</b>: בברכות השחר. ועוד."],["6142","648","<b>כמשא\"ר</b>: אכו: כמו שאנו רואים."],["6143","649","<b>שאין טעם לרצון כלל</b>: ראה של\"ה בית ה' [ד, ב בהגה] בשם ר' יוסף אלקשטילי. לעיל פ' בא פט, ד הערה 145."]]],[2300550724,"<span data-k=\"pg\">1116</span> ּ מיוחד להיות גילוי הרצון לדין וחוב ובשינויים וחילופים רבים לפי העת כנ\"ל וד\"ל (וכמו העלם המחשבה שבא לגילוי בדבור באותיות שלפי אופן גילוי אוה\"ד<sup data-n=\"6144\">650</sup> כך [י]הי' אופן האותיות דמח' שבהעלם שבא לגילוי כמצייר ציור בכתב כפי אופן הציור במחשבה כידוע). וזהו בחי' פנימי' וחיצוניות דאור הכתר שלמעלה שהוא בחי' רצה\"ע שלמעלה מן החכמה עליונה (אפילו מטעם כמוס שהוא בחי' ח\"ס טעם כמוס [ל]רצה\"ע<sup data-n=\"6145\">651</sup> כידוע) שיש בו ב' מדרגות דהעלם וגילוי כמו ברצון הנגלה באדם שיש לכל רצון מקור מיוחד בהעלם כו' והשינוי הנראה ברצון הנגלה לפעמים כך כו', זהו מצד השינוי רצון שבהעלם שנמשך לגילוי בהיפוך מרצה\"ק<sup data-n=\"6146\">652</sup> כמו בהעלם וגילוי בשכל במוח כו'. אך א\"כ י\"ל מ[ה] שאו' יהי רצון מלפניך שיכבשו רחמיך את כעסך כו', הלא ב' מדות אלה דרחמים וכעס הן ב' הפכי' בתכלית שבא בגילוי מן הרצון [הנעלם, ואחר שכבר בא בגילוי מן ההעלם לרוגז וכעס איך יהופך לרחמים<sup data-n=\"6147\">653</sup>, והלא שינוי זה צ\"ל בהעלם ומקור הרצון] שישונה מדין לחסד ורחמים, ומאין יהי' שינוי זה במקור הרצון [לשנות מהיפוך להיפוך כמו וינחם ה' על הרעה<sup data-n=\"6148\">654</sup> כו', ולא עוד אלא שיכבשו רחמיך כו' שיהי' הרצון<sup data-n=\"6149\">655</sup> ] של רחמים וחסד גובר על רצון של דין ורוגז, וכמו ברוגז רחם תזכור<sup data-n=\"6150\">656</sup> להפוך הרוגז לחסד ורחמים וכמו ולא אבה ה' לשמוע אל בלעם שהוא [הי'] המקטרג לעורר רצון של דין ורוגז ויהפוך את הקללה לברכה כי אהבך כו', ואיך נהפך הדין לחסד במקורו בעצמות בעה\"ר להפוך הקללה של הדין לברכה כי אהבך כו' ומה יועיל האהבה בזה כו' (וכן י\"ל מארז\"ל הקב\"ה מתפלל כו' מאי מצלי יה\"ר<sup data-n=\"6151\">657</sup> מלפני שיגולו רחמי על בני כו', וזהו פלא מה שייך בזה ענין התפלה שמתפלל בעצמו שיהי' רצון מלפניו שיגולו רחמיו לגבור<sup data-n=\"6152\">658</sup> על מדה\"ד שברצונו כו').\n<b>אך</b> הנה בהכרח לומר שיש עוד בחי' ומדרגה עליונה יותר שלמעלה גם מבחי' העלם הרצון שבא לגילוי באופנים שונים, והוא בבחי' עצמות בעה\"ר שנמשך ממנו מקור כללי לכל הרצונות הבאים בהעלם וגילוי הנ\"ל, כמו שיש כח ומקור השכל הכללי שנק' כח המשכיל ההיולי שממנו יומשך כל מקור שכל בפרט לחסד או לדין וקודם שיומשך מכח היולי זה מקור מיוחד לשכל של חסד או של דין הכל כלולים בו בכח ובהעלם עצמי ופשוט בלי נובע עדיין גם מקור [להמשכות] שכל בגילוי מן ההעלם לא לחסד ולא לדין, וע\"כ ממנו דוקא יכול להיות שינוי וחילוף משכל של חסד להפוך לשכל של דין בקו המשקולת המכריע מימין לשמאל וכן להיפוך מכריע משכל של דין להיות שכל של חסד גם במקורם בהעלם, משא\"כ כאשר [כבר] בא במקור מיוחד בהעלם לחסד דלא יהופך לדין כו' וד\"ל.",[["6144","650","<b>אוה\"ד</b>: אכא: אותיות הדיבור."],["6145","651","<b>ח\"ס טעם כמוס [ל]רצה\"ע</b>: נסמן לעיל שסא, ב."],["6146","652","<b>מרצה\"ק</b>: כא: מרצון הקדום."],["6147","653","<b>לרחמים</b>: א: ניתוסף: וחסד."],["6148","654","<b>וינחם ה' על הרעה</b>: תשא לד, יב."],["6149","655","<b>הרצון</b>: א: כח הרצון."],["6150","656","<b>ברוגז רחם תזכור</b>: חבקוק ג, ב."],["6151","657","<b>הקב\"ה. . מצלי יה\"ר</b>: ראה ברכות ז, א."],["6152","658","<b>לגבור</b>: כא: ליתא."]]],[2300550727,"<b>וכך</b> יובן ג\"כ ברצון שלמעלה מן השכל לגמרי שיכול להיות הכרעה לרצון של דין לחסד או להיפך גם במקור הרצון כנ\"ל, והוא בעצמות בעה\"ר שממנו נמשך מקור כח היולי כללי שכולל כל מיני רצון שיולדו בגילוי מן ההעלם שנק' מקור כל הרצונות שבהעלם וגילוי, שממנו יוכל להיות שינוי [מ]רצון של דין לחסד גם בהעלם במקור הנובע להיותו עדיין למעלה גם מבחי' נביעת הרצון אף בהעלם, רק שהוא בחי' מקור כח היולי כללי <span data-k=\"pg\">תקנח</span> ּ שכולל כ\"מ שעתיד לנבוע ממנו כל מיני רצון בהעלם ובגילוי כו'. וכך יובן למעלה שמטעם זה או' יה\"ר מלפניך ממש שהוא עצמות בעה\"ר כו' שיכבשו רחמיך את כעסך דהיינו להפוך מרצון של דין ורוגז גם בהעלם שיהי' מכריע לרצון של חסד ורחמים בהעלם שיבא לגילוי מטעם שהוא מקור היולי עדיין שיכול לשנות מרצון לרצון כנ\"ל וד\"ל.\n<b>אך</b> הנה עכ\"ז עדיין אין זה מובן לכאורה דא\"כ מהו שמבקשים יה\"ר מלפניך כו' שזהו מצד ע[צמות] כח היולי דרצה\"ע שיכול להפוך מרצון של דין לחסד, הרי מזה הטעם עצמו יכול להיות משם בהיפך שיהופך מרצון של חסד לדין וא\"כ במה יוכרע יותר שיהי' רצון מלפני[ו] להיות מרצון של דין לחסד ולא מרצון של חסד לדין אחר שהוא למעלה עדיין מהטיית הרצון לחו\"ג לגמרי כנ\"ל (ואם מפני בחי' הדעת דכת\"ר שבכתר שלמעלה מטעם כמוס כנ\"ל שהוא גם במקור הרצון שיחולק לחו\"ג יש כח המכריע מימין לשמאל ומשמאל לימין כקו המשקולת ונק' ד\"ע כידוע ומבואר (בדרוש דארדה נא בפ' וירא<sup data-n=\"6153\">659</sup> ) אבל הוא גופא י\"ל דלמה יכריע קו המשקולת דבחי' ד\"ע זה יותר משמאל לימין מהכרעה מימין לשמאל מאחר שהטעם הוא רק להיותו למעלה עדיין מהתחלקות רצון גם בהעלם כו' כנ\"ל). ואמנם באמת הנה אינו דומה בחי' כח<sup data-n=\"6154\">660</sup> היולי דרצה\"ע שלמעלה מן החכ' לגמרי לכח היולי דחכמה הנ\"ל שממנו יוכל להחליף משכל של חסד לדין ומדין לחסד בשוה (ע\"י דעת נוטה<sup data-n=\"6155\">661</sup> שנק' דע\"ת כידוע), שזהו שנק' אדם בחו\"מ<sup data-n=\"6156\">662</sup> שגם הרצון בא במורכב מהעלם לגילוי בשכל כו'. ואמנם בחי' כח היולי דרצה\"ע עצמו אע\"פ שמתחלק גם הוא לחו\"ג בעצם הרצון עצמו כנ\"ל, מ\"מ בבחי' ההכרעה מרצון לרצון שנק' שינוי רצון עכ\"פ אע\"פ שנא' בו כי לא אד\"ם הוא להנח\"ם ולהשתנות מרצון לרצון דשינוי המדות מן השכל ורצון הבא במורכב כו', אבל מכריע תמיד משמאל לימין ולא [מימין] לשמאל לפי שבעצמות בעהר\"צ<sup data-n=\"6157\">663</sup> אין בו אפי' מקור למקור לנטי' דקו השמאל בבחי' הדין רק בבחי' הטוב וחסד בעצם שכולו טוב (וכמאמר דלית שמאלא בהאי ע\"י<sup data-n=\"6158\">664</sup> ). והוא שנק' רעדכ\"ר עילאין כידוע שע\"ז אמר יהי רצון מלפניך דוקא",[["6153","659","<b>בדרוש דארדה נא בפ' וירא</b>: ראה תו\"ח שם קיג, א ואילך."],["6154","660","<b>כח</b>: כא: ליתא."],["6155","661","<b>דעת נוטה</b>: ראה גם לעיל פ' שמות מב, א. וש\"נ."],["6156","662","<b>בחו\"מ</b>: א: בתו\"מ(!). כא: בחכ' ומדות. וראה גם לעיל הערה 512."],["6157","663","<b>בעהר\"צ</b>: א: בעה\"ר העליון."],["6158","664","<b>דלית שמאלא בהאי ע\"י</b>: ראה זהר (אד\"ר) נשא קכט, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."]]],[2300550730,"שיכבשו רחמיך כו' דמשם יכול להיות בתמידי' התגברות הרצון של חסד ורחמים על רצון של דין ורוגז להמתיק[ו] בלי שינוי וחילוף לעולם שלא להיות בהיפוך כלל מטעם שכולו רק טוב בעצם וד\"ל. כי פי' רעוא דכ\"ר אינו רק כמו ענין מקור כללי לכל הרצונות שמשם יוכל להיות גם להיפך מחסד לדין, אלא שהוא בבחי' מקור כללי שממנו מתגלה רק בחי' רצון טוב וחסד בהעלם וגילוי ולא יהי' ממנו שום נטי' לדין כלל, וכמו באו\"פ<sup data-n=\"6159\">665</sup> מלך שפניו מאירים ברוב עונג ושמחה אז יאיר במצחא דוקא הארת אור רב טוב וחסד בעצם עד שיפעלו ממנו אז כל הארת אור רצון טוב בגילוי ונק' עת רצון כמו ואני תפלתי<sup data-n=\"6160\">666</sup> כו', וכן בעת רצון עניתי\"ך<sup data-n=\"6161\">667</sup> בעת רצון דוקא שהוא בשעה שמאיר במצחא דע\"י מבחי' <span data-k=\"pg\">1118</span> ּ רעדכ\"ר מקור כל רצון טוב וחסד, כי הרצון הטוב שבא רק מחמת עצם טובו ומקור כללי לכל רצון טוב ונק' רעדכ\"ר וכמובן<sup data-n=\"6162\">669</sup> בזהר בפי' רעוא שאינו רק בחי' רצון של חסד וטוב כמו יהא רעוא קדמך<sup data-n=\"6163\">670</sup> כו' שהוא בחי' עת רצון העליון בהארת או\"פ מלך כו' כמו במנחה דשבת<sup data-n=\"6164\">668</sup> כידוע. וגם פי' רעוא זה היינו ענין ריעות שהוא אהבה וריעות של חיבה יתירה שבין איש לרעהו כנפשו, דפי' רעוא לשון ריעות כריעים האהובים שכל נפשו נקשר ונמשך בו שממילא יומשך אליו רק כל רצון טוב וחסד יתירה וכמבואר במ\"א בפי' ותרועת מלך בו<sup data-n=\"6165\">671</sup> תרועה זו לשון ריעות וחיבה יתירה דקוב\"ה בכנס\"י מבחי' רעדכ\"ר כו', וכמו האהוב למלך ביותר שכל רצונו וחפצו תמיד אליו רק להטיב כו' וכמו והנערה אשר חפץ בה המלך<sup data-n=\"6166\">672</sup> וכמ\"ש בזהר זכאה ב\"נ דקוב\"ה אתרעי בי'<sup data-n=\"6167\">673</sup> כו' (והוא כאב את בן ירצ\"ה תמיד רק לטוב ואין בו נטיה לדין ולחוב כמ\"ש לא הביט און ביעקב כנ\"ל ).\n<b>וזהו</b> ונרצה לו לכפר עליו<sup data-n=\"6168\">674</sup> וכן והיה על מצחו תמיד לרצון בתמידות בלי שינוי לדין לעולם, וראי' שהרי הי' הציץ מכפר על עון המקדש<sup data-n=\"6169\">675</sup> (כמשי\"ת) כי מכריע תמיד משמאל לימין ולא מימין לשמאל אף שבא בהטיות דחו\"ג שברצון מכריע מגבו' לחסד, וז[הו] שאו' יה\"ר מלפניך דוקא שזהו בחי' [ה]המשכה מרעדכ\"ר עילאין שנק' עת רצון הטוב בעצם (בבחי' כת\"ר שבכת\"ר שלמעלה גם מחכמה שבו המטה כלפי חו\"ג, שבזה אמר כי לא אד\"ם הוא להנחם מדין לחסד כמו בשאול שא' נחמתי כי המלכתי<sup data-n=\"6170\">676</sup> כו' ולא הי' בו שינוי לחסד. וז\"ש וגם נצח ישראל<sup data-n=\"6171\">677</sup> שזהו נצח דכתר עצמו שלמעלה מבחי' אדם דחכ' דכת\"ר שבדין אין חסד כלל ובחסד אין דין כלל מצד תוקף המדות דרצון בעצם, אבל בחי' כת\"ר שבכת\"ר בחי' מקור כללי",[["6159","665","<b>באו\"פ</b>: אכא: באור פני."],["6160","666","<b>ואני תפלתי</b>: תהלים סט, יד."],["6161","667","<b>בעת רצון עניתי\"ך</b>: ישעי' מט, ח."],["6162","669","<b>וכמובן</b>: כא: וכמבואר."],["6163","670","<b>יהא רעוא קדמך</b>: זהר ויקהל רו, א."],["6164","668","<b>רעדכ\"ר. . במנחה דשבת</b>: נסמן לעיל שנט, ב."],["6165","671","<b>ותרועת מלך בו</b>: בלק כג, כא. וברש\"י שם. ראה מאמרי אדה\"ז תקס\"ד ר\"ע קפ. ע' קפד. ע' קפה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו\"ת בלק עב, ב</a>. מאמרי אדה\"א במדבר ח\"ד ע' א'תקמח ואילך. ע' א'תקעו."],["6166","672","<b>והנערה אשר חפץ בה המלך</b>: ראה אסתר ב, יג-יד. לעיל פ' בא קכה, ד הערה 599."],["6167","673","<b>זכאה ב\"נ דקוב\"ה אתרעי בי'</b>: ראה זהר שלח קסא, א. ח\"ש קכט, א."],["6168","674","<b>ונרצה לו לכפר עליו</b>: ויקרא א, ד."],["6169","675","<b>הציץ מכפר על עון המקדש</b>: ראה לעיל הערה 555."],["6170","676","<b>נחמתי כי המלכתי </b>[כא: ניתוסף: את שאול]: שמו\"א טו, יא."],["6171","677","<b>וגם נצח ישראל</b>: שמו\"א טו, כט."]]],[2300550733,"בכח היולי לכל תולדות הרצון שם מאיר מעצמות אור א\"ס שכולו טוב בעצם שזהו בחי' רעדכ\"ר שינחם על הרעה כו', אף ברעה שאין לה סליחה ע\"פ משפט התורה כלל כי גם בבחי' חכ' שבתורה יש שינוי תמיד מחסד לדין ומדין לחסד ע\"פ הטעם דרצה\"ע. אך עכ\"ז יש בירור והבדלה בין טמא לטהור<sup data-n=\"6172\">678</sup> בין טו\"ר שאם אין דעת דתורה אין הבדלה וזהו עיקר שם מ\"ה דתיקון באד\"ם כו'. אך עכ\"ז הרי יוכל להיות סליחת העוונות לעוברי רצונו ביו\"כ ע\"י יגמה\"ר דרעדכ\"ר כנ\"ל למעלה מהבדלה דתורה בח\"ס<sup data-n=\"6173\">679</sup> כו' אף שלא אד\"ם הוא להנח\"ם, מ\"מ מדין לחסד ינחם כמו וינחם ה' כו', והוא מצד בחי' עצם הטוב דרעדכ\"ר שמרבה לסלוח גם לעוברי רצונו בתו\"מ. כידוע כי גם המצות יש בהן ב' מדרגות, א' רצה\"ע שבא בד\"פ<sup data-n=\"6174\">680</sup> בטעם כמוס לרצון בכל מצוה, ויש מקור כללי לכולם בשוה טרם שמתחלקי' <span data-k=\"pg\">תקנט</span> ּ לחו\"ג כמו ברמ\"ח מ\"ע ושס\"ה ל\"ת הכלולים באנכי ולא יהי'<sup data-n=\"6175\">681</sup> כו' מבחי' כת\"ר דאנכ\"י שבא בגילוי בשם הוי' דחכמה דתור\"ה<sup data-n=\"6176\">682</sup> כמ\"ש אנכי הוי'<sup data-n=\"6177\">683</sup> כו' כנ\"ל. ועכ\"ז לא יוכל להשתנות גם במקור הכללי דרצה\"ע שבמצות מצד ההבדלה בפנימי' ועצמי' הרצון דוקא שנק' כת\"ר שבכת\"ר וע\"כ לא יהופך הטמא לטהור והפסול לכשר לעולם כו', אך ע\"י יגמדה\"ר דרעדכ\"ר<sup data-n=\"6178\">684</sup> יהופך מדין לחסד למחול העון שע\"פ התורה מטעם הנ\"ל, שא\"כ בהכרח למעלה משם הוי' דתו\"מ שירד מאנכי כו' ששם למעלה גם מן המצות כמו אם צדקת<sup data-n=\"6179\">685</sup> כו', דהיינו למעלה גם מבחי' ההבדלה שבפנימי' הרצון וחכמה ע\"כ יהופך גם הזדונות לזכיות ביו\"כ. וזהו בחי' עונג ורצון אשר הוא בבחי' [ה]העלם ממש במהו\"ע ית' ממש שנק' שעה\"מ<sup data-n=\"6180\">686</sup> בעצמו כמו בעוה\"ב שלמעלה מן העונג ורצה\"ע שבמצות והוא הוי' הוי' אל רחום כו' שמאיר ביו\"כ במצחא כו' וד\"ל. וזהו בפנימי' הוי' דאל רחום א', הוי' הב'<sup data-n=\"6181\">687</sup> לעבור על החכמה דתורה להיות אל רחום ונושא עון כו' שזהו רק בהארת הרצון העצמי שלמעלה מהתחלקות הרצון במצות לחו\"ג כו' שהוא ג\"כ מהפך מדין לחסד ע\"י רחמים וזהו הוי'<sup data-n=\"6182\">688</sup> אל רחום כו', והוי' הב' למעלה מזה הוא ההמשכה [ד]רעדכ\"ר עצמו שנמשך מעצמות א\"ס ממש שיהא נמשך הטוב בעצם שאין בו נטי' לדין כלל שנק' רעדכ\"ר שצריך להיות ע\"י המשכה מיוחדת, והיינו קדוש ומובדל בערך גם מהמשכות הרחמים רבים בהוי' הב' לסליחת העוונות, אלא שהוי' הא' דרעדכ\"ר הוא מקור להוי' הב' [והיינו שמהוה כל הויו\"ת די\"ג מדה\"ר בפרט. וז\"ש ויקרא ה' ה' שקרא והמשיך מהוי' הא' שבעצמו' להמשיך רעדכ\"ר להוי' הב'] שיהא בא בגילוי הרצון הטוב לסלוח העוונות בפו\"מ להיות רחום וחנון כו' ונושא עון למטה ממש וד\"ל.",[["6172","678","<b>בין טמא לטהור</b>: כא: ליתא. ואולי נשמט מפני תיבות הדומות: בין. . בין."],["6173","679","<b>בח\"ס</b>: א: בחכ'."],["6174","680","<b>בד\"פ</b>: א: בדרך פרט."],["6175","681","<b>ברמ\"ח מ\"ע ושס\"ה. . באנכי ולא יהי'</b>: נסמן לעיל פ' יתרו רנב, א."],["6176","682","<b>דתור\"ה</b>: א: בתו\"מ."],["6177","683","<b>אנכי הוי'</b>: יתרו כ, ב."],["6178","684","<b>דרעדכ\"ר</b>: א: ליתא."],["6179","685","<b>אם צדקת</b>: איוב לה, ז."],["6180","686","<b>שעה\"מ</b>: אכא: שעשועי המלך."],["6181","687","<b>א' הוי' הב'</b>: א: הוי' הא'."],["6182","688","<b>הוי'</b>: א: ליתא."]]],[2300550736,"<b>וזהו</b> ג\"כ [ענין] שא' קדש למ\"ד למטה והוי' מלמעלה כנ\"ל, דהנה בציץ היו ב' מדרגות ברצה\"ע הנ\"ל, והא'<sup data-n=\"6183\">689</sup> בחי' רצון הנגלה<sup data-n=\"6184\">690</sup> מן ההעלם שנמשך בתו\"מ והוא ע\"י מע[שה] המצ[ות] שעולה הקדושה מלמטה למעלה בבחי' או\"ח כנ\"ל, שזהו קדש ל' למטה כו' ורוח אייתי רוח כו' להמשיך מקדושת<sup data-n=\"6185\">691</sup> אור הכתר בחכמה שזהו שם הוי' דאנכי בבחי' מקור הרצה\"ע דתו\"מ (שבא בבחי' הבדלה בפנימית ועצמית הרצון כמו שהי' במ\"ת כנ\"ל<sup data-n=\"6186\">692</sup>. והמדרגה הב' בבחי' מקור כל הרצונות עליונות [ש]למעלה מרצון דתו\"מ, והוא [ב]בחי' רעדכ\"ר הנ\"ל שיש לו המשכה מיוחדת בפ\"ע מן ההעלם דעצמות אוא\"ס ממש (שנק' שעה\"מ בע[צמו]<sup data-n=\"6187\">693</sup> שיתגלה בעוה\"ב כנ\"ל), והוא נמשך ג\"כ ע\"י שם הוי' שנמשך ע\"י בחי' רעדכ\"ר עצמו מעצמות המאציל ממש שהוא למעלה הרבה מקדושת המצות ברצה\"ע הנגלה מן ההעלם כנ\"ל (והיינו בפנימי' הוי' הנז' ביגמה\"ר כו'), ששניהם למעלה ממשפט התורה שהוא סליחת העוונות לעו\"ר<sup data-n=\"6188\">694</sup> להיות הרחוק קרוב וגם הטמא יטהר כמ\"ש לפני הוי' תטהרו, והוא הוי' הב' דאל רחום כו' שמקבל מהוי' הא' דרעדכ\"ר שמהוה כל בחי' הוי' בפרט במחילת העוונות ופסיק טעמא בינייהו<sup data-n=\"6189\">695</sup>, לפי שאין ערוך כלל ביניהם שזהו בחי' עונג הנעלם בעצמות ממש כנ\"ל שאינו בא לגילוי במורגש (רק בעוה\"ב), ועכ\"ז נמשך דרך דילוג<sup data-n=\"6190\">696</sup> בהוי' הב' להיות ממנו סליחת <span data-k=\"pg\">1120</span> ּ העוונות בפו\"מ כנ\"ל וד\"ל.\n<b>וזהו</b> ג\"כ ענין שם הוי' הכתוב בציץ למעלה שהוא כמו הוי' הא' שבי\"ג מדה\"ר והיינו להיות נמשך בחי' רעדכ\"ר עצמו במצחא דאהרן ע\"י הציץ (כמשי\"ת), וע\"כ לא הי' כתוב שם הוי' זה בלמ\"ד להוי' אלא הוי' סתם להיות מהוה כל הוי[ו]' בפרט. וע\"כ הי' כתוב קדש למ\"ד מלמטה שיהא עולה קדושת המצות למעלה בשם הוי' שכתוב למעלה שהוא בחי' רעדכ\"ר שיה[י'] רצויים לפני הוי' זה כל המצות כאב את בן ירצה כנ\"ל, שמפני שאהבת האב לבן בחי' עצמי' ממש בריעות וחיבה יתירה כמו ברעדכ\"ר באו\"פ מלך כו' ע\"כ כל מעשיו רצויים בעצמי' ופ[נימי'] התעה\"פ<sup data-n=\"6191\">697</sup> הנעלם הנ\"ל. וזהו הכח בעצם הטוב הזה להגביר כח החסד על כח הדין עד שלא יאבה לשמוע למקטרג כבלעם ויהפוך הקללה לברכה כי אהבך כו' ע\"כ מהפך גם הדין לחסד והיינו רק מחמת כח האה\"ר העצמית ממש (וזש\"א יה\"ר מלפני שיגולו רחמי על בני דוקא, כנ\"ל בענין הגורלות דיו\"כ",[["6183","689","<b>והא'</b>: א: והוא. כא: הא'."],["6184","690","<b>הנגלה</b>: כח: הנולד."],["6185","691","<b>מקדושת</b>: שם: מנקוד'."],["6186","692","<b>כנ\"ל</b>: שם: ממש וד\"ל."],["6187","693","<b>שעה\"מ בע[צמו]</b>: נסמן לעיל פ' תרומה שיח, ב."],["6188","694","<b>לעו\"ר</b>: אכא: לעוברי רצונו."],["6189","695","<b>בינייהו</b>: שם: בגווייהו. וראה גם לעיל בפנים על יד הערה 645."],["6190","696","<b>דילוג</b>: כא: דילוג גדול."],["6191","697","<b>התעה\"פ</b>: א: התענוג הפשוט."]]],[2300550739,"שגם ברוממות הע[צמות] ממש נבחרו בבחי' פנימי' ועצמי' ע\"כ מתפלל בעצמו שיומשך בחי' רעדכ\"ר מן הע[צמות] שלו שנק' בעה\"ר שיגולו רחמי' מן ההעלם שיהי'<sup data-n=\"6192\">698</sup> רצון מוחלט כבר וא\"צ רק לעורר בציץ להיות זכרון לבד כו' וד\"ל.\n<b>והנה</b> מעתה י\"ל מ\"ש אחר ופתחת עליו כו' קדש להוי' והי' על מצח אהרן ונשא אהרן את עון הקדשים אשר יקדישו בנ\"י כו' עד והי' על מצחו תמיד לרצון לפני ה' כו' (וקודם לזה א' ושמת אותו על פתיל תכלת<sup data-n=\"6193\">699</sup> והי' על המצנפת אל מול פני המצנפת יהי' ואח\"כ א' והי' על מצח אהרן כו', ולפ\"ז המצנפת למעלה מן הציץ בגובה הראש והציץ במצח למטה (כי תפילין הי' בראשו בין ציץ למצנפת כמארז\"ל שערו הי' נראה בין ציץ למצנפת<sup data-n=\"6194\">700</sup> ששם הי' מניח תפילין כו' (וע' פרש\"י<sup data-n=\"6195\">701</sup> ), וא\"כ מצנפת למעלה מעלה<sup data-n=\"6196\">702</sup> מן התפילין והתפילין למעלה מן הציץ (דלא כמ\"ש בלק\"ת<sup data-n=\"6197\">703</sup> דתפילין הי' למטה מן הציץ כי הציץ במוחין דאבא והתפילין במוחין דאימא כי ציץ לשון זכר<sup data-n=\"6198\">704</sup> ע\"ש דזהו נגד המשנה הנ\"ל<sup data-n=\"6199\">705</sup>, ובאמת תפילין במוחין דחב\"ד<sup data-n=\"6200\">706</sup> דכת\"ר בפ' קדש והי' כו' שהן ג' חללי גלגלתא<sup data-n=\"6201\">707</sup> (כמשי\"ת) והציץ שעשה משה הוא בבחי' פנימי' יס\"א<sup data-n=\"6202\">708</sup> שבו פנימי' יסוד דע\"י שמתגלה שם מרעדכ\"ר כו' וע\"כ הוא לשון זכר ומקיפי' דתפילין למעלה מן המקיף דציץ שמקבל מן המצנפת שהוא בגלגלתא עצמו ע\"י התפילין כו' כמשי\"ת). דהנה מבואר למעלה שה[י'] בענין הציץ ב' תנאים, א' שיעשנו משה דוקא מטעם הנ\"ל (שהוא בבחי' פנימי' חכמה בבחי' מ\"ה בעצם בהמשכת אור דתורה כנ\"ל). והב' שי[ו]נח הציץ על מצח אהרן דוקא, כי בחי' אהרן מבואר ג\"כ למעלה שנק' שוש' דמטרוניתא ונק' רועה לכנ\"י באהבה רבה שיעורר בלב כאו\"א תמיד כו' כנ\"ל וע\"כ הי' הציץ על אהרן דוקא שבו וע\"י יאיר לישראל מרדכ\"ר כו'.\n<b>אך</b> הנה מ\"ש על מצח אהרן דוקא, הנה יש להקדים תחלה ענין א' הידוע בזהר (בענין תפילין בפ' ואתחנן עיי' בסידור הנדפס<sup data-n=\"6203\">709</sup> ) שיש ג' חללי גלגלתא והן ג' מוחין דחב\"ד (ונחלקים לד' מוחין כמו בד' <span data-k=\"pg\">תקס</span> ּ פרשיות דתפילין קדש והי' כו' ע\"י בחי' הדעת שנתחלק לחו\"ג<sup data-n=\"6204\">710</sup> כידוע. וז\"ש ובדעת חדרים ימלאון<sup data-n=\"6205\">711</sup> שהן ל\"ב חדרים שבמוח<sup data-n=\"6206\">712</sup> בפרט בד' מוחין הללו שנחלק כ\"א לח' כו' גימ' ל\"ב שהן ל\"ב שבילין דמתפתחין במוחא<sup data-n=\"6207\">713</sup> כו'). אך זהו במוחין דחב\"ד שנחלקו באו\"כ שתחת קרומא דחפיא<sup data-n=\"6208\">714</sup> כו',",[["6192","698","<b>שיהי'</b>: אכא: שהי'."],["6193","699","<b>ושמת אותו על פתיל תכלת</b>: תצוה כח, לז."],["6194","700","<b>שערו הי' נראה בין ציץ למצנפת</b>: זבחים יט, א. ערכין ג, ב."],["6195","701","<b>פרש\"י</b>: תצוה כח, לז."],["6196","702","<b>מעלה</b>: אכא: ליתא."],["6197","703","<b>דלא כמ\"ש בלק\"ת</b>: טעמי המצות תצוה ד\"ה מצות ציץ נזר הקודש. וכ\"ה גם בקהלת יעקב מערכת ציץ (ד\"ה ציץ ה\"ס)."],["6198","704","<b>ציץ לשון זכר</b>: ראה גם לעיל שנט, א הערה 2."],["6199","705","<b>נגד המשנה הנ\"ל</b>: כ\"ה בהכת\"י. ראה לעיל הערה 700."],["6200","706","<b>דחב\"ד</b>: כא: דאבא דחב\"ד."],["6201","707","<b>ג' חללי גלגלתא</b>: ראה זהר ואתחנן רסב, א. (אד\"ר) נשא קמ, א. וראה גם לעיל פ' שמות כג, ד. וש\"נ."],["6202","708","<b>והציץ. . יס\"א </b>[אכא: יסוד אבא]: ראה גם טעמי המצות שם. מאו\"א מערכת ציץ סי\"ט. ולהעיר מטעמי המצות שם ד\"ה מצות אפוד: הציץ. . מיסוד אימא. ובאור זרוע למהר\"מ פאפרוש לשם (רנו, א). זהר הרקיע ויקהל ריז, ב."],["6203","709","<b>בסידור הנדפס</b>: שער התפילין ו, ג ואילך."],["6204","710","<b>הדעת שנתחלק לחו\"ג</b>: נסמן לעיל שנג, א הערה 462."],["6205","711","<b>ובדעת חדרים ימלאון</b>: משלי כד, ד [ושם: ימלאו — ראה לעיל פ' שמות מב, א בהערה 229]."],["6206","712","<b>ל\"ב חדרים שבמוח</b>: ראה לעיל פ' בא קח, א."],["6207","713","<b>ל\"ב שבילין דמתפתחין במוחא</b>: ראה זהר (אד\"ר) נשא קכח, ב. קלו, א."],["6208","714","<b>קרומא דחפיא</b>: ראה זהר שם קכח, ב."]]],[2300550742,"דמוח החכ' באו\"כ מיוחד כידוע דמוח החכ' קר ולח<sup data-n=\"6209\">715</sup> ומוח הבינה חם ויבש ומוח הדעת הוא בחי' ממוצע והוא בחי' אמ\"ר<sup data-n=\"6210\">716</sup> כידוע. אבל יש עוד למעלה מקרומא זה דחפיא על מוחא בחלל הגלגלתא שזהו למעלה אצל הקרום העליון שדבוק לגלגלת[א] עצמה שנק' קרומא דאוירא<sup data-n=\"6211\">717</sup> כו', שזהו נק' חללי גלגלתא דוקא ולא חללי מוחין, שהן בחי' מקיפי' דחב\"ד כמו שהן בבחי' הכת\"ר שנק' גלגלתא<sup data-n=\"6212\">718</sup> עצמה כידוע, ובחי' חכ' שבכת\"ר נק' ח\"ס וכן בינה שבכתר ובחי' דעת נק' ד\"ע דא\"א כידוע שהוא ממוצע בין חו\"ב<sup data-n=\"6213\">719</sup> שבכת\"ר [כ]ענין גדולה דיעה שניתנה בין ב' אותיות י\"ה<sup data-n=\"6214\">720</sup> כו'). והנה מוח הדעת דגלגלתא הוא הממוצע שעומד באמצע בין חו\"ב ועיקר הציץ הי' הנחתו באמצע אע\"פ שהי' מוקף [מאוזן] לא[ו]זן<sup data-n=\"6215\">721</sup>, והוא ע\"י פתיל האמצעי שבאמצע הראש נגד המצנפת שעל זה א' ושמת אותו על פתיל תכלת והי' על המצנפת כו' (עיין פרש\"י ) והיינו שהי' עיקר הציץ שהי' כתוב בו קדש לה' באמצע מוח<sup data-n=\"6216\">723</sup> הראש לנגד מוח הדעת<sup data-n=\"6217\">722</sup> (והוא בחלל האמצעי דגלגלתא כנ\"ל שהוא ד\"ע דכתר (והיינו לנגד מקום הנחת התפילין שבגובה הראש בין ציץ למצנפת) כנ\"ל.\n<b>וביאור</b> ענין בחי' הדעת<sup data-n=\"6218\">724</sup> שנק' ממוצע בין ב' חללי המוחין דחו\"ב (שבהעלם דאור הכתר כנ\"ל שזהו מקור המיוחד הנובע מן ההעלם לגילוי אור השכל במוח להטות לחסד ולזכות או להיפוך, והדעת הוא ד\"ע שמטה למקור הראשון דחו\"ב<sup data-n=\"6219\">725</sup> כו', שזהו הטיי' הרצון דכתר שמחמתו יטה מקור להמשיך לזכות כמו הדמיון מן השוחד כו' כמבואר במ\"א). ומשם נמשך לבחי' ד\"ת שבמוחין דחו\"ב הנגלי' להטות השכל הגלוי כך או כך או בבחי' ממוצע ממש ומזה נחלק לחו\"ג ולל\"ב חדרים ממש, אבל בד\"ע דכת\"ר למעלה עדיין מהתחלקות לחו\"ג רק שכולל הכל וממנו מקור כל הטיות (כמ\"ש בפ' וירא<sup data-n=\"6220\">726</sup> ). וסיבת הטיות הללו ברצון ושכל הנ\"ל<sup data-n=\"6221\">727</sup> הוא מצד בחי' הדעת הזה ששרשו מגיע למעלה מכל הטיות הרצון וחכמה, והטעם הוא כי פי' דעת אינו ענין חכמה ושכל דוקא דא\"כ למה יש בכחו להטות השכל לדבר והיפוכו בין בהעלם בין בגילוי כנ\"ל, אלא עיקר ענינו הוא בחי' כח ההתקשרות<sup data-n=\"6222\">728</sup> שיש באדם דהיינו מה שיש בכחו להתקשר א\"ע בכ[ל] ד[בר] מה בכל ע[צמותו] ממש. והיינו מה שתוקע כל עצמותו בדבר, שהוא בא מצד ענין כח ההרגשה<sup data-n=\"6223\">729</sup> שמרגיש את הדבר וירד לע[ו]מקו בכל עצמותו",[["6209","715","<b>דמוח החכ' קר ולח</b>: ראה גם לעיל פ' שמות כז, ג. וש\"נ."],["6210","716","<b>אמ\"ר</b>: ראה לעיל פ' משפטים רפג, ג הערה 101."],["6211","717","<b>קרומא דאוירא</b>: נסמן לעיל שסא, ג."],["6212","718","<b>הכת\"ר שנק' גלגלתא</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ג."],["6213","719","<b>דעת. . ממוצע בין חו\"ב</b>: ראה גם לעיל פ' וארא פה, ד."],["6214","720","<b>גדולה דיעה. . י\"ה</b>: נסמן לעיל שנה, ב הערה 559."],["6215","721","<b>שהי' מוקף [מאוזן] לא[ו]זן</b>: שבת סג, ב. הובא ברש\"י תצוה כח, לו. רמב\"ם פ\"ט מהל' כלי המקדש ה\"א."],["6216","723","<b>מוח</b>: איגכאכג: מצח."],["6217","722","<b>הציץ. . באמצע מוח הראש לנגד מוח הדעת</b>: ראה גם לעיל שנח, ב. בהערה הבאה."],["6218","724","<b>(והוא. . הדעת</b>: כא: ליתא. וכנראה נשמט מפני תיבות הדומות: הדעת. . הדעת."],["6219","725","<b>ד\"ע שמטה למקור הראשון דחו\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670254\" data-slug=\"torat-chaim\" data-id=\"2300670254\">תו\"ח וירא קיב, ב</a> ואילך."],["6220","726","<b>כמ\"ש בפ' וירא [כ\"ז ליתא ביג]</b>: ראה שם קיב, ג ואילך."],["6221","727","<b>הנ\"ל</b>: אכא: הכל."],["6222","728","<b>דעת. . ההתקשרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. לעיל פ' בשלח קנה, ג. וש\"נ."],["6223","729","<b>דעת. . ההרגשה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא</a> ספמ\"ו. לעיל פ' בא קד, ב הערה 361."]]],[2300550745,"(בל\"א דער קלעפ אין<sup data-n=\"6224\">730</sup> אריין לייגין זיך מיט אלע כחות פנימי' מחמת [דעם] דער הער וואש ער האט דער<sup data-n=\"6225\">731</sup> חוש צו דער הערין זייער דיא זאך זייער טיף כו'), כי מי שאינו מתקשר עצמו [כ\"כ] בדבר אינו מרגישו כ\"כ. ונמצא שבדעת יש בו ב' דברים הללו כח ההתקשרות עד שתוקע כל עצמו בדבר וגם כח ההרגשה שמרגיש ומכיר בדבר ביותר מזולת[ו] כו' וד\"ל. ובחי' ההתקשרות וכח ההרגשה הזאת היא כולל<sup data-n=\"6226\">732</sup> והיולי לכ[ל] ד[בר] כפי שהוא <span data-k=\"pg\">1122</span> ּ אם הוא בדבר חכמה ושכל מתקשר בכל ע[צמותו] בה<sup data-n=\"6227\">733</sup> (ער קלע‘[ט] זיך זייער „ריין און איז זיך מתקשר בהתקשרות<sup data-n=\"6228\">734</sup> כל עצמות שלו<sup data-n=\"6229\">735</sup> כנ\"ל ), ואז יכול כח התקשרות זאת לירד לעומק השכל במקורו הראשון עד שיטהו לכמה אופנים שונים וממוצעי' רבים כו'. וכן אם התקשרות באהבה דבר מה יהי' בו בחי' ההרגשה בתכלית בכל עצמותו כמו שמרגיש א\"ע (וידוע דהכח ההרגשה שמרגיש א\"ע ביותר זהו עיקר בחי' הדעת (כי קטן שאין לו דעת<sup data-n=\"6230\">736</sup> אינו מרגיש א\"ע כו'<sup data-n=\"6231\">737</sup> וע\"כ אינו מרגיש לזולתו לרחם עליו, וכל מי שיש בו דעת יותר יותר ירגיש ברחמנות על זולתו השפל, וכן יותר ירגיש בכאב ויסורים כמו יוסיף<sup data-n=\"6232\">738</sup> דעת יוסיף מכאוב<sup data-n=\"6233\">739</sup>, ויותר יפחד בעצמו להיות מרגיש א\"ע ביותר וכן בהתפשטות המדות באהבה וחמדה או יראה ופחד הכל תלוי בבחי' הדעת דוקא. והיינו ענין ב' כחות הנ\"ל כח ההתקשרות בדבר וכח ההרגשה שזהו בגידי המוח של המוח<sup data-n=\"6234\">740</sup> דוקא ששם הוא כח ההרגשה שמרגיש א\"ע ביותר וכל כאב שבאברים כו' וכן להרגיש בכ[ל] ד[בר] זולתו דהיינו הך כו', ובגידי הרגשה הללו שם הוא כח ההתקשרו' לקשר ולתקוע א\"ע בכ[ל] ד[בר] שרוצה אם בשכל או במדות כו', דהא בהא תליא שבמקום א' הן כח ההרגשה וכח ההתקשרו' שהוא במוח הדעת דוקא שהוא כח התוקף וחוזק שיש במוח זה דדעת בתוקף הרגשת עצמו ותוקף התקשרות העמוקה בדבר כו' (וע\"כ נק' דעתן שעומד על דעתו ותקיף בדעתו (וגם שהנשים דעתן קלות<sup data-n=\"6235\">741</sup> מ\"מ כח התקשרותן יותר חזק וכן הרגשתם לפי שהוא בקו א' לבד<sup data-n=\"6236\">742</sup> כמבואר במ\"א).\n<b>אך</b> עדיין אין זה מובן דמה שייכות יש לב' כחות הללו דהתקשרות והרגשה כא' במקום א' שהוא כלי מוח הדעת דוקא, דלכאורה הן ב' דברים וענינים נפרדי' דכח ההתקשרות [ה]ו[א] לחוץ ממנו וכח הרגשה הוא בעצמו דוקא כנ\"ל. אמנם הענין הוא דכח ההתקשרות בחוץ ממנו תלוי בכח ההרגשה",[["6224","730","<b>אין</b>: אכא: און."],["6225","731","<b>דער</b>: שם: דעם."],["6226","732","<b>היא כולל</b>: א: הוא כח כללי. כא: הוא כח הכולל."],["6227","733","<b>בה</b>: א: בל\"א. יגכאכג: כבפנים."],["6228","734","<b>איז. . בהתקשרות</b>: כא: ער איז זיך זייער מתקשר."],["6229","735","<b>עצמות שלו</b>: א: עצמו. כא: עצמיו'."],["6230","736","<b>קטן שאין לו דעת</b>: ראה חגיגה ב, ב. גיטין כב, סע\"ב. כג, א."],["6231","737","<b>כו'</b>: כא: כ\"כ."],["6232","738","<b>כמו יוסיף</b>: כא: ויוסיף."],["6233","739","<b>ויוסיף דעת יוסיף מכאוב</b>: קהלת א, יח. ראה גם לעיל פ' בא קד, ב. וש\"נ."],["6234","740","<b>המוח</b>: אכא: הדעת."],["6235","741","<b>שהנשים דעתן קלות</b>: שבת לג, ב. ראה לעיל פ' בא פח, א. וש\"נ."],["6236","742","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680300\" data-slug=\"torat-chaim\" data-id=\"2300680300\">שהנשים. . בקו א</a>' לבד</b>: ראה ד\"ה והי' לכם לציצית תקס\"ה נדפס בסידור שער הק\"ש פ, ד. אמ\"ב שם סד, ד. מאמרי אדה\"א במדבר ח\"ג ע' א'רסז ואילך. תו\"ח וישלח קצב, ד."]]],[2300550748,"בעצמו דוקא, לפי שבאמת שרש בחי' ההרגשה בעצמו<sup data-n=\"6237\">743</sup> ביותר זהו מתפשט מכח הרצון דוקא, דהיינו מה שיש בנפש כח הרצון להתיישב דבר מה, שיש בנפש כח הרצון<sup data-n=\"6238\">744</sup> להתמשך [אל] דבר מה שזהו המשכת הנפש והטייתו שנוטה לדבר חוץ ממנו כמו שירצה האדם בממון או במאכל ולבוש וכה\"ג הרי נפשו נמשכת לחוץ מעצמות[ו]. וע\"כ נק' הרצון בשם נפש<sup data-n=\"6239\">745</sup> ממש כמו נפשי אויתיך<sup data-n=\"6240\">746</sup> כו' היש את נפשך<sup data-n=\"6241\">747</sup> אין נפשי<sup data-n=\"6242\">748</sup> אל העם הזה<sup data-n=\"6243\">749</sup> כו', כי הרצון הוא חלק נמשך מן הנפש עצמה כמו צמאה לך נפשי<sup data-n=\"6244\">750</sup> אע\"פ שאינה רק המשכת הרצון לבד [רק] שהוא בפ[נימי'] הרצון דוקא והיינו בחי' התע[נוג] שמלובש ברצון שבלעדי התע[נוג] שבנפש לדבר מה אין להמשכת הרצון אליו קיום כלל, דמחמת התע[נוג] הזה הוא שבא לכלל המשכת הרצון ולשון רצון הוא ענין מרוצה<sup data-n=\"6245\">751</sup> שתרוץ הנפש לדבר מה שמתענג בו דוקא (וכמו\"כ יש בהיפוך, שע\"י הרצון שירצה [ו]יחפוץ בדבר מה אז מתענג בו ואם אין לו רצון לדבר אין לו עונג בו כלל שנמצא העונג חיצוני' והרצון פנימי', ואעפ\"י דמה שנראה לעין הוא הרצון דוקא והעונג מתעלם בו כו' <span data-k=\"pg\">תקסא</span> ּ זהו כשהעונג פנימי והרצון חיצוני אבל להיפך כשהרצון פנימי הרצון מוסתר והעונג נראה לעין כמו גם באה\"ר בתענוגים הנראה לעין שזהו רק מצד הרצון הפנימי הנעלם בו שבלעדו לא היה מתענג כלל כו').\n<b>והנה</b> א\"ר ששרש הרצון הוא במוח דוקא והוא בגידי המוח ששם כח ההרגשה<sup data-n=\"6246\">752</sup> להרגיש בכל עצמו ובכל אברי הגוף כנ\"ל, והיינו במוח הדעת דוקא כנ\"ל שהוא כח המרגיש בעצמו ולחוץ ממנו כנ\"ל. וא\"כ מובן שיש ברצון בחי' ההרגשה ובחי' ההתקשרות הנ\"ל, דהיינו מה שעיקר סיבת ההתפשטות והמשכת כח הרצון מן הנפש לחבר א\"ע בדבר זולתו שנק' כח המחבר לחוץ מעצמו זהו בא רק מכח של ההרגשה בעצמו שהוא מוח הדעת שכ[ל] מ[ה] שמרגיש א\"ע ביותר יבא מזה התפשטות הרצון שהוא בחי' ההתקשרות של הנפש לדבר חוץ ממנו, שמזה הטעם אין השראת הרצון רק בגידי ההרגשה דוקא, כמו גם מה שיעלה במוחו התעוררו' רצון לילך ברגל ולהניע בידו זה אינו רק מחמת בחי' ההרגשה שיש בנפש ע\"כ מתפשט חוץ ממנו, וכ\"ש לתאוות המאכל או הממון שתלוי כל רצונות הנולדים בזה אם רב אם מעט הכל בבחי' [ה]הרגש[ה]<sup data-n=\"6247\">753</sup> שמרגיש א\"ע, וכל מי שאינו מרגיש א\"ע כ\"כ אינו נמשך ברצון להתקשר בחוץ ממנו כ\"כ (וראי' כשגידי ההרגשה הנק' נערוי\"ן חלושי' לא יבא להתפעלות הרצון והמשכת תאוה כלל כזקן וחולה וכה\"ג כידוע). ונמצא",[["6237","743","<b>בעצמו</b>: בתורת חיים כאן נכפלו עוד הפעם התיבות: דוקא כנ\"ל. . בעצמו."],["6238","744","<b>דהיינו. . הרצון</b>: איגכג: דהיינו מה [יגכג: שיש] בנפש כח הרצון. כא: ליתא."],["6239","745","<b>נק' הרצון בשם נפש</b>: ראה גם לעיל פ' וארא עט, ג. וש\"נ."],["6240","746","<b>נפשי אויתיך</b>: ישעי' כו, ט."],["6241","747","<b>היש את נפשך</b>: חיי שרה כג, ח. מלכים-ב ט, טו [ושם: אם יש (את) נפשכם — ראה לעיל פ' בשלח רב, א הערה 931]."],["6242","748","<b>היש את נפשך אין נפשי</b>: ראה לקוטי שיחות לך כרך ב ע' 456 בהערה."],["6243","749","<b>אין נפשי אל העם הזה</b>: ירמי' טו, א ובתרגום־ רש\"י ורד\"ק שם."],["6244","750","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["6245","751","<b>ולשון רצון. . מרוצה</b>: ראה גם לקמן פ' ויקהל תלח, ג. מאמרי אדה\"א נ\"ך ע' תפו. וש\"נ."],["6246","752","<b>הרצון. . בגידי המוח. . ההרגשה</b>: ראה גם לעיל שנח, ב הערה 94."],["6247","753","<b>שיש בנפש. . בבחי' [ה]הרגש[ה]</b>: א: ליתא. וכנראה נשמט מפני תיבות הדומות: בחי' ההרגשה. ֿ. בבחי' [ה]הרגש[ה]."]]],[2300550751,"דסיבת כח ההרגשה וכח ההתקשרות בבחי' הדעת הכל בא מן כח הרצון שבנפש שבא מצד טבע הרגשת עצמו שזה דוקא שיוכל להיות שימשיך כל עצמו בדבר כו', אמנם זהו דוקא בבחי' פנימי' הרצון שהוא<sup data-n=\"6248\">754</sup> מן פנימי' העונג דהיינו מבחי' הפנימי' ועצמי' הנפש ממש שהוא כח הרגשת עצמות ממש שזהו שמתלבש במוח הדעת דוקא (וראי' לזה הוא מ[ה] שא\"ר דבלא שלימות מוח הדעת אינו מוליד מטפה שבמוח כמו פחות מבן ט'<sup data-n=\"6249\">755</sup> או זקן וסריס וכה\"ג, וכמו והאדם ידע את חוה<sup data-n=\"6250\">756</sup> כו' שבחי' דעת זה הוא בחי' פנימי' כח ההרגשה שבנפש ששם הוא פנימי' ועצמי' התענוג עליון<sup data-n=\"6251\">757</sup> ורצון, והוא בחי' כח ההתקשרות יתירה שבנפש לחוץ ממנו כמו והאדם ידע כו' שמזה סימן שיוכל להוליד מזרעו דבר חוץ ממנו כו', וכמו שאין קישוי אלא לדעת<sup data-n=\"6252\">758</sup> דוקא [שבא] מכח ההרגשה שבמוח הדעת כו', וא\"ל אינו מוליד אע\"פ שיש לו מוחין דחב\"ד בשלימות (כמבואר במ\"א) (וגם סיבת כל ההטיות מרצון ושכל ומדות כנ\"ל שבא מן הדעת דוקא (בד\"ע וד\"ת כנ\"ל) הכל הוא בא רק מצד בחי' הכח של ההרגשה בנפש שה[ו]א המטה את הרצון והשכל מהיפך להיפך ממש (וראי' מן השוחד שיעור עיני חכמים<sup data-n=\"6253\">759</sup> להטות משפט השכל מצד הטי' ברצון לזכות יותר, וסיבת ההטיי' זו לרצון ממקור הרצון<sup data-n=\"6254\">760</sup> זהו מצד בחי' ההרגשה בנפשו להשוחד שהוא טובת עצמו שהרגיש בזה ביותר, ולפ\"ע ההרגשה זו כך יטה רצונו לדבר כנ\"ל. וכן בהפרש בין אוהב לשונא שיטה רצונו לאוהב כמו שיטה משפט מחוב לזכות כמו הרגשת <span data-k=\"pg\">1124</span> ּ עצמו שאינו רואה חוב לעצמו כו' וכאב את בן ירצה לפי שמרגישו כמו עצמו שממנו נולד כו', ולשונאו יטה רצונו ושכלו לחוב מצד [העדר] הרגשתו בתכלית שמזה יבא סיבת האכזריות גם בקטן וחסר דעת כו'). ונמצא מובן עכ\"פ מכ\"ז שבחי' כח ההתקשרות עצמי' שבמוח הדעת זהו עיקר פנימי' כח הרצון שבנפש ופנימי' ועצמי' התענוג שבה (שמטעם זה אין כח המוליד בטפה הרוחני' רק במוח הדעת כנ\"ל), וזהו כידוע שבחי' פנימי' הדעת שהוא קו האמצעי שרשו בפנימי' הכת\"ר<sup data-n=\"6255\">761</sup> דוקא דהיינו בד\"ע שלמעלה מחו\"ב והוא בכת\"ר שבכת\"ר שלמעלה גם מההתחלקות חו\"ג דרצון העליון כו' כנ\"ל רק שהוא כולל [כ[ל] מ[ה] שעתיד להתחלק למטה בדע\"ת כו' כנ\"ל בענין ג' חללי גלגלתא כו' וד\"ל.\n<b>והנה</b> הדוגמא מכ\"ז יובן ג\"כ בבחי' דעת בנה\"א כמ\"ש אתה הראת לדעת<sup data-n=\"6256\">762</sup> כי כו', וכן וידעת היום<sup data-n=\"6257\">763</sup>, וכך בכמה מקומות שמצוה על בחי' הדעת כמו דוד שאמר לשלמה ואתה",[["6248","754","<b>שהוא</b>: כא: שבא."],["6249","755","<b>אינו מוליד. . פחות מבן ט'</b>: ראה נדה לב, ב."],["6250","756","<b>והאדם ידע את חוה</b>: בראשית ד, א."],["6251","757","<b>עליון</b>: אכא: ליתא."],["6252","758","<b>שאין קישוי אלא לדעת</b>: נסמן לעיל שנח, ב הערה 95."],["6253","759","<b>השוחד שיעור עיני חכמים</b>: פ' שופטים טז, יט."],["6254","760","<b>הרצון</b>: כא: השכל."],["6255","761","<b>הדעת. . בפנימי' הכת\"ר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380512\" data-slug=\"likkutei-torah\" data-id=\"4001380512\">לקוטי תורה שלח נ, א</a>."],["6256","762","<b>אתה הראת לדעת</b>: ואתחנן ד, לה."],["6257","763","<b>וידעת היום</b>: ואתחנן שם, לד."]]],[2300550754,"בני דע את אלקי<sup data-n=\"6258\">765</sup> אביך<sup data-n=\"6259\">764</sup> כו', וכן בכל דרכיך דעהו<sup data-n=\"6260\">766</sup> כו', כ\"ז אין הפי' בהשגה שכל וחכמה בהתבוננות דוקא. אלא ענינו הוא בחי' כח ההכרה וההרגשה שיכיר את בוראו בדעת שלימה כמו שמרגיש חיי עצמו (בל\"א דער הערין שטארק זייער אין מוח ולב) איך שהוא בורא את הכל והוא חיינו האמיתי וחוש ההרגשה הזאת ביותר זהו בחי' דעת דקדושה, והיינו בחי' כח ההתקשרו' שמתקשר כל עצמו באלקים חיים (דער קלעפ און אריין לייגין מיט גאר דעם נפש אין אלקות [כו']) שבזה יש בחי' פנימית [הרצון] שזהו הטיות כל רצון רק לטוב שהוא לידבק בה' לבדו ופנימי' התענוג שמחמתו מתקשר כל רצונו הפנימי' כנ\"ל<sup data-n=\"6261\">767</sup> (עד שהוא ניזוז ונעתק ממקומו לגמרי, כי יש בכח ההתקשרות ועומק ההרגשה והכרה הזאת באלקות או בפנימי' סודות<sup data-n=\"6262\">768</sup> התורה וכה\"ג בנגלה, כמו ב\"ע שחשקה נפשו בתורה<sup data-n=\"6263\">769</sup> עד שיצא ויופשט מכל עצמי' ממש רק בה' לבדו כו', וכמו נשמת משה<sup data-n=\"6264\">770</sup> שהי' מבחי' פנימי' הדעת דקדושה שעולה עד פנימי' התע[נוג] ורצון שזהו פנימי' ד\"ע<sup data-n=\"6265\">771</sup> דכתר כנ\"ל, וע\"כ כל הטיות רצון העליון שבמצות הכל הי' ע\"י דוקא. וכן נשמת אברהם שהכיר את בוראו מיד בהולדו<sup data-n=\"6266\">772</sup> ויצא לאויר העולם דידיעה והכרה זו היתה בבחי' הרגשה והתקשרות חושיו בכל פנימי' עצמו[תו] עד שניזוז ונעתק ממקומו לגמרי ממש כו') (וכמו לע\"ל שידע כל פעול<sup data-n=\"6267\">773</sup> כו' וכתיב ומלאה הארץ דעה את ה'<sup data-n=\"6268\">774</sup> כו', וכך פי' ד\"ע את אלקי כו' וידעת היום כי ה' הוא האלקי' שזהו רק בחי' חוש ההכרה וההרגשה והתקשרות בכל עצמו ביחו\"ע ויחו\"ת דהוי' הוא האלקי' ממש). וכמו\"כ מלמעלה למטה הרי אמר רק אתכם ידעתי<sup data-n=\"6269\">775</sup> מכל כו', ידיעה זו בחי' הכרה והרגשה ע\"י בחי' התקשרות מד\"ע כמו וידע אלקי'<sup data-n=\"6270\">776</sup> (וזה הי' בציץ שהי' מונח לנגד מוח הדעת דוקא במצח אהרן (כמשי\"ת).\n<b>אך</b> כ\"ז הוא בבחי' דעת דקדושה שהוא בחי' ההתקשרות וחוש ההרגשה לצאת מעצמו' כנ\"ל, וזהו מבחי' ד\"ע וד\"ת ברצון וח[כ'] ומ[דות] דקדושה האלקי', אבל זה לעומת זה עשה<sup data-n=\"6271\">777</sup> כו' הוא בחי' דעת דקליפה כמו בלעם <span data-k=\"pg\">תקסב</span> ּ ששרשו בדעת<sup data-n=\"6272\">778</sup> דק\"נ שהוא בלעם<sup data-n=\"6273\">779</sup> בן בעור וכמו ובלע<sup data-n=\"6274\">780</sup> את הקדש<sup data-n=\"6275\">781</sup> דחכמה שהוא לנגד דעת דמשה כמ\"ש ויודע דעת עליון<sup data-n=\"6276\">782</sup> מאחוריים דעורף שלנגד מוח הדעת הפנימי' שבמצח כו' כידוע. והענין הוא שכל בחי' הדעת דק\"נ הוא רק כח ההרגשה וההתקשרות בפנימי' הרצון ועונג הע[צמי] רק לגרמי' דוקא שהוא רק",[["6258","765","<b>אלקי אביך</b>: א: ה' אלקיך(!)."],["6259","764","<b>ועתה בני </b>[כא: ליתא]<b> דע את אלקי אביך</b>: דהי\"א כח, ט [בדילוג]. ראה סידור שער הלולב רסג, סע\"ג ואילך. מאמרי אדה\"א נ\"ך ע' פט."],["6260","766","<b>בכל דרכיך דעהו</b>: משלי ג, ו."],["6261","767","<b>כנ\"ל</b>: אכא: כו'."],["6262","768","<b>סודות</b>: כא: ליתא."],["6263","769","<b>ב\"ע שחשקה נפשו בתורה</b>: ראה יבמות סג, ב. לעיל פ' בשלח רלט, א הערה 1061."],["6264","770","<b>נשמת משה</b>: ראה גם לעיל שנח, ג."],["6265","771","<b>ד\"ע</b>: א: רצון."],["6266","772","<b>אברהם שהכיר את בוראו מיד בהולדו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670130\" data-slug=\"likkutei-sichot\" data-id=\"1301670130\">לקו\"ש וירא כרך לה ע' 68</a> ואילך הערות 51. 52."],["6267","773","<b>שידע כל פעול</b>: תפלת העמידה לר\"ה."],["6268","774","<b>ומלאה הארץ דעה את ה'</b>: ישעי' יא, ט [ושם: כי מלאה — נסמן לעיל פ' בשלח קס, ד]."],["6269","775","<b>רק אתכם ידעתי</b>: עמוס ג, ב. ראה גם לקמן פ' ויקהל תלח, א."],["6270","776","<b>וידע אלקי'</b>: שמות ב, כה."],["6271","777","<b>זה לעומת זה עשה</b>: קהלת ז, יד. ראה גם לעיל פ' יתרו רנא, ג הערה 45."],["6272","778","<b>בלעם ששרשו בדעת</b>: ראה זהר בלק קצד, א. ע\"ח (שער הארת המוחין) של\"ב, פ\"ב. מאמרי אדה\"א דברים ח\"ב ע' תרמג. וש\"נ."],["6273","779","<b>בלעם</b>: כאכג: בלע."],["6274","780","<b>בלע. . ובלע</b>: ראה גם לעיל פ' שמות מב, ב. וש\"נ."],["6275","781","<b>ובלע את הקדש</b>: כ\"ה בהכת\"י. וראה הערה שלפנ\"ז."],["6276","782","<b>ויודע דעת עליון</b>: בלק כד, טז."]]],[2300550757,"להרגיש ולהתקשר בעצמו ולא ליזוז ממקומו בדבר מה חוץ מעצמו כלל, ע\"כ א\"א שיהי' לע\"ש דנוגה גם בשרשם שמקבלים מדעת שלהם שמתפשט בז' מ[דות] דק\"נ בחי' הביטול והזזה להכיר ולהרגיש את בוראם אע\"פ דקרו לי' אלקא דאלקיי'<sup data-n=\"6277\">783</sup> כו', וגם בלעם א' לא אוכל לעבור<sup data-n=\"6278\">784</sup> את פי ה' כו'. כי כל דעתם והתקשרותם רק לעצמם דוקא היפך הביטול, וכמו שרואה אדם בנה\"ט שיש בה תוקף ההרגשה רק לעצמו ע\"כ מתאוה בכל תאוה רק למלאות רצונו ונפשו כמו הלעיטני נא כו', וכן [ו]בטן רשעים תחסר, וכן א' לעלוקה כו' הב הב כו' (בל\"א נ ר צו זיך ניט פון זיך כו'). וזהו מבחי' הדעת לרע ולא לטוב, שבעה\"ד טו\"ר נחלק [לב'] מדרגות, יודעי טוב להרגיש בטוב ואינו יודע להרגיש ברע כלל, ויודע רע אינו מרגיש רק רע, ויודעי טו\"ר זהו בחי' התערובות טו\"ר שבנה\"ט שנעשה מסיבת החטא שאכל מעה\"ד טו\"ר (והוא מה שיש תוקף וגסות ב[רע ד]נה\"ט בחוצפא דעמלק בעקשות ונצחון מטעם הנ\"ל לפי שאין בהם בחי' דעת האלקי כלל ע\"כ הן בבחי' יש נפרד כמו מצחך נחושה<sup data-n=\"6279\">785</sup> כו' כמצח אשה זונה כו', ולהיפך מזה הוא בחי' תוקף הביטול בהתקשרות הדעת דקדושה במצח דוקא, שזה הי' ענין הנחת הציץ במצח אהרן דוקא במוח הדעת (כמשי\"ת).\n<b>אך</b> הנה ענין ג' חללי גלגלתא שהן ג' מוחין [ד]חב\"ד כנ\"ל (אע\"פ שהן בבחי' חב\"ד שבכת\"ר שבחלל הריקן למעלה מן המוחין ממש כנ\"ל), ומ\"מ נק' בחי' מוחין ע\"ש בחי' העלם ומקור לחב\"ד<sup data-n=\"6280\">786</sup> הנגלית ממש כנ\"ל, הרי הן טמונים ומכוסים ונעלמים תחת עצם הגלגלת[א] עצמה, דעצם הגלגלתא חופה עליהם כידוע דגלגלתא היא דחפיא על מוחא<sup data-n=\"6281\">787</sup> (דהיינו גם על מ[ו]\"ס כו'). וא\"כ בהכרח מזה לומר שיש בבחי' עצם הגלגלתא כח חזק עליון יותר גם ממוח הדעת (שהוא המטה לחו\"ג ושרש[ו] בכת\"ר שבכת\"ר הנ\"ל), אע\"פ שמוח הדעת יש בו מבחי' פנימי' הרצון ופנימי' התע[נוג] שנק' פנימי' הכתר בכלל כנ\"ל, אחר שהעצם דגלגלת חופה עליו והדעת נכסה תחתיו הרי עצם הגלגלת בבחי' מקיף עליו וידוע דכל מקיף גדול מן הניקף בתוכו<sup data-n=\"6282\">788</sup> (אע\"פ שהגלגלת אינה רק עצם פשוט בחי' דומם גשמי כעצם המצח כו').\n<b>והנה</b> ענין כח החזק ותקיף הזה שיש בגלגלתא יותר גם מכח פנימי' הרצון שבדעת הנ\"ל נראה שזה בחוש הטבעית",[["6277","783","<b>דקרו לי' אלקא דאלקיי'</b>: מנחות בסופה."],["6278","784","<b>לא אוכל לעבור</b>: בלק כב, יח."],["6279","785","<b>מצחך נחושה</b>: ישעי' מח, ד [ושם: ומצחך — וכ\"ה לעיל על יד הערה 542]."],["6280","786","<b>לחב\"ד</b>: א: לחו\"ב."],["6281","787","<b>דגלגלתא היא דחפיא על מוחא</b>: ראה זהר (אד\"ר) נשא קכח, ב."],["6282","788","<b>דכל מקיף גדול מן הניקף בתוכו</b>: ראה גם לעיל פ' וארא נח, ד ובהערה 25. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381173\" data-slug=\"likkutei-torah\" data-id=\"4001381173\">לקו\"ת שה\"ש יא, א</a>."]]],[2300550760,"באדם למטה והוא בעבודת ה' בתפלה, דהנה א\"ר בעבודה שבלב זו תפלה<sup data-n=\"6283\">789</sup> וק\"ש בהעמיק אדם דעתו בטוב בהתבוננו' ביחו\"ע ויחו\"ת וכה\"ג בשש\"מ<sup data-n=\"6284\">790</sup> בפסוד\"ז עד שמקשר א\"ע בכל פנימי' <span data-k=\"pg\">1126</span> ּ עצמי' ותוקע כל עומק ושכל ועומק פנימית רצונו ומדותיו באוי\"ר אמיתית רק לה' לבדו (כי ניזוז ממקומו לגמרי מעוצם חוש ההרגשה וההכרה והתקשרות כל עצמו באלקי' בהשגה והתבוננות זו שבמוח הדעת כנ\"ל). הנה עכ\"ז א[נו רואים] שמיד אחר התפלה וק\"ש אחר זמן מה בצאתו בהילוכו בשוק או במלאכתו בביתו חולפת ועוברת כל התפעלות פנימי' הרצון וההתקשרות שהי' מלובש במוח הדעת ובלב כאלו לא הי' במציאות מעולם כידוע לכל, ובודאי א\"א ל[ומר] מפני זה השינוי והחילוף שלא הי' התפעלות הרצון והתקשרות הלב אמיתי בעת התפלה כלל, כי ודאי הי' אמת, כי זהו כח פעולתו של בחי' הפנימי' מוח הדעת אלקי דקדושה כנ\"ל. רק שאין הארתו וכח התפשטותו מתקיים זמן רב, וכ\"ש בעת עסקו וטרדתו בעניני גופו שאז מסיח דעתו לגמרי מענין ההשגה והתבוננות באלקים שהי' במוחו ולבו בתפלה ע\"כ ממילא יפול הנופל בעניני רצונות הזרים שלא לה' המה כו', כי היסח הדעת היינו שהוסח והוזז כח הדעת שהוא תקיעת והתקשרות הנ\"ל וגורם השכחה לגמרי עד שלא נשאר אף רושם זכרון מזה כנ\"ל<sup data-n=\"6285\">791</sup> וד\"ל. אמנם הנה א\"ר לעין שיש הרבה בנ\"א שנשאר אצלם בחי' הרשימו מאת ההתפעלות פנימי' הרצון וההתקשרות והרגשה דבחי' הדעת הנ\"ל גם כל היום אפי' בעת עסקו במו\"מ ושארי צרכי גופו בטרדא גדולה מאד עכ\"ז מיד נז[כר] על ה' הבורא הכל להתקשר בו בכל עצמ[ו]' רצונו אף שאינו בפנימי' המוח והלב כלל, מ\"מ בבחי' רושם עכ\"פ נשאר אצלו כמו בכל דרכיך דעהו כו'. הענין הוא שא\"ז<sup data-n=\"6286\">792</sup> בא מרושם של הדעת שהוא בחי' ההתקשרות והרגשה האלקות הנ\"ל שהרי הסיח דעתו לגמרי (וע\"כ הוזהר במצות תפילין למשמש בהן כל שעה שלא יסיח דעתו מהן ק\"ו מציץ<sup data-n=\"6287\">793</sup> (וכמשי\"ת). אלא שרש ענין בחי' רושם הזה שנשאר כל היום כנ\"ל הוא בא מבחי' ההסכם החזק ברצונו שהי' לו בק\"ש ותפלה שכך הוסכם אצלו בהסכם חזק מאד ש[י]הי' הולך בדרכי ה' וידבק בו תמיד כו', והיינו עכ\"פ שלא יסור מדרך הטוב והישר [ד]תו\"מ ויחזק עצמו לילך אחרי ה' ולהיות סומ\"ר וע\"ט כל היום אף שיהי' טרוד מאד בעסקיו [ו]לא ישכח הדבר מלבו ולא ישתקע מחומרי' עוה\"ז לגמרי כו'.\n<b>והנה</b> שרש ענין הסכמה הזאת אע\"פ שה[י]א רק בחיצוני' הרצון לבד ולא בפנימי' הרצון עכ\"ז היא חזקה יותר מן בחי' פנימית הרצון שחולף ועובר מיד כנ\"ל והסכמה זו לא תחלוף ותעבור לעולם, ובהכרח צ\"ל שיש שרש להסכם חזק החיצוני במקור הרצון הממשיך ומוליד כל רצון פנימי' וחיצוני'",[["6283","789","<b>בעבודה שבלב זו תפלה</b>: ראה תענית ב, א. לעיל פ' בשלח קסב, א הערה 13."],["6284","790","<b>בשש\"מ</b>: אכא: בשבחו ש\"מ."],["6285","791","<b>כנ\"ל</b>: א: כלל כנ\"ל. כא: כלל וכלל."],["6286","792","<b>שא\"ז</b>: שם: שאין זה."],["6287","793","<b>במצות תפילין למשמש. . מציץ</b>: ראה שולחן ערוך אדמו\"ר הזקן הלכות תפילין סכ\"ח, ס\"א-ב."]]],[2300550762,"שנק' רצון לרצון כו'. והענין הוא שדוגמא כזו בהסכם והחלט הרצון לבד שנק' רצון לרצון לבד בקבלת התורה שאמ' כל אשר דבר ה' נעשה, הרי עדיין לא שמעו רצונו שיקבלו עליו ברצון פ[נימי] לשמוע בקולו רק אמ' כל אשר דבר ה' ויגלה רצונו לנו נעשה ונקיים, הרי לא הי' זה בבחי' רצון פנימי' <span data-k=\"pg\">תקסג</span> ּ רק שיקבלו עליהם להיות כל רצונם רק במה שירצה ה' ויגזור אומר עליהם יעשו, א\"כ אין זה רק קבלת רצון לרצון דהיינו שיקבלו [לרצון להם בכל אשר ירצה כו', וכמו שמקבלי'] עליהם עול מלכות כמו שום תשים עליך מלך, כך הוא קבלת עומ\"ש שכל אשר יגזור אומר יבטלו רצונם נגד רצונו שזהו ג\"כ קבלת רצון לרצון לבד, דהיינו שמקבל עליו שיהי' רצונו בטל נגד רצונו אף שעדיין לא ביטל רצונו בפנימי' נגד רצון אחר שלא גילה רצונו עדיין. ועכ\"ז קבלת מ\"ש זה שמקבלים עליו יותר חזק מגוף ביטול פנימי' הרצון שאח\"כ כי ממנו דוקא נמשך כל יסוד המלוכה שאח\"כ שנשמעים לרצונו בתכלית הביטול, אע\"פ שלא הי' קבלת עומ\"ש זה רק בחיצוניות רק בהסכם חזק בבחי' רצון לרצון לבד והוא מה שעשה הסכם חזק לקבלת עול זה לבטל רצונו תמיד כו' (וכך הוא בענין קבלת כ[ל] ד[בר] להבא שנק' רצון לרצון לבד, כמו קבלת תענית שמקבל עליו להיות לו רצון מוסכם להתענ[ו]ת ביום מחר שאינו רק בהסכם חזק לזה וממילא יקיים ברצון טוב ומתענה ולא יוכל לשנות אחר שכבר קיבל עליו תענית זה, וכן הנודר ונודב לצדקה או ללמוד מסכת פ[לוני] או להשיא יתום ושאר מצוה מקיים ע\"פ הסכם לרצון זה אע\"פ שאין לו רצון בפנימי' כלל כו'. ואנו מוצאים שגדול כח ההסכם הזה להיות לו רצון לדבר מה שזהו כמו שמקשר א\"ע בשבועה ויותר מזה עד כ[ל] מ[ה] שיהי' אח\"כ מזה בחוזק התפעלות הרצון והחשק לדבר הכל יסודו מן ההסכם שבתחלה שנק' קבלת הרצון [לרצון], כמו בר\"י שראה לר\"ל דקפץ ירדנ[א]<sup data-n=\"6288\">794</sup> כו' אמר חילך לאורייתא שראה בו תוקף הנפש בהסכם שלו הזה שקיבל עליו ללמוד תורה שיהי' חכם גדול דהיינו שחילו רב יהי' לו לחשק הלימוד בתורה אח\"כ ברצון גמור, אע\"פ דבחי' הסכם דקבלה זו דקביל עליה הי' רק להיות [לו] רצון לתורה כו' (וכך הוא בדין וד\"ת דמל' שהמקבל עליו בהסכם ע[ו]ל מל' יענש אח\"כ בעברו על רצונו, וכן ענין נודר ונודב וכה\"ג). וכך הוא ענין ההסכם חזק שהי' בק\"ש ותפלה לילך אחרי ה' ותורתו כו' וכנ\"ל שבחי' הרושם הנשאר מזה כל היום חזק הוא מאד הרבה יותר מהתקשרות והתפעלות הרצון במוח הדעת כנ\"ל שהוא חולף ועובר מיד בהיסח הדעת כנ\"ל<sup data-n=\"6289\">795</sup>, אבל בחי' רשימו דקבלת מל' שמים בהסכם חזק בחיצוני' שנק' רצון לרצון (ובל\"א ער וויל וועלין עש<sup data-n=\"6290\">796</sup> איז בווילונג<sup data-n=\"6291\">797</sup> דעם רצון כו') לא יאבד לעולם אף בגודל טרדתו כנ\"ל.",[["6288","794","<b>בר\"י. . דקפץ ירדנא</b>: בבא מציעא פד, א."],["6289","795","<b>שבחי' הרושם. . כנ\"ל</b>: כא: ליתא. וכנראה נשמט מפני תיבות הדומות: וכנ\"ל [אכא: כנ\"ל]. . כנ\"ל."],["6290","796","<b>עש</b>: כא: ער. כג: כבפנים."],["6291","797","<b>בווילונג</b>: א: ביווילונג. כא: בעווילוג צו. כג: וילונג צו."]]],[2300550764,"<b>(ובמ\"א</b> מבואר שזהו שנק' היכל הרצון כמו באמת<sup data-n=\"6292\">799</sup> ויציב<sup data-n=\"6293\">798</sup>, כידוע שאחר שקיבל עליו עומ\"ש באהבה ורצון כמו ומלכותו ברצון<sup data-n=\"6294\">800</sup> כו' שזהו באה\"ר במס\"נ בפ' ואהבת כו' בכל לבבך ובכל נפשך כו' עדיין א[ין] ז[ה] אמת גמור כי יכול להשתנות וחולפת ועוברת אחר התפלה כנ\"ל, אבל מ[ה] שאו' אמת ויציב ונכון ומתוקן ומקובל וטוב ויפה הדבר הזה עלינו כו' זהו בחי' הסכם החזק על הדבר הזה שכבר קיבל בק\"ש <span data-k=\"pg\">1128</span> ּ שיבא לידי מעשה בפו\"מ בביטול הרצון נגד רצון ה' בתורתו כו'. וז[הו] שאו' ויציב כמו יציבא מלתא<sup data-n=\"6295\">801</sup> כו' וכן ומתוקן ומקובל וטוב ויפה הדבר הזה כו', שאינו אלא כמסכים בהסכמה שטוב ויפה ומקובל עלינו לקיים רצון ה' עי\"ז דוקא מתקיים באמת לענין מעשה כל היום ברשימו שנשאר מזה ההסכם, ע\"כ נק' היכל הרצון שבו שורים כל רצונות הטובים שבאים בגילוי כל היום והוא מאמת לאמת דאהבה ורצון שבק\"ש ובלעדי זה ההסכם שאו' ויציב ונכון אין לאהבה דק\"ש קיום כלל, א\"כ בהכרח לומר שיש להסכמה וקבלה זו שאו' ומקובל וטוב למעלה יותר מאו[ר] פ[נימי'] הרצון שבאהבה דק\"ש וע\"כ ממנו נעשה יחודא עילאה בהיכל קדשי קדשים כו' שהוא בסמיכת גאולה לתפלה<sup data-n=\"6296\">802</sup> כמבואר במ\"א וד\"ל. ומטעם זה אנו מוצאים שגם הכפי' וההכרח שעושים לאדם להיות לו רצון הטוב האלקי במצות עולה בכי טוב כמו שהי' רוצה בפנימית הרצון ממש, והוא ממה שבענין מצות הצדקה כופין אותו<sup data-n=\"6297\">803</sup> עד שיאמר רוצה אני<sup data-n=\"6298\">804</sup> דודאי ע\"י כפי' והכרח אין לו רצון באמת שיאמר רוצה אני כו', עכ\"ז מה שאומר רוצה אני אמת הוא<sup data-n=\"6299\">805</sup> אחר הכפיה זהו שעושין לו כמו בחי' רצון לרצון, לפי שכבר קיבל בסיני לקיים רצון ה' במצות צדקה ורק הגוף אינו מניחו [ו]ע\"י כפי' נגלה בו הסכם הנשאר בנשמתו מכבר וע\"כ או' רוצה אני באמת כו' וד\"ל. וכן מטעם זה גם גט המעושה בישראל כשר<sup data-n=\"6300\">806</sup> כו' מצד קבלת התורה שיש בכאו\"א בהעלם כו' וכמבואר במ\"א. ומזה יובן שגם בחי' כפי' והכרח שמכריח [אדם] א\"ע בהסכם חזק להיות לו רצון לתו\"מ נק' רצון גמור עד שממנו יומשך כל בחי' התפעלות רצון בפנימי' מטעם הנ\"ל, ששרש הסכם זה הוא למעלה גם ממקור המוליד כל רצון פ[נימי'] מן ההעלם והוא בע[צמו'] תוקף כח הנפש בנצחון שהוא חזק מאד לחזק כל רצון כו' (כמשי\"ת).\n<b>והנה</b> כל הנ\"ל בבחי' ההסכם החזק<sup data-n=\"6301\">807</sup> בקבלת רצון לרצון כנ\"ל מקומו ומשכנו הוא במצח שבראש דוקא שבכלי המצח הזה הוא שם שהוא<sup data-n=\"6302\">808</sup> כח ההסכם הזה לעשות רצון לרצון להבא בתוקף גדול מאד עד שלא ישונה ויבוטל לעולם כנ\"ל, ואע\"פ",[["6292","799","<b>היכל הרצון כמו באמת ויציב</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פכ\"ז. מאמרי אדה\"א דברים ח\"ב ע' תז. וש\"נ."],["6293","798","<b>ובמ\"א. . היכל הרצון כמו באמת ויציב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680334\" data-slug=\"torat-chaim\" data-id=\"2300680334\">תו\"ח וישב רי, א</a> ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתקעא. דרך חיים לט, ב."],["6294","800","<b>ומלכותו ברצון</b>: נוסח תפלת ערבית."],["6295","801","<b>ויציב כמו יציבא מילתא</b>: דניאל ו, יג."],["6296","802","<b>בסמיכת גאולה לתפלה</b>: ברכות ט, ב."],["6297","803","<b>מצות הצדקה כופין אותו</b>: ראה שו\"ע יו\"ד סרמ\"ח בתחלתו."],["6298","804","<b>כופין אותו עד שיאמר רוצה אני</b>: לשון תו\"כ ויקרא א, ג. ר\"ה ו, א. וש\"נ (בנוגע לקרבנות — גט)."],["6299","805","<b>רוצה אני אמת הוא</b>: ראה רמב\"ם ספ\"ב מהל' גירושין. מאמרי אדה\"ז תקע\"א ע' קעט ואילך."],["6300","806","<b>גט המעושה בישראל כשר</b>: גיטין פח, ב."],["6301","807","<b>החזק</b>: א: הרצון."],["6302","808","<b>שם שהוא</b>: כא: ליתא."]]],[2300550766,"שהמצח אינו אלא בחי' עצם דומם פשוט, מ\"מ הוא בחי' הכלי דוקא לכח זה שהוא לחזק רצון לרצון בתוקף ועוז להבא כנ\"ל, ולכך הוא חופה ושורה על בחי' מוח הדעת שבפנים בבחי' מקיף חיצוני עכ\"פ כנ\"ל כי גדול כחו הרבה<sup data-n=\"6303\">809</sup> ממנו כנ\"ל עד שממנו יומשך כח וחיזוק בפנימי' הרצון שבמוח הדעת זה (שבהעל\"ם הכת\"ר שיבא לידי גילוי תמיד כנ\"ל בענין קבלת עומ\"ש וקבלת תענית וכה\"ג, שמזה ההסכם יומשך הכח ועוז לרצון פנימי' או בביטול אמיתי לרצון המלך כמו שהי' במ\"ת כשא' נעשה כו') ולפי שבחי' הסכם וקבלה זו אינה נראה לעין רק בחיצוני' שאינו רק בחי' התגלות למראה לבד <span data-k=\"pg\">תקסד</span> ּ ע\"כ בחי' הכלי שלו [אינו]<sup data-n=\"6304\">810</sup> רק בחיצוני' ג\"כ שהוא כלי המצח שהוא עצם פשוט ואין בו אור וחיות רוחני כלל, ועכ\"ז קשה ותקיף הוא הרבה יותר מבחי' הרוחני' דרצון הפנימי והתקשרות דמוח הדעת הפ[נימי] הנ\"ל (שמטה כל רצון ושכל כו' כנ\"ל) וראי' מקבלת התורה ומענין אמת ויציב כנ\"ל) (ועוד ראי' לזה מענין כח הגדול שיש בכאו\"א מישראל למסור נפשו על קדוה\"ש<sup data-n=\"6305\">811</sup> וכן גם בצר לו מאד לא יוכל ליפרד מה' א' לגמרי והוא רק מצד כח ההסכם הזה שהוא המחזק ועושה כל רצון לרצון כו' ולא מצד התפעלות פנימי' הרצון שנק' רצון ה[נ]ולד שחולף ועובר ואינו מתקיים בנסיון כו', משא\"כ בחי' הסכם וניצוח הזה דוקא הוא שעומד בכל הנסיונות הקשים עד מיצוי הנפש ממש, לפי שתוקף וניצוח זה הוא בעצם הנפש ממש שלמעלה גם מבחי' מקור הרצון והתענוג והוא שנק' תוקף כח הנצחון שבנפש עצמה כמו [שנק'] קשה עורף<sup data-n=\"6306\">812</sup>, שזהו עצמו בבחי' הביטול היפוכו במצח דוקא שהוא מול העורף ממש כי בקושי העורף הוא בבחי' לגרמי' שאינו ניזוז ממקומו כלל. וכן בקליפה דעמלק גם במצח דחוצפא ועזות מצח כמצח אשה זונה כו', והיפוכו ממש הוא בבחי' הביטול בתכלית לאין האלקי להיות רצון לרצון בהסכם חזק עד שיוכל למס\"נ באחד ומקבל כל הנסיונות ולא יפול מנקודת יהדותו כו'. וזהו בחי' הכלי דמצד הקדושה<sup data-n=\"6307\">813</sup> שהוא בחי' כלי לבחי' רעוא דכל רעוין ששורה במצח דוקא (כמשי\"ת).\n<b>ובכ\"ז</b> יובן הטעם שציוה ה' שיונח הציץ על מצח אהרן דוקא, כי אהרן שושבינא דמטרוניתא דכללות נשמות ישראל שבמצחו יש בחי' כח ההסכם הכללי דכלל נש\"י בבחי' קבלת רצון לרצון, ואע\"פ שהוא בחיצוני' כמו בקבלת עומ\"ש בלבד אבל הוא מקור ויסוד האמיתי לכל תולדות רצונות הטובים וישרים לילך בדרכי ה' כו' כנ\"ל בין בסומ\"ר בביטול רצון זה<sup data-n=\"6308\">814</sup> ובין בקיום מ\"ע לקי[י]ם רצון ה'. וזהו ענין אותיות אלה דקד\"ש",[["6303","809","<b>כחו </b>[א: כח]<b> הרבה. . שהוא</b>: א: ליתא."],["6304","810","<b>[אינו]</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות: כו'). . נראה לעין, שבשורה שלפנ\"ז."],["6305","811","<b>בכאו\"א מישראל למסור נפשו על קדוה\"ש</b>: ראה תניא פי\"ח."],["6306","812","<b>קשה עורף</b>: תשא לד, ט. ראה שמו\"ר פמ\"ב, ט. רלב\"ג בשם זקנו־ פענח רזא־ פי' הטור הארוך עה\"פ. מאמרי אדה\"ז תקס\"ה ח\"א ע' שפה. ע' שצג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370368\" data-slug=\"torah-or\" data-id=\"3901370368\">תו\"א תצוה פה, א</a>. מאמרי אדה\"א שמות ח\"ב ע' תצז. לעיל פ' וארא פב, ג."],["6307","813","<b>דמצד הקדושה</b>: אכא: דמצח דקדושה."],["6308","814","<b>זה</b>: שם: זר."]]],[2300550768,"לה' שהי' כתוב קד\"ש לה'<sup data-n=\"6309\">815</sup> בתחלת שטה התחתונה שהיא העלא' דקדש דחכ' דתו\"מ מלמטה למעלה כמו בקבלת התורה בהר סיני שאמ' נעשה כנ\"ל, ושם הוי' למעלה שהוא מקור כל בחי' הוי' דרצון [ו]חכ' דתו\"מ כנ\"ל והוא נק' רעוא דכ\"ר עילאין דוקא. והענין הוא דכמו שהסכם חזק הזה בכנ\"י מלמטה למעלה הוא שעושה רצון לרצון להבא בלי יחולף וישונה לעולם כנ\"ל, כך יהי' שורה בזה ג\"כ מבחי' בעל עצמות הרצון שהוא עצמות אור א\"ס ממש בבחי' תוקף ועוז גדול בעצמות שלו ממש באה\"ר לנש\"י, וכמו שבכנ\"י א[ין] ז[ה] רק בחי' תוקף הביטול בנפש עצמה עד מס\"נ, כך מלמעלה למטה רוח אייתי רוח לעורר אה\"ר עצמי' שיהי' בתוקף הע[צמו'] בניצוח והסכם חזק לחזק רצ\"פ שיהי' מאיר בתמידות בגילוי בחיצוני' עכ\"פ, והוא ענין גילוי <span data-k=\"pg\">1130</span> ּ הרצ[ון] הפ[שוט] שבעצמות ממש שנק' רעוא דכ\"ר שבא מחמת ריעות וחיבה יתירה כנ\"ל, וכמבואר באד\"ר דבמצחא דע\"י בי' אתגליא מבחי' רעוא דכ\"ר, פי' אתגליא אינו רק גילוי חיצוני', והוא בחיצוני' הכלי דמצח אהרן שאינו ג\"כ רק בחיצוני'<sup data-n=\"6310\">816</sup> הכלי לזה הגילוי אבל הוא תקיף וחזק מאד, לפי שביכולתו להמשיך מעצמות בעה\"ר הפ[שוט] שיומשך בחי' רעדכ\"ר שהוא מקור כל רצון טוב וחסד דוקא ואין בו נטיה לדין כלל כנ\"ל גם לגבור על כח הדין כמו ויהפוך ה'<sup data-n=\"6311\">817</sup> כו'. וע\"כ אין גילוי זה דרעדכ\"ר רק במצח שהוא הכלי לזה דוקא מטעם הנ\"ל שהוא העושה ההסכם לרצון להבא ע\"כ בזה ישכון דוקא מאד<sup data-n=\"6312\">818</sup> [ד]רעדכ\"ר שהוא ג\"כ מצד בחי' ההסכם חזק להיות לו רצון לרצון תמיד בלי שינוי כלל בכנ\"י מלמעלה למטה ולעמוד לנגד כל קטרוג כנ\"ל וד\"ל.\n<b>וזהו</b> והי' על מצח אהרן ונשא אהרן את עון הקדשים כו' הזכיר ב\"פ אהרן, א' מצח אהרן, והב' ונשא אהרן כו'. לפי שבמצח אהרן דוקא הוא הכלי להתגלות בחי' רעדכ\"ר הנ\"ל שזהו שם הוי' שכתוב בציץ למעלה שהוא כמו שם הוי' הא' שבי\"ג מדה\"ר (כמשי\"ת). ומ\"ש ונשא אהרן את עון הקדשים זהו כמו בחי' [שם] הוי' הב' דאל רחום וחנון כו' להיות נושא עון בפו\"מ כנ\"ל. והיינו ב' המדרגות שהי' בציץ, א' קדש לה' מלמטה שזהו כמו הוי' הב' דאל כו'. והב' שם הכתוב למעלה שהוא כמו שם הוי' הא' שבי\"ג מדה\"ר כנ\"ל שבו התגלות רעדכ\"ר עצמו שמשיג<sup data-n=\"6313\">819</sup> מקור ההמשכה די\"ג מדה\"ר בהוי' הב' דאל רחום כו', והוא מ\"ש ג\"כ כאן ונשא אהרן את עון כו' לכפר על עון הקדשים בפו\"מ, וכמ\"ש למעלה בענין מקור הסליחה דעון בפו\"מ שהוא למעלה גם ממקור הרצון שבתו\"מ גם בהבדלה הפ[נימי'] ע\"פ ח\"ס דהיינו טעם כמוס לרצה\"ע ולמעלה גם מחו\"ג שבעצם הרצון כו', וע\"כ יכול לכפר העון להיות הזדונות כזכיות ממש משום דגם חושך לא יחשיך כו' כחשיכה כאורה (אע\"פ שהבדיל בין אור לחשך ובין קדש לחול כו' כמו",[["6309","815","<b>לה'</b>: א: ל'. כא: למ\"ד."],["6310","816","<b>רק בחיצוני'</b>: כא: ליתא."],["6311","817","<b>ויהפוך ה'</b>: תצא כג, ו."],["6312","818","<b>מאד</b>: אכא: מאור."],["6313","819","<b>שמשיג</b>: שם: שממנו נמשך."]]],[2300550770,"במ\"ת בא' אנכי ולא יהי' לך זהו דוקא בהמשכ[ת] העונג העליון<sup data-n=\"6314\">820</sup> ברצון וחכמה כו'). והיינו בבחי' רעדכ\"ר שהוא מקור כל רצון טוב וחסד מעצם הטוב שאין בו נטי' לדין כלל כנ\"ל (והוא בבחי' עונג ושע[שועים] העצמי' שנעשו<sup data-n=\"6315\">821</sup> בעצמו' בלתי מורכב ברצון אף לא בבחי' מקור לרצון ההיול\"י כנ\"ל), ולכך גם הטמא יטהר וכמ\"ש מי יתן טהור מטמא<sup data-n=\"6316\">822</sup> לא אח\"ד כו' אח\"פ ממש. וכך יובן כאן גם במדרגה עליונה יותר והוא לכפר גם על עון הקדשים אשר יקדישו בנ\"י שיטמאו בטומאה ויפגמו קדושתם ועכ\"ז יכופר העון הזה דקדשים שלא יחולל קדושתם מן הטומאה כלל והוא שא' ונשא אהרן את עון הקדשים כו' כמו ונושא עון בחטא גמור (לפי שבבחי' רעדכ\"ר יטהר כל טומאה כמ\"ש לפני הוי' תטהרו והיינו לפני הוי' הא' די\"ג מדה\"ר, והוא שם הוי' שכתוב למעלה מקדש למ\"ד לכפר על עון הקדשים דכנ\"י שעולה מלמטה למעלה, וע\"כ הי' נכתב קד\"ש להוי' <span data-k=\"pg\">תקסה</span> ּ דוקא דהיינו שיתמלא כל חסרון ופגם בקדש דישראל ויהיו תמיד קדש לה' ממש).\n<b>אך</b> עדיין י\"ל בטעם הנחת הציץ על מצח אהרן דוקא, דהלא ידוע בשרש בחי' אהרן כה\"ג שהוא הרועה וזן ומפרנס לישראל בהמשכה דאה\"ר העצמיית העליונה לעורר האה\"ר בכנ\"י בתמידות דוקא בלי שינוי וחילוף כלל, והוא עיקר הגילוי במצח אהרן שבו עיקר הרצון באה\"ר כו' וא\"כ למה צריך להנחת הציץ דוקא על מצח אהרן בכתיבה דב' תיבות הללו דקדש לה' דוקא. אמנם הנה באמת לפי הפשט בכתובים האלו שהי' עיקר המכוון בהנחת הציץ נזר הקד\"ש רק לכפר על עון הקדשים שיקדישו בנ\"י, וגם להיות לרצון להם לפני תמיד לפני ה'. וב' הענינים האלה א' הוא, דהגם שע\"י אהרן כה\"ג נמשך תמיד אה\"ר העצמית בגילוי במצח כנ\"ל באור פני מלך חיים<sup data-n=\"6317\">823</sup> כו', עכ\"ז יכול להיות הפסק מחיצה מבדלת כאשר יהי' פגם בקדושה דישראל שלא יאיר בהם אור א\"ס שבפנימי' הכת\"ר, כי עי\"ז יחולל קדושת שם הוי' השורה בישראל ולא יהי' נק' קד\"ש להוי' כו'. אך ע\"י הציץ מרצה ומכפר על עון הקדשים ויהי' אור קדושתם שלימה להיות<sup data-n=\"6318\">824</sup> בתמידות כ\"ז<sup data-n=\"6319\">825</sup> שהציץ על מצח אהרן דוקא ששם בחי' התגלות דאה\"ר העצמות כנ\"ל. ולפ\"ז הרי יובן שעיקר ענין הציץ לרצות על עון הקדשים היינו שלא יופסק אור האה\"ר העצמי' שהוא בבחי' מקיף תמידי דאה' שברצון הע[צמי] שלמעלה מן הטעם לגמרי אפי' מטעם כמוס דחכ'<sup data-n=\"6320\">826</sup> דתו\"מ כמו בחי' הוי' הב' דאל רחום כו' כנ\"ל וד\"ל. והטעם הב' להיות לרצון תמיד להם לפני ה' כו', דהנה הגם שמצח אהרן הי' בחי' כלי לאור זה דציץ שיאיר בו מרעדכ\"ר לכפר על עון הקדשי' היינו רק במה שנמשך ובא מאורו למטה לכפר כו' (שזהו בחי' הוי' הב' דאל רחום כו') שהוא רק בחי' התגלות דאה\"ר דעצמות הרצון כו'. ואמנם למעלה מזה היינו בחי' ש[ם] הוי' שכתוב",[["6314","820","<b>העליון</b>: שם: העצמי."],["6315","821","<b>שנעשו</b>: שם: שנעלם."],["6316","822","<b>מי יתן טהור מטמא</b>: איוב יד, ד."],["6317","823","<b>באור פני מלך חיים</b>: משלי טז, טו."],["6318","824","<b>להיות</b>: א: קדש לה' להיות. כא: להיות קודש להוי'."],["6319","825","<b>כ\"ז</b>: כא: כל זמן."],["6320","826","<b>דחכ'</b>: כא: דח\"ס."]]],[2300550772,"למעלה בציץ שהוא כמו ש[ם] הוי' הא' די\"ג מדה\"ר כנ\"ל שזהו המשכ' עצם האור דרעוא דכל רעוין מעצמות אור א\"ס ממש<sup data-n=\"6321\">827</sup>, שנק' סדכ\"ס דלית מחת\"ב כלל אפילו מחשבה ורצון העצמי' שנק' מקור כל רצון כו' שזהו בחי' שעה\"מ בעצמו ממש שמשם מקור כל רעוין ע[צמיי'] והוא צריך להתמשך ג\"כ ע\"י ש[ם] הוי' מיוחד, וזהו כמו ויקרא הוי' [הוי']<sup data-n=\"6322\">828</sup> שקרא בתחלה לש' הוי' הא' מעצמו' ממש ומשם הוי' זה קרא והמשיך לשם הוי' הב' להיות אל רחום כו'. וכך הוא בענין הציץ ממש שהוא שם הוי' שכתוב למעלה שהוא המשכות דרעוא דכל רעוין שזהו למעלה [הרבה] מגילוי האור דבחי' רעוא דכל רעוין במקיף דאהבה רבה העצמי' לכפר על עון הקדשים הנ\"ל כי הרי זהו העונג העצמי' שכלול בעצמות ממש שאפס קצהו נמשך לכפר על עון הקדשים כו' לחזק להרצון העצמי' באה\"ר שלא יופסק מכ[ל] ד[בר] חוצץ כנ\"ל וד\"ל.\n<b>וענין</b> טעם הב' שא' והי' על מצחו תמיד לרצון כו' היינו בחי' האור דעצם רעוא <span data-k=\"pg\">1132</span> ּ דכל רעוין שבשם הוי' שכתוב למעלה שזהו בהוי' הא' [שב]י\"ג מדה\"ר כנ\"ל, ומבחי' שם הוי' זה נמשך לקד\"ש למ\"ד לכפר על עון הקדשים מן ההעלם לגילוי כמו בהמשכה דהוי' הא' להוי' הב' דאל רחום כו'. אך בכאן הי' זה ע\"י בחי' העלא' דקד\"ש למ\"ד מלמטה למעלה תחלה והיינו ע\"י העלא' קדוש' המצות דישראל שיהי' לרצון לפני ה' כו' שהוא ע\"י פתוחי חותם דאמת דתורה כנ\"ל. והענין הוא כמבואר למעלה שהי' בציץ ב' תנאים, א' שיעשנו משה. והב' שיונח על מצח אהרן דוקא, וזה בלא זה אינו כלום והיינו שע\"י משה דוקא יאיר האור דרעוא דכ\"ר בציץ זה (והוא בשם הוי' שכתוב למעלה), והב' שיהי' הציץ על מצח אהרן שהוא בחי' הכ\"ג<sup data-n=\"6323\">829</sup> שיקבל האור הזה מרעוא דכל רעוין, כי אין כ\"ק<sup data-n=\"6324\">830</sup> לקבל זה האור הרצון הפשוט כו' כ\"א במצח אהרן דוקא מטעם הנ\"ל שהמצח הוא בחי' כח ההסכם החזק להיות רצון לרצון תמיד כנ\"ל וד\"ל.\n<b>אך</b> הנה הטעם לזה שע\"י משה דוקא נעשה בציץ לפי<sup data-n=\"6325\">831</sup> המשכת רעוא דכל רעוין ע\"י עצמו ולא ע\"י אחר זולתו, לפי שהי' שרש נשמת משה מבחי' מוח הדעת העליון שעולה בפנימית הכתר ממש שנק' כתר שבכתר בעצמו' בעה\"ר הפנימי'<sup data-n=\"6326\">833</sup> כו' שזהו מקור להמשכת רעוא דכל רעוין<sup data-n=\"6327\">832</sup> שהוא מקור כל רצונות הפשוטים כנ\"ל. והיינו לפי שבחי' הדעת דמשה זהו בחי' עומק ההתקשרות בפנימי' הרצון ופנימי' התענוג בהרגשה עצמי' עד שניזוז ממקומו לגמרי כו' בבחי' מ\"ה בתכלית כו' שממילא עולה לעצמו' בעל הרצון שמשם נמשך מקור התורה ומצות בפנימי' דחכ' ופנימי' הרצון (שהוא בחי'",[["6321","827","<b>ממש</b>: א: (מקור כל רעוין ועצמי' ממש)."],["6322","828","<b>ויקרא הוי' [הוי']</b>: ראה גם לעיל פ' בשלח קמט, ד. וש\"נ."],["6323","829","<b>הכ\"ג</b>: אכא: הכלי קיבול."],["6324","830","<b>כ\"ק</b>: שם: כלי קבול."],["6325","831","<b>לפי</b>: שם: בחי'."],["6326","833","<b>בעה\"ר הפנימי'</b>: א: בעל הרצה\"פ. יגכג: בעה\"ר הפשוט. כא: חסר כנ\"ל."],["6327","832","<b>ע\"י </b>[א: ליתא]<b> עצמו. . דכל רעוין</b>: כא: ליתא וכנראה נשמט מפני תיבות הדומות: דכל רעוין. . דכל רעוין."]]],[2300550774,"דעת עליון דעת המטה לרצון העליון דמצות להבדיל בין טו\"ר במ\"ע ול\"ת בכלל [ב]אנכי [ולא] כו' כנ\"ל). אך להיות מבואר למעלה שבחי' מוח הדעת אע\"פ שהוא בהתקשרות דפנימי' הרצון יכול להחליף ולעבור מיד ואין לו קיום ע\"כ גם על<sup data-n=\"6328\">834</sup> בחי' פנימי' הדעת דמשה שהי' נמשך [ה]אור דרעוא דכל רעוין הי' נפסק ועובר ולא הי' מאיר תמיד לרצון כו', אבל על מצח אהרן ששם הוא בחי' ההסכם החזק ברצון לרצון בתמידות כנ\"ל, שם הי' הציץ מונח להיות לרצון בתמידות מרעוא דכ\"ר זה בלי הפסק לעולם כידוע שהציץ הי' מרצה בתמידות כו'<sup data-n=\"6329\">835</sup> שהי' על מצחו כמ\"ד עודהו על מצחו מרצה<sup data-n=\"6330\">836</sup> אף שלא בשעת עבודה כו'. ונמצא דבאמצעות שניהם דוקא דהיינו ע\"י מעשה הציץ ע\"י משה שנק' שושבינא דמלכא להאיר ולהמשיך המשכה דרעוא דכל רעוין וע\"י אהרן שנק' שוש' דמטרוניתא כו' שה[ו]נח הציץ במצחו דוקא נתקיים הארה זו בתמיד[ו]ת כנ\"ל להיותו כלי לאור זה וד\"ל (והוא לפי שכלי המצח הוא מעצם הגלגלתא שהוא למעלה הרבה אף מאו\"כ הדעת שעולה ברצה\"ע דפנימי' הכתר ע\"כ חולף ועובר, וההסכם אינו עובר לעולם ועכ\"ז ע\"י בחי' הפנימי' הדעת דמשה נמשך בחי' האור דרעדכ\"ר מטעם הנ\"ל וד\"ל).\n<b>וזהו</b> והי' על מצחו תמיד לרצון להם לפני ה' ממש, דהנה מבואר למעלה <span data-k=\"pg\">תקסו</span> ּ דעיקר המנגד לקליפת עמלק לשבור בחי' הגסות והחוצפא והעקשות ונצחון דעמלק (בעורף שלנגד המצח כנ\"ל) הוא ע\"י בחי' הציץ שבמצח אהרן, שהוא בחי' נצחון ותוקף ההסכם החזק לבטל הרצון תמיד מפני רצון ה' זהו דוקא בחי' הכלי להתקבל ולהתקיים בתוכו מבחי' רעדכ\"ר עצמו הנמשך ע\"י משה כנ\"ל (והוא מה שנשאר רושם הזכרון באדם גם בהיותו טרוד בכל היום שיהי' לו רצון לה' עכ\"פ כו' אף לאחר היסח הדעת שיכול להיות שכחה לגמרי, ומפני זה ה\"ז בחי' כלי לאור הרצון הפ' שהוא מקור כל הרצונות הפשוטי' שיאיר גם בתמידות דוקא שז\"ש והי' על מצחו תמיד לרצון להם, פי' תמיד בלי שינוי והפסק כלל שאינו נפסק אורו לעולם כי רושם שלו [נשאר] שלא נשכח (כחותם בטבעתו לאות וזכרון ע\"ד רצון המוחלט מכבר שנגמר בדעתו ורצונו שלא ישונה לעולם כנ\"ל) להיות מקור כל רצון הנולד ע\"כ מאיר אורו בלי הפסק. וזהו תמיד לרצות<sup data-n=\"6331\">837</sup> להם [לרצות להם] על עון הקדשים, וכמו הוי' אל רחום כו' שנושא עון תמיד, אך נמשך זה מרעדכ\"ר שהוא מקור כל הויות שברצון הנגלה הבא לכפר. וזהו לרצון להם לפני הוי' למעלה לפני שם הוי' העליון שהוא כמו הוי' הא' שבי\"ג מדה\"ר שהוא מקור להוי' הב' להיות נושא עון כו' וכמו לפני הוי' תטהר\"ו כנ\"ל, ולכך חזר וכפל והי' על מצחו תמיד לרצון דקאי ברעדכ\"ר עצמו וד\"ל.",[["6328","834","<b>על</b>: אכא: ע\"י."],["6329","835","<b>כו'</b>: אכא: כל זמן."],["6330","836","<b>עודהו על מצחו מרצה</b>: יומא ז, ב."],["6331","837","<b>לרצות</b>: אכא: לרצון."]]],[2300550776,"ומעתה יובן המשך כל הפסוקי' יחד ועשית ציץ זהב כו' ע\"י משה שהוא בחי' מ\"ה דחכ' עילאה<sup data-n=\"6332\">838</sup> דתורה הקדומה בבחי' פנימי' הדעת שבכתר כו', ושמת אותו על פתיל תכלת והי' על המצנפת כו', שיש כאן ג' מדרגות זו למעלה מזו מצנפת, ותפילין בין ציץ למצנפת, וציץ שהן ג' מדרגות, דכתר שבכתר עצמו זהו המצנפת, וחב\"ד שבכתר שהן ג' חללי הגלגלתא הנ\"ל זהו התפילין שהן במקום שמוחו של תינוק רופס<sup data-n=\"6333\">839</sup> למעלה בגובה המצח ובסוף הגלגלת, והציץ הוא במצח זהו בחי' חג\"ת שבכתר שבכתר עד נה\"י שהוא המאיר באותיות דקדש להוי' דבי' אתגלי' מרעדכ\"ר הנ\"ל, שהוא בחי' יסוד<sup data-n=\"6334\">840</sup> דע\"י שנמשך ע\"י פנימי' יסוד אבא<sup data-n=\"6335\">841</sup>, והפתיל תכלת הוא המחבר ציץ למצנפת והוא פתיל האמצעי דוקא שהוא לנגד מוח הדעת שהוא באמצע כנ\"ל. וביאור כ\"ז מובן מכל הנ\"ל בענין ג' קשרים בבחי' גליא וסתים, דחב\"ד שבעצם הרצון שלמעלה מהתחלקות חו\"ג דעצם הרצון שלמעלה מן הטעם לרצון כו' זהו התפילין, שהן מקיף דמוחין בהעלם דכתר שבכתר כמ\"ש ואהי' אצלו אמון שעשועי'<sup data-n=\"6336\">842</sup> עצמיי'<sup data-n=\"6337\">843</sup> הוא סת[י]ם דאורייתא שהוקשה כל התורה לתפילין<sup data-n=\"6338\">844</sup> כו', והציץ הוא במצח אהרן כהנא רבא בחי' חג\"ת, אה\"ר בעצם [ה]רצון לישראל למעלה מן הטעם ומאיר בו מרעדכ\"ר בתמידות בעצם אור הכתר שבכתר<sup data-n=\"6339\">845</sup> שבראש במצנפת שזהו בחי' קדש להוי', דישראל מלמטה מתקשראן באוריי' בחב\"ד דכתר שבכתר שהוא ד\"ע דמשה בחי' מ\"ה. וזהו פתוחי חותם דתורה שנעשה לזכרון, והוי' הא' שבציץ הוא רעדכ\"ר עצמו שהוא מסדכ\"ס שהוא שעה\"מ בעצמו כו' שמאיר ע\"י התו' שנק' חותם העליון כנ\"ל והוא כמו ויקרא [הוי'] הוי' ביגמה\"ר כנ\"ל, והן סדר הפסוקי' הללו ועשית ציץ והי' על המצנפת דוקא והי' על מצח אהרן בגילוי דרעדכ\"ר באה\"ר לרצון להם לפני [הוי'] ממש כנ\"ל וד\"ל.",[["6332","838","<b>דחכ' עילאה</b>: א: דד\"ע."],["6333","839","<b>התפילין. . תינוק רופס</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ז, סי\"ד."],["6334","840","<b>יסוד</b>: כא: פנימיו' דיסוד."],["6335","841","<b>אבא</b>: א: אריך."],["6336","842","<b>ואהי' אצלו אמון שעשועי'</b>: משלי ח, ל [בדילוג]."],["6337","843","<b>עצמיי'</b>: כא: שעשועי' העצמיי'."],["6338","844","<b>שהוקשה כל התורה לתפילין</b>: קדושין לב, א."],["6339","845","<b>שבכתר</b>: אכא: ליתא."]]],[2300550063,"<b>בעזה\"ש תורת אדמו\"ר משבת פ' שקלים</b>\n<span data-k=\"pg\">1134</span> ּ<b>כי</b> תשא<sup data-n=\"6340\">1</sup> את ראש בנ\"י לפקודיהם כו'<sup data-n=\"6341\">2</sup>, כתיב בטח בה' ועשה טוב<sup data-n=\"6342\">3</sup> כו'<sup data-n=\"6343\">4</sup> ורעה אמונה, פי' רעה כמו הרועה המנהיג צאנו בשדות הוא זנם ומפרנסם תמיד כו', כמו\"כ בחי'<sup data-n=\"6344\">5</sup> משה רע\"מ<sup data-n=\"6345\">6</sup> הוא [ה]זן ומפרנס בכל דור<sup data-n=\"6346\">7</sup> לכללות נש\"י הנק' אמונה<sup data-n=\"6347\">*8</sup>. כי הנה ישראל מאמינים בני מאמינים<sup data-n=\"6348\">8</sup> פי' שנקבע בנפשם האלקי' מצד שרש חוצבם באלקים חיים ישראל עלו במח'<sup data-n=\"6349\">10</sup> כו'<sup data-n=\"6350\">9</sup>, ענין התחדשות הבריאה מאין ליש כו', [ו]כאלו רואים בעין השכל ממש האין השופ\"ע ומהווה שמים וארץ וכל הברואים שנראים",[["6340","1","<b>כי תשא</b>: דרוש זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז משבת פ' שקלים תקס\"ג. ונדפס במאמרי אדה\"ז תקס\"ג ח\"א ע' קעו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370497\" data-slug=\"torah-or\" data-id=\"3901370497\">תו\"א תשא קיא, ג</a> ד\"ה וביאור הדבר [ומהתחלת המאמר שם קיא, א עד כאן הוא הנחת מהרי\"ל. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520020\" data-slug=\"or-hatorah-hb\" data-id=\"8316520020\">אוה\"ת תשא ס\"ע א'תתפג</a>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940213\" data-slug=\"or-hatorah-hb\" data-id=\"8159940213\">ע\"כ</a> הועתק מכ\"י דודי הרי\"ל זצ\"ל ויותר לא נמצא מכת\"י]. דרוש זה בתוס' אריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א שמות ח\"ב ע' תריט ואילך. וראה דרך מצותיך ע' סה ואילך. אוה\"ת תשא ע' א'תתעט (עד פ\"ג על הנחת מהרי\"ל כנ\"ל ומשם ואילך על הנחת כ\"ק אדה\"א]. וראה שם ע' א'תתצ. ע' א'תתקא. ע' א'תתלח ובכרך ז ע' ב'תשפה. ובכרך ח ע' ג'צו. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["6341","2","<b>כי תשא את ראש בנ\"י לפקודיהם כו'</b>: תשא ל, יב. ראה גם מאמרי אדה\"א שמות כאן בהערה."],["6342","3","<b>בטח בה' ועשה טוב</b>: תהלים לז, ג."],["6343","4","<b>כו'</b>: בגחיז: שכן ארץ."],["6344","5","<b>בחי'</b>: בגח: ליתא. יז: נק'."],["6345","6","<b>נק' משה רע\"מ</b>: ראה זהר וירא קו, א. לעיל פ' וארא עז, ב. וש\"נ."],["6346","7","<b>בכל דור</b>: גח: תמיד. ואולי נשתרבב לכאן משורה שלפנ\"ז (ומפרנסם תמיד)."],["6347","*8","<b>נש\"י הנק' אמונה</b>: זהר ויקרא טז, ב. לעיל פ' משפטים רצו, ב ובהנסמן שם."],["6348","8","<b>מאמינים בני מאמינים</b>: ראה שבת צז, א. לעיל קי, ג הערה 578."],["6349","10","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב הערה 248."],["6350","9","<b>מצד. . כו'</b>: יז: ליתא."]]],[2300550095,"ליש ודבר נפרד כו' איכות<sup data-n=\"6351\">12</sup> ביטול מציאות הנפרד<sup data-n=\"6352\">11</sup> לגבי מקורו האלקי<sup data-n=\"6353\">13</sup> כמ\"ש כי עמך מקו\"ח כו'<sup data-n=\"6354\">14</sup> הם משיגים בתכלית<sup data-n=\"6355\">15</sup> מצד חכמה שבנפשם האלקי' [כו']. וזה<sup data-n=\"6356\">16</sup> שנק' אמונה הוא על<sup data-n=\"6357\">18</sup> ההטבעה שהוטבע זה בנפשם מצד שרשם האבות הן [הן] המרכבה<sup data-n=\"6358\">19</sup> כו'<sup data-n=\"6359\">20</sup>, כמו האומן את היונק<sup data-n=\"6360\">17</sup> שמרגילו מעט מעט מקטנות[ו] עד שכמו<sup data-n=\"6361\">21</sup> טבע בנפשו ולכל אשר יחפוץ האומן<sup data-n=\"6362\">22</sup> ללמדו כו'<sup data-n=\"6363\">23</sup>, ואלו הי' מלמדו בפעם א[חת] לא הי' כמו טבעיות אצלו, אך מפני הרגילות וגם ההגדלה מדי יום ביומו<sup data-n=\"6364\">24</sup> מעט מעט הוטבע בו הדבר שלמדו כו'. וכמו\"כ<sup data-n=\"6365\">25</sup> עד\"מ<sup data-n=\"6366\">26</sup> אחדות ה' באבות הנק' אמונים<sup data-n=\"6367\">27</sup> הם אשר המשיכו בכללות נש\"י<sup data-n=\"6368\">28</sup>",[["6351","12","<b>איכות</b>: גטו: ואיכות. ח: ועיקר."],["6352","11","<b>שנראים. . הנפרד</b>: יז: ואיך שהם בטלים במציאות."],["6353","13","<b>מקורו האלקי</b>: יז: מקורם הוא חיות אלקות."],["6354","14","<b>כי עמך מקו\"ח כו' </b>[יז: וגו']: תהלים לו, י."],["6355","15","<b>בתכלית</b>: שם: כ\"ז בתכלית."],["6356","16","<b>וזה</b>: גחיז: ומה."],["6357","18","<b>על</b>: שם: ע\"ש."],["6358","19","<b>האבות הן [הן] המרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["6359","20","<b>כו'</b>: יז: והם נק' אומנים לכנס\"י. ראה גם לקמן הערה 27."],["6360","17","<b>אמונה. . האומן את היונק</b>: ראה גם לעיל פ' בא קטז, ג. וש\"נ."],["6361","21","<b>שכמו</b>: שם: שנעשה כמו."],["6362","22","<b>האומן</b>: שם: ליתא."],["6363","23","<b>כו'. . כו'</b>: שם: כ\"ז ליתא."],["6364","24","<b>ביומו</b>: גחטו: ויום."],["6365","25","<b>וכמו\"כ</b>: שם וביז: כמ\"כ."],["6366","26","<b>עד\"מ</b>: ג: כתבו ומחקו. ח: ע\"ד."],["6367","27","<b>באבות הנק' אמונים </b>[ג: אמונה]: אטויז: אומנים — ראה גם לעיל פ' בא קיח, ב. וש\"נ."],["6368","28","<b>בכללות נש\"י</b>: גח: בכנ\"י. ראה גם לקמן הערה 31."]]],[2300550127,"המסתעפי' מהם מעט מעט כאומן את היונק כו'<sup data-n=\"6369\">29</sup> עד<sup data-n=\"6370\">30</sup> שהוטבע אחדות ה' בכנס\"י<sup data-n=\"6371\">31</sup> בבחי' טבעי' [ו]כאלו רואה בעין השכל ממש כו' לכך המקבלים שפע זו נק' אמונה וד\"ל<sup data-n=\"6372\">32</sup>.\n<b>וזהו</b> ורע\"ה אמונ\"ה פי'<sup data-n=\"6373\">33</sup> מעלת משה רע\"מ<sup data-n=\"6374\">34</sup> יתירה על האבות בזה דהיינו שהוא הזן ומפרנס את [ה]אמונה זו. וביאור הדבר הוא להיות כי האמונה ה[י]א בבחי' ממכ\"ע וסוכ\"ע לבד, דהיינו איך שהוא ית' הוה ומהווה<sup data-n=\"6375\">35</sup> מאין ליש במדת מלכותו<sup data-n=\"6376\">36</sup> כידוע בענין יתברך שמ\"ך בפי כל חי כו'<sup data-n=\"6377\">37</sup>, פי' מה שבפי כל הברואים<sup data-n=\"6378\">38</sup> השגות באלקות אינו אלא שמ\"ך מדת מלכותו כח הפועל בנפעל<sup data-n=\"6379\">39</sup> כידוע<sup data-n=\"6380\">40</sup>. ובחי' סוכ\"ע הוא למעלה מהשגתם לגמרי ואומרים קדוש הוי'<sup data-n=\"6381\">41</sup> כו' וגם זאת בכלל אמונה תחשב שמאמינים ומשיגים<sup data-n=\"6382\">42</sup> איך שהוא קדוש ומובדל. אך למעלה מסובב וממלא הוא למעלה מענין האמונה כו', כי מאחר שאין<sup data-n=\"6383\">43</sup> בעצמות א\"ס ב\"ה שום<sup data-n=\"6384\">44</sup> תפיסא למקבלים לומר אפי' שהוא קדוש ומובדל כו', מפני שהקדוש ומובדל כו' הוא<sup data-n=\"6385\">45</sup> לשלול ממה<sup data-n=\"6386\">46</sup> שהוא בחי' ממלא<sup data-n=\"6387\">47</sup> אבל בעצמותו ומהותו גם קדוש לא יתכן לומר אלא כמ\"ש אתה הוא הוי' לבד\"ך<sup data-n=\"6388\">48</sup> כו'<sup data-n=\"6389\">49</sup> וד\"ל. והנה מבחי' העצמות שהוא ענין לבד\"ך כו' נמשך משם שפע ומזון לרעו\"ת האמונה דהיינו שיהי' מושג בבחי' סובב וממלא כו'. וזהו כי תשא את ראש בנ\"י פי' ראש בנ\"י הם החכ'<sup data-n=\"6390\">50</sup> שבכנס\"י שהוטבע<sup data-n=\"6391\">51</sup> בנפשם מן האבות כנ\"ל<sup data-n=\"6392\">52</sup> והתנשאות והגבהת ראש ומוחין דכנס\"י הוא ע\"י משה דוקא כי תש\"א את ראש כו' מפני שבחי' מש\"ה [הוא] רעי' מהימנא לזון ולפרנס<sup data-n=\"6393\">53</sup> את האמונה<sup data-n=\"6394\">54</sup> כמ\"ש ורע\"ה אמונה וד\"ל.\n<b>והנה</b> על ג' דברים העולם עומד<sup data-n=\"6395\">55</sup> על התו' ועל העבודה ועל גמ\"ח, עבודה הן הקרבנות בזמן בהמ\"ק<sup data-n=\"6396\">56</sup> שהי' אש מלמעלה יורד ע\"ג המזבח בדמות <span data-k=\"pg\">תקסז</span> ּ אר\"י'<sup data-n=\"6397\">57</sup> כמבואר בזהר והיינו ענין כאר\"י' ישא\"ג שהוא פני אר\"י' [א]ל הימין<sup data-n=\"6398\">58</sup> כו'.",[["6369","29","<b>כו'</b>: יז: ליתא."],["6370","30","<b>כו' עד</b>: גח: ליתא."],["6371","31","<b>בכנס\"י</b>: שם: בכללות נש\"י. ראה גם לעיל הערה 28."],["6372","32","<b>וד\"ל</b>: יז: ליתא."],["6373","33","<b>פי'</b>: גח: ליתא."],["6374","34","<b>רע\"מ</b>: יז: ליתא."],["6375","35","<b>הוה ומהווה</b>: גחטויז: מהווה."],["6376","36","<b>מלכותו</b>: בדרמ\"צ כאן ישנו הג\"ה."],["6377","37","<b>בענין יתברך שמ\"ך בפי כל חי כו' </b>[גחיז: ליתא]: נוסח ברכת המזון. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370331\" data-slug=\"torah-or\" data-id=\"3901370331\">תו\"א יתרו עד, ד</a>."],["6378","38","<b>הברואים</b>: גח: הנבראים."],["6379","39","<b>כח הפועל בנפעל</b>: נסמן לעיל פ' תצוה שכה, ב."],["6380","40","<b>כידוע</b>: יז: ליתא."],["6381","41","<b>קדוש הוי'</b>: ישעי' ו, ג."],["6382","42","<b>שמאמינים ומשיגים</b>: יז: שמשיגים ומאמינים."],["6383","43","<b>מאחר שאין</b>: שם: ליתא."],["6384","44","<b>שום</b>: שם: אין שום."],["6385","45","<b>כו' הוא</b>: גחטויז: היינו."],["6386","46","<b>ממה</b>: גחיז: מה — בדרמ\"צ כאן ישנו הוספה."],["6387","47","<b>בחי' ממלא</b>: בדרמ\"צ ממלא. באה כאן הוספה."],["6388","48","<b>אתה הוא </b>[טויז: ליתא]<b> הוי' לבד\"ך</b>: נחמי' ט, ו."],["6389","49","<b>כו'</b>: בדרמ\"צ כאן ליתא. וישנו הוספה."],["6390","50","<b>הם החכ'</b>: אב: הוא החכמה. ח: הוא החו\"ב. יז: החכמה."],["6391","51","<b>שהוטבע</b>: יז: והאמונה שהוטבע."],["6392","52","<b>כנ\"ל</b>: יז: הנק' אומנים כנ\"ל."],["6393","53","<b>דוקא. . ולפרנס</b>: שם: לזון ולפרנס."],["6394","54","<b>את האמונה</b>: אגח: ליתא. יז: באה כאן הוספה גדולה. ע\"כ הושוה ליז."],["6395","55","<b>על ג' דברים העולם עומד</b>: אבות פ\"א, מ\"ב. ראה אוה\"ת כאן ע' א'תתפג."],["6396","56","<b>בזמן בהמ\"ק. . בדמות אר\"י'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111354\" data-slug=\"likkutei-sichot\" data-id=\"1300111354\">לקו\"ש תשא (כרך יא) ע' 347</a>. תרומה (כרך טז) ע' 616."],["6397","57","<b>אש מלמעלה </b>[גחטו: שלמעלה]<b>. . בדמות אר\"י'</b>: נסמן לעיל פ' יתרו ער, א הערה 46."],["6398","58","<b>כאר\"י' ישא\"ג שהוא פני אר\"י' [א]ל הימין</b>: הושע יא, י. יחזקאל א, י. ראה סידור שער האלול רלא, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, רע\"ג</a>. מאמרי אדה\"א דרושי חתונה ח\"א ע' רעח ובהנסמן שם."]]],[2300550159,"<b>וביאור</b> הדברים<sup data-n=\"6399\">59</sup> היינו כמ\"ש מצרף לכסף<sup data-n=\"6400\">60</sup> כו' כן איש לפי כו', פי' כי הנה אה\"ר שהיא באה ונמשכת מלמטה למעלה<sup data-n=\"6401\">61</sup> לעורר את האהבה בכללות נש\"י הוא בבחי' מקיף כמ\"ש וימינו תחבקני<sup data-n=\"6402\">62</sup> כו' והיינו כאר\"י' ישא\"ג לעורר כנס\"י, וזה אינו אלא [לאחר] ההתבוננו' בק\"ש בפסוק שמע ישראל ובשכמל\"ו יחודא עילאה ותתאה<sup data-n=\"6403\">64</sup>, ואז בש\"ע שהתפלה במקום קרבן<sup data-n=\"6404\">65</sup> יורד האש שלמעלה<sup data-n=\"6405\">63</sup> אה\"ר מבחי' ארי' הנ\"ל ואוכל הקרבן שהוא הנה\"ב<sup data-n=\"6406\">66</sup> כו', דהיינו שנתהפך גם רצון חומר הגוף לה' לבדו ואין בלבו אלא א[חד] ואין זר אתו כו'. וזהו מצרף לכסף כו'<sup data-n=\"6407\">67</sup> פי' עד\"מ הכסף המעורב בסיגים בתכלית התערובות כשנותנים אותו בכור המצרף בשלהבת מתברר<sup data-n=\"6408\">68</sup> ומתפרדי' כל החלקים שבו עד שחלק הטוב יוצא נקי בפ\"ע, וכל חלקי הסיגי' מתפרדים ויוצאים מובדלים בפ\"ע, וכל שיתנו אותו בשלהבת הרבה פעמים יותר [יותר]<sup data-n=\"6409\">69</sup> יובדל חלקי הסיגים הדקים כידוע. וא\"כ נמצא שמה שהיו הסיגים בהעלם מתחלה בערבוביא, ע\"י השלהבת נתגלו ויוצאים<sup data-n=\"6410\">70</sup> לידי גילוי, וכל שנתנה<sup data-n=\"6411\">71</sup> הכסף בשלהבת יותר, יותר יצא ההעלם עד שגם הדק שבדקין י[ו]צא להפרד בפ\"ע ולא להיות מעורב בטוב כו' וד\"ל. וכמו\"כ עד\"מ בנפש הבהמיות עם הניצוץ האלקי<sup data-n=\"6412\">72</sup> שהן מעורבים בתכלית מטו\"ר<sup data-n=\"6413\">73</sup> וע\"י שלהבת העולה מאלי' בתפלת שמו\"ע מחמת שאגת ארי' דלעילא הנ\"ל מתבררים כל החלקים המעורבים ויוצא מן ההעלם כל הסיגים גם הדק שבדקין כו' וד\"ל.\n<b>וזהו</b> הטעם שאנו אומרים סלח לנו בשמו\"ע<sup data-n=\"6414\">74</sup> דוקא<sup data-n=\"6415\">75</sup>, להיות כי כל מה שהתבונן ביותר העמקות בק\"ש וסדר כל<sup data-n=\"6416\">76</sup> השבחים שבפסוד\"ז בהתלהבות רשפי אש שלמטה צעק לבם<sup data-n=\"6417\">77</sup> כו', יותר נתעורר למעלה אש שלמעלה אהבה רבה כו' ואז גם שמים לא זכו בעיניו<sup data-n=\"6418\">79</sup> כו'<sup data-n=\"6419\">78</sup> מאחר דלגבי עצמות המאציל כלא חשיבי המשפיע עם המקבל סובב וממלא כו', וגם למטה נתגלה כל<sup data-n=\"6420\">80</sup> דק שבדקין שבתערובות טו\"ר ואז נעשה חוטא גדול גם",[["6399","59","<b>וביאור הדברים</b>: מכאן נדפס ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370497\" data-slug=\"torah-or\" data-id=\"3901370497\">תו\"א קיא, ג</a> [ושם: וביאור הדבר]. באוה\"ת כאן באה הערה: ר\"ל ענין אש שלמעלה שהי' יורד זהו יובן מענין מצרף לכסף, וע' עוד מענין אש שלמעלה שהי' יורד בלקו\"ת בד\"ה לבאר ענין יוה\"כ פ\"ג."],["6400","60","<b>כמ\"ש </b>[טוטז: מ\"ש]<b> מצרף לכסף</b>: משלי כז, כא. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' תפ."],["6401","61","<b>מלמטה למעלה</b>: גחטוטז: מלמעלה למטה."],["6402","62","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380804\" data-slug=\"likkutei-torah\" data-id=\"4001380804\">לקו\"ת ראה כב, א</a>."],["6403","64","<b>שמע ישראל ובשכמל\"ו יחודא עילאה ותתאה</b>: ואתחנן ו, ב. פסחים נו, א. זהר בראשית יח, ב."],["6404","65","<b>שהתפלה במקום קרבן</b>: ראה ברכות כו, א-ב. לעיל פ' יתרו רסח, ב. וש\"נ."],["6405","63","<b>בק\"ש. . בש\"ע. . יורד האש שלמעלה</b>: ראה אוה\"ת כאן ע' א'תתפו בהג\"ה."],["6406","66","<b>הקרבן שהוא הנה\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370250\" data-slug=\"torah-or\" data-id=\"3901370250\">תורה אור וארא נה, ד</a>."],["6407","67","<b>כו'</b>: גח: ליתא."],["6408","68","<b>מתברר</b>: גח: מתבררים. טז: יתברר."],["6409","69","<b>[יותר]</b>: טז: ליתא."],["6410","70","<b>ויוצאים</b>: שם: ויראו ויצאו."],["6411","71","<b>שנתנה</b>: גחטוטז: שנשתהא."],["6412","72","<b>האלקי</b>: טוטז: אלקי."],["6413","73","<b>בתכלית מטו\"ר</b>: טז: מטו\"ר בתכלית."],["6414","74","<b>שאנו אומרים סלח לנו בשמו\"ע</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' קפב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670423\" data-slug=\"torat-chaim\" data-id=\"2300670423\">תו\"ח וירא קד, ב</a> ובהערה 20."],["6415","75","<b>סלח לנו בשמו\"ע דוקא </b>[גח: ליתא]: טז: בשמ\"ע דוקא סלח לנו."],["6416","76","<b>כל</b>: טוטז: ליתא."],["6417","77","<b>צעק לבם</b>: איכה ב, יח."],["6418","79","<b>שמים לא זכו בעיניו</b>: איוב טו, טו."],["6419","78","<b>ואז גם שמים לא זכו בעיניו כו'</b>: באוה\"ת כאן ע' א'תתפז מציין ע\"ז: הר\"ד [ כ\"ק אדמו\"ר האמצעי] נ\"ע כו'. ואולי הכוונה שזהו הוספת כ\"ק אדה\"א. וראה להלן הערה 81."],["6420","80","<b>כל</b>: טז: גם כל."]]],[2300550191,"בדקות הרע ואומר סלח לנו כי חטאנו כו', מפני<sup data-n=\"6421\">81</sup> שחוט השערה נדמה להם כהר<sup data-n=\"6422\">82</sup> לגבי אמיתי' בעל האמת כו' כמשל מי שעומד לפני מלך שגם תנועה קלה בפריקות עול הי'<sup data-n=\"6423\">83</sup> כמרד יחשב וגם כל יגיעותי\"ו לא יזכ\"ו בעיני המלך [לפי] שלגבי התנשאות<sup data-n=\"6424\">84</sup> המלך אין לך דבר שיספיק כו' וד\"ל. וז\"ש גבי מומין [ד]דוקין שבעין לדידהו לא הוי מומא<sup data-n=\"6425\">85</sup> ולדידן הוי מומא<sup data-n=\"6426\">86</sup>, פי' דוקין שבעין הוא ההסתרה שבחכ'<sup data-n=\"6427\">87</sup> והשגה<sup data-n=\"6428\">*88</sup> האלקי' מצד חומר וחושך<sup data-n=\"6429\">88</sup>, והסתרה זו שלא נתפס במוח ולב סובב וממלא הוא תכלית הדקות של הרע משבירת רפ\"ח ניצוצי'<sup data-n=\"6430\">89</sup> שבשעת חטא אדה\"ר שנתגשמו כל הברואים וכמ\"ש<sup data-n=\"6431\">90</sup> בזהר דאחשיך אנפין<sup data-n=\"6432\">91</sup> כו'<sup data-n=\"6433\">92</sup>, ולכך לדידהו<sup data-n=\"6434\">93</sup> שנלקחים מבחי' אחוריים דאלקי' אחרים<sup data-n=\"6435\">94</sup> אין זה מום כי הפרידן מאחדותו<sup data-n=\"6436\">95</sup> בתחלה כו', אך לדידן ישראל עלו במח' הוי מום גמור כי ישראל מאמינים כנ\"ל. וזהו שבהם נאמר עינים להם ולא <span data-k=\"pg\">1136</span> ּ יראו<sup data-n=\"6437\">96</sup> מפני הדוקין שבעין החכמה כנ\"ל<sup data-n=\"6438\">97</sup>, וכמו בבלעם שהי' סומא בעין א'<sup data-n=\"6439\">98</sup> כו', אבל בישראל נא' וכל ישראל רואים<sup data-n=\"6440\">99</sup> כו' וד\"ל. וכל הנ\"ל שמתברר<sup data-n=\"6441\">100</sup> הדק שבדקין אינו אלא דוקא אחרי שירד לעמקות ההתבוננות וגם בהתלהבות<sup data-n=\"6442\">101</sup> התפלה כדוגמת הקרבן כנ\"ל, משא\"כ בתחילה הוא מעורב טו\"ר בתכלית דהיינו כידוע בענין כל דרכי איש זך בעיניו<sup data-n=\"6443\">102</sup> כו' שנדמה לו הר<sup data-n=\"6444\">*103</sup> כחוט השערה והוא כשר וישר בעיניו כו' ואינו מרגיש הרע כלל, אבל כשמתלהב ביותר [יותר] ירגיש אפי' הקל שבקלי'<sup data-n=\"6445\">**103</sup> כהר גבוה כנ\"ל וד\"ל.\n<b>וזהו</b> ונתנו איש כופר נפשו לה'<sup data-n=\"6446\">103</sup> מחצית השקל [בשקל הקודש] תרומה לה'<sup data-n=\"6447\">104</sup>, פי' כי הנה במשכן הי' ג' דברים כללים זהב וכסף ונחשת והוא נגד ג' דברים שהעולם עומד עליהם שהן תורה ועבודה וגמ\"ח, העבודה הן הקרבנות הוא בחי' הזה\"ב<sup data-n=\"6448\">105</sup> ורשפי אש התשוקה מלמטה למעלה כידוע, והכס\"ף הוא חסד<sup data-n=\"6449\">106</sup> עליון מלמעלה למטה אה\"ר הנ\"ל לעורר האהבה בכנס\"י נכסוף נכספתי<sup data-n=\"6450\">107</sup> כו' והנחושת הוא ממוצע כלול",[["6421","81","<b>מפני. . כו'</b>: באוה\"ת כאן ע' א'תתפז נרשם ע\"ז: הר\"ד נ\"ע. . ע\"כ. וראה לעיל הערה 78."],["6422","82","<b>להם כהר</b>: גטז: כהר. ח: להר."],["6423","83","<b>עול הי'</b>: גטו: עול האימה. ח: עול מאומה. טז: העול האימה."],["6424","84","<b>התנשאות</b>: טז: רוממות."],["6425","85","<b>לדידהו </b>[גח: לגבי דידהו]<b> לא הוי מומא</b>: ראה גיטין נו, א. מאמרי אדה\"א שמות ח\"ב כאן ע' תרלד ובהנסמן שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670086\" data-slug=\"likkutei-sichot\" data-id=\"1301670086\">לקו\"ש בראשית (כרך לה) ע' 24</a> ואילך."],["6426","86","<b>ולדידן הוי מומא</b>: טו: ליתא."],["6427","87","<b>שבחכ'</b>: ח: שבחו\"ב."],["6428","*88","<b>והשגה</b>: טז: להשגה."],["6429","88","<b>וחושך</b>: גחטוטז: מחש[י]ך הגוף."],["6430","89","<b>רפ\"ח ניצוצי'</b>: נסמן לעיל פ' יתרו ערב, ד."],["6431","90","<b>כל הברואים וכמ\"ש</b>: גו: כמ\"ש."],["6432","91","<b>דאחשיך אנפין</b>: ראה זהר ח\"ש קלא, א."],["6433","92","<b>כו'</b>: גח: [כל] בריין."],["6434","93","<b>לדידהו</b>: טז: ניתוסף: עכו\"ם."],["6435","94","<b>דאלקי' אחרים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310027\" data-slug=\"tanya\" data-id=\"3401310027\">תניא פכ\"ב</a> ובמ\"מ הגהות והע\"ק לשם. ע\"ח (שער ציור עולמות) שמ\"ג, פ\"א. לקו\"ת להאריז\"ל נח ו, יג. שע\"ת קיח, ב. ש\"א פו, ב. מאמרי אדה\"א בראשית ע' תסה. שמות כאן ס\"ע תרלד ואילך. דברים ח\"ב ע' תקנז. וש\"נ."],["6436","95","<b>הפרידן מאחדותו</b>: ראה זהר יתרו פז, א. מאמרי אדה\"א שמות ח\"ב כאן ע' תרלה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670578\" data-slug=\"torat-chaim\" data-id=\"2300670578\">תו\"ח נח עה, ג</a> ובהערה 23."],["6437","96","<b>עינים להם ולא יראו</b>: תהלים קטו, ה. קלה, טז."],["6438","97","<b>כנ\"ל</b>: טז: כו'."],["6439","98","<b>בבלעם שהי' סומא בעין </b>[ג: סתום עין]<b> א'</b>: סנהדרין קה, סע\"א."],["6440","99","<b>וכל ישראל רואים</b>: דהי\"ב ז, ג [ושם: בני ישראל — אבל כ\"ה ביל\"ש שמיני ט, כד (רמז תקכד). תהלים לג, א (רמז תשכ)]. ח ובאוה\"ת כאן ע' א'תתמה: העם — יתרו כ, טו. יז (ע' סו): בני ישראל."],["6441","100","<b>שמתברר</b>: טו: שמתפרר."],["6442","101","<b>בהתלהבות</b>: שם: כי בהתלהבות."],["6443","102","<b>כל דרכי איש זך בעיניו</b>: משלי טז, ב."],["6444","*103","<b>הר</b>: טוטז: ההר."],["6445","**103","<b>שבקלי'</b>: שם: שבקלות."],["6446","103","<b>ונתנו איש כופר נפשו לה'</b>: המשך הכתוב כי תשא (לב, יב)."],["6447","104","<b>מחצית השקל [בשקל הקודש] תרומה לה'</b>: תשא שם, יג [בדילוג]."],["6448","105","<b>העבודה הן </b>[גח: היא]<b> הקרבנות. . הזה\"ב</b>: ראה גם מאמרי אדה\"א שמות ח\"א ס\"ע רעג ואילך."],["6449","106","<b>והכס\"ף הוא חסד</b>: נסמן לעיל שעא, ד."],["6450","107","<b>נכסוף נכספתי</b>: פיוט ”ידיד נפש\". ויצא לא, ל: נכספתה — ראה מאמרי אדה\"א במדבר ח\"ב ע' תתסב בהערה."]]],[2300550223,"משניהם<sup data-n=\"6451\">108</sup> והוא<sup data-n=\"6452\">109</sup> [ה]תור\"ה<sup data-n=\"6453\">110</sup> וכללותן ג' קוין ימין ושמאל ואמצע כידוע וד\"ל. והנה ידוע ההפרש בין קדש לקדוש שקדוש בוי\"ו מורה ההמשכה<sup data-n=\"6454\">111</sup> מסובב לממלא לומר שהוא ית' קדוש ומובדל מזמן ומקום כו' והוא מתנשא<sup data-n=\"6455\">112</sup> ומרומם מהם כו' [כידוע], אבל קדש בלא וי\"ו הוא עצמיות הסובב<sup data-n=\"6456\">*113</sup> קודם שהי'<sup data-n=\"6457\">113</sup> סובב לממלא<sup data-n=\"6458\">114</sup> כו' שאז הוא ענין<sup data-n=\"6459\">115</sup> הקדושה וההבדלה בעצמותו ולא שהי'<sup data-n=\"6460\">116</sup> קדוש ומובדל מתחתון הימנו בלבד כו' וד\"ל. וזהו ענין שקל הקדש דנשקל במדה קדש העליון בג' קוין כו' וד\"ל, וענין מחצית השקל<sup data-n=\"6461\">117</sup> דוקא, להיות כי<sup data-n=\"6462\">118</sup> בחי'<sup data-n=\"6463\">119</sup> משה רע\"מ הוא לזון ולפרנס [את] האמונה בכנס\"י<sup data-n=\"6464\">120</sup> כנ\"ל בענין כי תשא את ראש בנ\"י כו' והיינו שהוא ממשיך מקדש [העליון] העצמו' [של המאציל ב\"ה להיות קדו\"ש בחי' סובב לממלא כו', והמשכת קודש העליון הוא בג' קוין ימין ושמאל ואמצע כנ\"ל ע\"י] תורה ועבודה וגמ\"ח דוקא, להיות כי<sup data-n=\"6465\">121</sup> ע\"י המצות אנו מתקדשין בקדש העליון כמאמרינו אשר קדשנו במצותיו<sup data-n=\"6466\">122</sup> כו' [והיינו בחי' קדו\"ש בוי\"ו כו', והוא ענין שקל הקודש שנשקל במדה קדש העליון בג' קוין כו' וד\"ל.\n<b>וענין</b> מחצית השקל<sup data-n=\"6467\">123</sup> דוקא כו'<sup data-n=\"6468\">124</sup> ] להיות כי קדש העליון הזה בא ונמשך בבחי'<sup data-n=\"6469\">125</sup> כף מאזנים לשוקלו לחצאין שוין דוקא ומחצית[ו] יתנו כו', ועד\"מ כששוקלין איזה דבר לחצאין שוין, כל שמחצית הא' יותר כבד במשא ויכבד ביותר בירידתו מטה מטה ע\"פ המעט שמכריעו כן לפ\"ע יתעלה מחצית השני שבכף שכנגדו וי[ו]גבה ויתרומם למעלה מעלה כידוע. וכמ\"כ עד\"מ קדש העליון נשקל בכף מאזני החכמה עליונה ימין ושמאל, פי' המחצית האחד יורד בדרך ירידה מלמעלה למטה בבחי' קוין הנ\"ל להוסיף אורות באצי' ע\"י מעשה<sup data-n=\"6470\">126</sup> רמ\"ח מ\"ע שכללותם הוא ענין יחוד קוב\"ה ושכינתי' דהיינו להיות בחי' סובב וממלא כו', [ו]מחצית הקדש העליון בכף השמאלי ירידתו בשביל העלי' והסתלקות שיתעלה ויתרומם למעלה כשיכריע[נו]",[["6451","108","<b>והנחושת. . כלול משניהם</b>: ראה זהר תרומה קלח, ב."],["6452","109","<b>והנחושת. . והוא [ה]תור\"ה</b>: ראה מאמרי אדה\"א שמות ח\"א ע' עדר. ח\"ב כאן ע' תרלז. אוה\"ת תשא כרך ז ע' ב'תשפז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061170\" data-slug=\"likkutei-sichot\" data-id=\"1300061170\">לקו\"ש תרומה (כרך ו) ע' 159</a> בשולי הגליון להערה 51."],["6453","110","<b>התור\"ה</b>: טז: ניתוסף: וגם נחשת ר\"ת נובלות חכמה שלמעלה תורה — ראה גם קהלת יעקב בערכו."],["6454","111","<b>שקדוש בוי\"ו מורה ההמשכה</b>: ראה ש\"א צב, ב ובהערה 51. מאמרי אדה\"א הנחות תקע\"ז ע' רסג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380219\" data-slug=\"likkutei-torah\" data-id=\"4001380219\">לקו\"ת אמור לג, ב</a> ואילך. יו\"כ סט, ב. לעיל פ' וארא נח, ב. וש\"נ."],["6455","112","<b>מתנשא</b>: גח: מתרומם ומתנשא."],["6456","*113","<b>עצמיות הסובב</b>: טוטז: עצמות אא\"ס."],["6457","113","<b>שהי'</b>: טוטז: שיהי'."],["6458","114","<b>לממלא</b>: טז: וממלא."],["6459","115","<b>ענין</b>: גח: ליתא."],["6460","116","<b>שהי'</b>: גחטוטז: שהוא."],["6461","117","<b>דנשקל. . השקל</b>: גחטוטז: ליתא. ונמצאים בסמוך על יד הערה 123."],["6462","118","<b>כי</b>: טו: ליתא."],["6463","119","<b>בחי'</b>: גחטוטז: ליתא."],["6464","120","<b>בכנס\"י</b>: גח: ליתא. טוטז: לכנ\"י."],["6465","121","<b>כי</b>: גח: ליתא."],["6466","122","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' לא וע' קפו. דרך מצותיך ע' קסח."],["6467","123","<b>שנשקל. . השקל</b>: ראה הערה 117."],["6468","124","<b>כו'</b>: טז: וכו'."],["6469","125","<b>בבחי'</b>: שם: בכלי."],["6470","126","<b>מעשה</b>: גח: ליתא."]]],[2300550255,"הכף הימיני<sup data-n=\"6471\">127</sup> כנ\"ל במשל. והיינו מחצית השקל שיתנו תרומה לה' פי' ארמותא<sup data-n=\"6472\">128</sup> להוי' כנז' בזהר, והוא עליית כנס\"י ישראל עלו במח' בתשוקה נפלאה מלמטה למעלה בתפלת שמו\"ע ע\"י אור חסד עליון דקדושה<sup data-n=\"6473\">129</sup> העליון שירד לעורר את האהבה בבחי' או\"ח כו' וד\"ל. וזהו כי תש\"א את רא\"ש בנ\"י, פי' כשתרצה לפרנסם באמונתם מחסד העליון מחצית השק\"ל של הקדש העליון שיורד לעורר את האהבה בבחי' או\"ח להגביה [ולנשא] <span data-k=\"pg\">תקסח</span> ּ את ראש ומוחין דכנס\"י כו', ונתנו איש כופר נפשו כו' מחצית השקל כו' ומאותה המחצית<sup data-n=\"6474\">130</sup> היו הקרבנות שהוא ענין העלאת מ\"ן מלמטה למעלה אשה ריח ניחוח כו' כידוע. והעשי\"ר לא ירבה והדל לא ימעיט כו' והטעם הוא כי כבר נשקל המחצית בשקל הקדש העליון מתחלה כו'<sup data-n=\"6475\">131</sup>, וא\"כ העשיר במצות והדל במצות שוין כי כך הי' המדה בתחלה מהמודד בבחי'<sup data-n=\"6476\">*132</sup> מאזני חכ' עילאה כנ\"ל וד\"ל.\n<b>לפקודיהם</b> פי' כמו יפקד מקום דוד<sup data-n=\"6477\">132</sup> כו' שהוא לשון חסרון<sup data-n=\"6478\">133</sup>, והענין הוא בהיות כי הרי מבואר למעלה בענין שמי\"ם לא זכ\"ו בעיניו כו' כשהעלי' הוא בתכלית לגבי העצמו' וכן למטה בכנס\"י אומרים סלח לנו כו' לפי שאז מתברר תכלית הבירור ויתפרדו כל פועלי און<sup data-n=\"6479\">134</sup> אפי' הדק שבדקים כנ\"ל, וזהו לפקודיה\"ם פי' שמפרש הטעם למה תשא ותגביה את ראש ומוחין דכנס\"י כו' הוא כדי שיפקד ויחסר הרע הנדבק בנשמותיהן בערבוביא בהעלם כי מעתה יתפרדו ויבולע המות<sup data-n=\"6480\">135</sup> כו'<sup data-n=\"6481\">136</sup> וד\"ל, וזהו ונתנו איש כופר נפשו לה' לשון כופר הוא כמו בעי לכפורי ידי' בההוא גברא<sup data-n=\"6482\">137</sup> כו' דהיינו הסרת הלכלוך והמיאוס כו', וכמו\"כ יכפר<sup data-n=\"6483\">139</sup> נפשו<sup data-n=\"6484\">138</sup> דהיינו שיוסר ויובדל כל חלקי הרע מנפשם ויתפרדו כל פועלי און כו' ע\"י ענין מחצית השקל שיתנו תרומ\"ה לה' שהרי הקרבן שבא ממנו נאכל ונשרף ע\"ג המזבח לגמרי באש שלמעלה ארי' עילאה<sup data-n=\"6485\">140</sup> דאכיל קורבנין כו', והוא ארמות\"א העלי' בתכלית שאז יהופך גם הרע לטוב כהמס דונג מפני אש<sup data-n=\"6486\">141</sup> כן יאבדו רשעים כו' [וד\"ל]. וזהו מחצית השקל השנית שבכף השמאלי להעלות מרפ\"ח ניצוצין תרומה לה' כו', אך ערך העלי' הוא לפי ערך הירידה מלמעלה למטה במחצית השקל הקדש העליון שבכף הימין",[["6471","127","<b>הימיני</b>: שם: היורד."],["6472","128","<b>תרומה. . ארמותא</b>: ראה זהר תרומה קמז, א."],["6473","129","<b>דקדושה</b>: גחטוטז: דק[ו]דש."],["6474","130","<b>המחצית</b>: גח: מחצית השקל."],["6475","131","<b>כו'</b>: טוטז: כנ\"ל."],["6476","*132","<b>בבחי'</b>: טז: בחי'."],["6477","132","<b>יפקד מקום דוד</b>: גחטז: ויפקד — שמו\"א כ, כה. כז. יטו ומאמרי אדה\"א שמות ח\"ב ע' תרמז נפקד — ראה לקמן שפג, ג. הנסמן במאמרי אדה\"א שם."],["6478","133","<b>לשון חסרון</b>: ראה מצודות שם."],["6479","134","<b>ויתפרדו כל פועלי און</b>: ע\"פ תהלים צב, י."],["6480","135","<b>ויבולע המות</b>: ע\"פ ישעי' כה, ח."],["6481","136","<b>כו'</b>: טז: כנ\"ל."],["6482","137","<b>בעי לכפורי ידי' בההוא גברא</b>: גיטין נו, א."],["6483","139","<b>יכפר נפשו</b>: גחטז: יכפר[ו] נפשם."],["6484","138","<b>דהיינו. . נפשו</b>: טו: ליתא."],["6485","140","<b>עילאה</b>: גחטז: ליתא."],["6486","141","<b>כהמס דונג מפני אש</b>: תהלים סח, ג."]]],[2300550285,"המכביד ויורד בג' קוין תורה ועבודה וגמ\"ח וכללותם רמ\"ח מ\"ע רמ\"ח המשכות מקדש העליון כענין אשר קדשנו במצותיו<sup data-n=\"6487\">142</sup> כו' וד\"ל, וכל שמתגברי' ישראל ביותר במעשה המצות אז נמדד המדה של קדש העליון בשפע רב יותר ואז ממילא עליי' כנס\"י הגבה מאד נעלה לפי ערך כנ\"ל וד\"ל. וז\"ש<sup data-n=\"6488\">143</sup> העשי\"ר לא ירבה כו' הגם שתלוי במעשה המצות כו', הרי ידוע דכללות נש\"י קומה שלימה<sup data-n=\"6489\">144</sup> הוא והראש תלוי ברגל, ולכך הדל והעשיר שוין במחצית השקל, אך במדידת כללות ההשקלה בשני החצאים בבחי' אור ישר ואור חוזר תלוי לפי ערך מעשה המצות בכנס\"י כידוע וד\"ל.",[["6487","142","<b>במצותיו</b>: גחטוטז: ליתא."],["6488","143","<b>וז\"ש</b>: טוטז: ומ\"ש."],["6489","144","<b>נש\"י קומה שלימה</b>: ראה גם לעיל פ' שמות מה, ד. וש\"נ."]]],[2300550064,"<b>ביאור על כי תשא הנ\"ל</b>\n<b>להבין</b> שרש[י] הדברים הנ\"ל<sup data-n=\"6490\">1</sup>, הנה שרש ענין ורע\"ה אמונה<sup data-n=\"6491\">2</sup> הוא בחי' משה יסוד אבא<sup data-n=\"6492\">3</sup> דממשיך חסדים לנוק' הנק' אמונה<sup data-n=\"6493\">4</sup> כמבואר בזהר בכמה מקומות, ופרטי הדברים הנה מתחלה יש להבין שרש ענין מחצית השקל כו', הנה ידוע דת\"ת דאימא כתר לזו\"נ<sup data-n=\"6494\">5</sup>, ומהחסד שבת\"ת זה<sup data-n=\"6495\">6</sup> מתחלק לשני חצאין חצי הא' לז\"א ונמשך בג' קוין שלו חג\"ת שהן תורה ועבודה וגמ\"ח<sup data-n=\"6496\">7</sup> והוא מחצית השקל הנשאר בז\"א, ומחצית החסדים נמשך לכתר דנוק' והוא<sup data-n=\"6497\">8</sup> כדי לעשות לה התעוררות העלאת מ\"נ כו'. וביאור הדברים אלו מובן ע\"פ הידוע בענין אתעדל\"ע שהוא ע\"י אתעדל\"ת<sup data-n=\"6498\">9</sup> מתחלה ומבואר שרש <span data-k=\"pg\">1138</span> ּ הענין בשער מ\"נ ומ\"ד<sup data-n=\"6499\">10</sup> כידוע. אך יש להבין בו<sup data-n=\"6500\">11</sup> מאחר שאין המ\"ד שהוא אתעדל\"ע אלא ע\"י העלאת מ\"ן מתחילה מהיכן יהי' כח להעלאת מ\"נ מתחלה, שהרי ידוע שאין שום<sup data-n=\"6501\">12</sup> כח במקבל כ\"א שישפיע לו המשפיע מלמעלה כו'.\n<b>אך</b> הענין הוא דב' מיני אתעדל\"ע<sup data-n=\"6502\">13</sup> הם, הא' לעשות הכנה במקבל<sup data-n=\"6503\">14</sup> שיוכל להתעורר ולהעלות מ\"נ אל המשפיע, והמשכת מ\"ד זה אינו אלא מבחי' המקיפים וימינ\"ו תחבקני<sup data-n=\"6504\">15</sup> לעורר האהבה שיהי' אל אישה תשוקתה בהעלאת מ\"נ כו' ולא",[["6490","1","<b>להבין שרש[י] הדברים הנ\"ל</b>: ביאור זה הוא הנחת כ\"ק אדה\"א מדרוש אביו כ\"ק אדה\"ז ביאור לפ' שקלים שנדפס במאמרי אדה\"ז תקס\"ג ח\"א ע' קעט. וראה בשינויים וכו' ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370500\" data-slug=\"torah-or\" data-id=\"3901370500\">תו\"א פ' תשא קיב, ב</a>. מאמרי אדה\"א שמות ח\"ב ע' תרמא ואילך. אוה\"ת תשא ע' א'תתצו. ע' א'תתקב. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["6491","2","<b>ורע\"ה אמונה</b>: תהלים לז, ג."],["6492","3","<b>משה יסוד אבא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו' ע' 244</a> ואילך."],["6493","4","<b>לנוק' הנק' אמונה</b>: ראה זהר בלק קפט, א. קצח, ב."],["6494","5","<b>דת\"ת דאימא כתר לזו\"נ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381212\" data-slug=\"likkutei-torah\" data-id=\"4001381212\">לקו\"ת שה\"ש כ, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381318\" data-slug=\"likkutei-torah\" data-id=\"4001381318\">מז, ג</a>."],["6495","6","<b>ומהחסד שבת\"ת זה</b>: ראה תו\"א ואוה\"ת כאן."],["6496","7","<b>חג\"ת שהן תורה ועבודה וגמ\"ח</b>: ראה גם לעיל שפב, א. לקמן במאמר זה."],["6497","8","<b>והוא</b>: דח: ליתא."],["6498","9","<b>אתעדל\"ע. . אתעדל\"ת</b>: נסמן לעיל פ' יתרו רנט, ב."],["6499","10","<b>בשער מ\"נ ומ\"ד</b>: בע\"ח."],["6500","11","<b>בו</b>: ד: כי. ח: ליתא."],["6501","12","<b>שום</b>: דט: ליתא."],["6502","13","<b>דב' מיני אתעדל\"ע</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. נ\"ך ע' תלו. וש\"נ."],["6503","14","<b>אתעדל\"ע. . לעשות הכנה במקבל</b>: נסמן לעיל פ' תרומה שטז, ג."],["6504","15","<b>וימינ\"ו תחבקני</b>: שה\"ש ב, ו. ח, ג."]]],[2300550096,"יהי' ממנו שום הולדת ולד כלל כו', אמנם התעוררות המשפיע שנית שאחרי העלאת מ\"נ של המקבל הוא בבחי' אורות פנימי' בכלים כו' והוא המוליד כו'<sup data-n=\"6505\">16</sup>. וביאור הדבר היינו עד\"מ [כמו] זווג הגשמי שהחיבוק והנישוק הוא לעשות התעוררות להיות אל אישה תשוקת\"ה כו' ואין מזה שום הולדה כו', לפי שהוא בבחי' העלם האהבה ולא בגילוי בגופו כו', אך הזרע של הטפה הוא בגילוי מן העלם האהבה כו' ולכך מוליד ולא יהי' כ\"א אחרי העלאת מ\"נ דאשה המזרעת תחלה כו'. כמו\"כ עד\"מ יש ב' מיני מ\"ד דאצי', הא' ענין אתעדל\"ע לעורר את האהבה במקבלי' ממל' דאצי' שיהי' למל' וחיילי' דילה נשמות ומלאכים כו' כח ועוז להיות תשוקת[ה] באהבה נפלאה להתפשט מכלי<sup data-n=\"6506\">17</sup> ההגבלה ולהיות עולין ונדבקי' במקורא דכולא בחי' ז\"א דאצי' כו', והתעוררות זו לעורר את האהבה ה[י]א הנמשכת בבחי' העלם גדול דהיינו בבחי' מקיף לבד ולא בגילוי וכמ\"ש וימינ\"ו תחבקני כו', וכמו שאנו רואים בחוש שמתעורר הניצוץ אלקי פתאום מבלתי שום הכנה מתחלה וזה מחסד עליון וימינ\"ו תחבקני כו'<sup data-n=\"6507\">18</sup> וכמ\"ש עד יערה עלינו רוח ממרום<sup data-n=\"6508\">19</sup> כו' ואין מזה שום הולדת נשמה או מלאך כו', כי אין הולדתם מאין ליש מבחי' יסוד שבמל' כו' כ\"א מאור הזרוע בכלים דאצי' כו', היינו בחי' גילוי אור [ב]התעוררות המשפיע דאצי'<sup data-n=\"6509\">20</sup> הנק' מ\"ד הראוי להוליד ולד שהוא דוקא אחרי תשוקת העלאת מ\"נ הבא מלמטלמ\"ע ממל' דאצי' וד\"ל.\n<b>וזהו</b> ענין מחצית השקל פי' שקל הקדש הוא המשכת החכ' דבחי' יסוד אבא הנק' קד\"ש<sup data-n=\"6510\">21</sup> ולא קדו\"ש בוי\"ו כידוע, ושק\"ל הוא המכריע בכף מאזנים כו' היינו כש[ה]חסדים דאבא ואימא נמשכו בבחי' מאזני' דהיינו בבחי' או\"י ואו\"ח פי' להיות החצי מן החסדי' נמשך לנוק' כדי שתוכל להעלות מ\"נ בבחי' או\"ח<sup data-n=\"6511\">22</sup> [ועשרים הגר\"ה שבשקל הוא ב' מיני י\"ס דאו\"י ואו\"ח כו']<sup data-n=\"6512\">23</sup> והחצי הוא בבחי' או\"י בג' קוין דז\"א בחג\"ת שבו כו'. וביאור הדברים היינו המחצית מחסד עליון דאבא יורד כדי לעורר את האהבה במל' בבחי' או\"ח והחצי מן החסדים נשאר בבחי' או\"י ולפ\"ע כובד מחצית השקל ב[בחי'] או\"י כן יהי' ערך הגבהת מחצית השק\"ל בבחי' או\"ח בכף מאזנים שכנגדו כשמכריעו ומגביהו בבחי' או\"ח כו'. וכדי להבין זה הנה<sup data-n=\"6513\">24</sup> תחלה יש להבין ענין מחצית השקל<sup data-n=\"6514\">25</sup> החסדים בבחי' או\"י, להיות כי הנה ידוע דרמ\"ח מ\"ע כללותם הם רק ה' חסדים<sup data-n=\"6515\">26</sup> ונחלקים לג'",[["6505","16","<b>כו'</b>: דח: ליתא."],["6506","17","<b>מכלי</b>: שם: מכלל."],["6507","18","<b>וכמו. . כו'</b>: אגדח: ליתא."],["6508","19","<b>עד יערה עלינו רוח ממרום</b>: ישעי' לב, טו."],["6509","20","<b>דאצי'</b>: דח: ליתא."],["6510","21","<b>החכ'. . הנק' קד\"ש</b>: ראה לעיל פ' תצוה שסב, ב. וש\"נ."],["6511","22","<b>פי'. . או\"ח</b>: אגדח: ליתא. וכנראה נשמט מפני תיבות הדומות: ואו\"ח. . או\"ח."],["6512","23","<b>[ועשרים. . כו']</b>: ניתוסף ע\"פ מאמרי אדה\"ז תקס\"ג כאן ע' קפ."],["6513","24","<b>הנה</b>: דח: ליתא."],["6514","25","<b>השקל</b>: דחטו: ליתא."],["6515","26","<b>דרמ\"ח מ\"ע כללותם. . ה' חסדים</b>: ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנה, ב. לעיל פ' בא צו, א. וש\"נ."]]],[2300550128,"חלקים כללים תורה ועבודה וגמ\"ח, גמ\"ח ח\"ס דלי\"ת<sup data-n=\"6516\">27</sup> להחיות רוח שפלים<sup data-n=\"6517\">28</sup> [הוא] מלמעלה למטה דהיינו להמשיך שפע למל' הנק' דלי\"ת<sup data-n=\"6518\">29</sup> כידוע, ועבודה הן הקרבנות שהן העלאת מ\"ן אשה ריח ניחוח<sup data-n=\"6519\">30</sup> כו' <span data-k=\"pg\">תקסט</span> ּ והוא בחי' [ה]גבורות והתלהבות התשוקה מלמטה למעלה כו', וב' בחי' אלו בז\"א עצמו הן<sup data-n=\"6520\">31</sup> שהן חו\"ג ימין ושמאל כו' והתור\"ה היא הממוצע כי כלולה מחו\"ג כמ\"ש מימינו אש דת למו<sup data-n=\"6521\">33</sup> כו' אש שחורה ע\"ג אש לבנה<sup data-n=\"6522\">34</sup> כו' והוא הת\"ת<sup data-n=\"6523\">32</sup> כידוע ו[ב]ג' קוין אלו חג\"ת נמשכי' החסדי' דכללות רמ\"ח מ\"ע מאבא שרש כל האצי', וזהו על ג' דברים האלו שהעולם<sup data-n=\"6524\">35</sup> שהוא ז\"א<sup data-n=\"6525\">36</sup> עומד כו' וד\"ל. וע\"כ ע\"י מעשה רמ\"ח מ\"ע [נמשך ו]ניתוסף אורות בכלים באצי' עצמו מאור הראשון דאבא כו', אך הוספה זאת שה[י]א בבחי' או\"ח<sup data-n=\"6526\">37</sup> מלמעלה מאבא כנ\"ל<sup data-n=\"6527\">38</sup> נשאר באצי' ולע\"ל כתיב ונגלה כבוד הוי'<sup data-n=\"6528\">39</sup> כו' כידוע. ומחצית השני[ת] מחסדים האלו נמשך לנוק' להיות עולה בבחי' או\"ח<sup data-n=\"6529\">40</sup> כנ\"ל וכל שהשפע של [ה]חסדים דאבא בהתגברות<sup data-n=\"6530\">41</sup> יותר באורות הנאצלים בבחי' או\"י כו', הרי גם המחצית השנית שכנגדו שעולה ב[בחי'] או\"ח הוא ג\"כ בהתגברות ההתנשאו' למעלה מעלה כנ\"ל, כמשל הכובד הגדול ביותר שבכף זה לפי ערך כובדו שמכביד[ו] למטה מטה כן יהי' ערך העלי' והתנשאות והגבהת הכף שכנגדו ממש בשוה כי המאזנים הם<sup data-n=\"6531\">42</sup> שקולים כו', וכמו\"כ כל שניתוסף האור באצי' דרך ירידה ביותר ע\"י תורה ועבודה וגמ\"ח בבחי' או\"י כנ\"ל כמו\"כ<sup data-n=\"6532\">43</sup> לפי ערך זה ביותר יהי' עליי' המל' ע\"י אתעדל\"ת<sup data-n=\"6533\">44</sup> [מ]מחצית השנית שבבחי' או\"ח בעילוי היותר גדול כו' וד\"ל.\n<b>וזהו</b> אין טפה יורדת<sup data-n=\"6534\">45</sup> מלמעלה שאין טפיים עולים כנגדה, פי' כי הנה ענין כדכד שמשותיך<sup data-n=\"6535\">46</sup> הם ב' שמות דהוי'<sup data-n=\"6536\">47</sup> שנמשכים לזו\"נ יחד מאו\"א כו', אך שהן נחלקי' לב' שמות מובדלין והיינו מחצית השקל כמבואר בלק\"ת<sup data-n=\"6537\">48</sup> וכנ\"ל. אמנם יש בזה עוד מדרגה שלישית והוא להיות כי הטפ[ו]ת [ה]חסדים [ה]עליונים שיורדים בבחי' או\"ח לעשות בחי' העלאת מ\"נ למטה הוא בחי' טפה א' לבד דהיינו [ענין] התעוררות כללי בהעלם האהבה כדי לעורר את המקבל ולא [ל]דבר מיוחד דוקא, ואנו רואים שהמקבל יתעורר אח\"כ בכמה אופנים דהיינו בשני דברים בדרך כלל באהבה<sup data-n=\"6538\">49</sup> ויראה חו\"ג, והרי א\"א לומר שהיראה שנתעוררה במקבל נתעוררה מעצמה כי אין לך דבר במקבל",[["6516","27","<b>ח\"ס דלי\"ת</b>: ראה גם לעיל פ' יתרו רנט, ד. וש\"נ."],["6517","28","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["6518","29","<b>למל' הנק' דלי\"ת</b>: ראה זהר (רע\"מ) פינחס רנז, ב. ת\"ז סתמ\"ב. תמ\"ז."],["6519","30","<b>אשה ריח ניחוח</b>: ויקרא א, ט. ועוד."],["6520","31","<b>הן</b>: דח: ליתא."],["6521","33","<b>מימינו אש דת למו</b>: ברכה לג, ב."],["6522","34","<b>אש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז [ד\"ה שחורות]. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["6523","32","<b>והתור\"ה היא הממוצע. . הת\"ת</b>: ברכות נח, סע\"א. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' תיב. וראה גם לעיל פ' בשלח קעג, א."],["6524","35","<b>האלו שהעולם</b>: דח: העולם."],["6525","36","<b>העולם שהוא ז\"א</b>: ראה ע\"ח (שער הארת המוחין) של\"ב, פ\"ה. (שער לאה ורחל) של\"ט, פ\"ח. שער מאמרי רז\"ל סנהדרין צז, א (ל, ב)."],["6526","37","<b>או\"ח</b>: דחטו: או\"י."],["6527","38","<b>כנ\"ל</b>: שם: כו'."],["6528","39","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["6529","40","<b>בבחי' או\"ח</b>: דח: אח\"כ באו\"ח."],["6530","41","<b>בהתגברות</b>: דחטו: בתגבורת."],["6531","42","<b>הם</b>: דח: ליתא."],["6532","43","<b>כמו\"כ</b>: שם: ליתא."],["6533","44","<b>אתעדל\"ת</b>: דחטו: אתעדל\"ע."],["6534","45","<b>אין טפה יורדת</b>: נסמן לעיל פ' יתרו רעו, ב."],["6535","46","<b>כדכד שמשותיך</b>: ישעי' נד, יב. במאמרי אדה\"ז תקס\"ג כאן ע' קפא (ובתו\"א כאן): כ\"ד כ\"ד."],["6536","47","<b>ב' שמות דהוי'</b>: גח: בחי' שמות הוי'."],["6537","48","<b>לב' שמות. . בלק\"ת</b>: ראה שם ר\"פ תשא. טעהמ\"צ שם. דרמ\"צ כאן סד, ב ואילך. מאמרי אדה\"א שמות ח\"ב כאן ע' תרמה."],["6538","49","<b>דברים בדרך כלל באהבה</b>: גח: בחי' דהיינו אהבה."]]],[2300550160,"[בלתי] <b>שיבא</b> מתחלה התעוררות מן המשפיע כידוע. וא\"כ מוכרח לומר שהי' התעוררות היראה שבמקבל ג\"כ באותה טפה של חסד עליון שירד מלמעלה לעורר את המקבל אך שהי' בהעלם, דהיינו שהי' המשכת התעוררות כללי לעורר את המקבל והי' כלול מכל מה שנתעורר המקבל אח\"כ מחו\"ג. וזהו אין לך טפה שהוא מחצית השקל השנית שיורד בבחי' או\"ח מלמעלה<sup data-n=\"6539\">50</sup> שאין ההעלאת מ\"נ מלמטה אח\"כ עולה בכפליים דהיינו טיפיים מחו\"ג אוי\"ר כנ\"ל. וזהו רמז מ\"ש ואולך אתכם קוממיות<sup data-n=\"6540\">51</sup> בשתי קומות להורות על הגדלת התעוררות המקבל ב' כפליים<sup data-n=\"6541\">52</sup> מקומה של המשפיע שירד אליה לעוררה כנ\"ל וד\"ל.\n<b>לפקודיהם</b><sup data-n=\"6542\">53</sup> כו', הנה במחצית השקל שנתנו כופר נפשם הי' מהם הקרבנות<sup data-n=\"6543\">54</sup> שהוא תרומה להוי'<sup data-n=\"6544\">55</sup>, וביאור ענין התרומה היינו בחי' או\"ח שעי\"ז שעולה המל' ב[בחי'] עילוי אחר עילוי כמ\"ש בזהר ארמות\"א להוי'<sup data-n=\"6545\">56</sup> כו'. אמנם יש להבין מהו ענין לפקודיה\"ם <span data-k=\"pg\">1140</span> ּ שהוא לשון חסרון כמו יפקד מקום דוד<sup data-n=\"6546\">57</sup> כו', להיות כי מבואר בזהר ויקהל איך שבשבת הוא עליי' המל' מק\"נ<sup data-n=\"6547\">58</sup> ויתפרדו<sup data-n=\"6548\">59</sup> כל החיצונים שיונקי' מבחי' אחוריים כמו מהצפרנים דידים ורגלים כו' ורחיצת<sup data-n=\"6549\">60</sup> הרגלים מכל טינוף ולכלוך כמ\"ש רחצתי את רגלי<sup data-n=\"6550\">61</sup> כו'. וביאור הדבר הוא, בהיות כי הרי<sup data-n=\"6551\">62</sup> ידוע שהמל' היא ראש לשועלים<sup data-n=\"6552\">63</sup> ותתן טרף לביתה<sup data-n=\"6553\">64</sup> בי\"ע לכל העולמות גם לנוג\"ה שבכל עולם מאחר<sup data-n=\"6554\">65</sup> שמסתתרת בסתר המדרגות בירידה אחר ירידה להחיות רוח שפלים כו', א\"כ יכולים הכל לקבל אף החיצוני' עד הע' שרים<sup data-n=\"6555\">66</sup> דעשי' מקבלים יותר<sup data-n=\"6556\">67</sup> השפע מבחי' הצפרנים כידוע בענין ועשתה את צפרני'<sup data-n=\"6557\">68</sup> כו'. והנה עיקר סיבת מותרי ההשפעה הוא מחמת הערבוביא דטו\"ר<sup data-n=\"6558\">69</sup> שנפל בשביר\"ה וצריך בירור כידוע ובח\"כ' דוקא אתברירו<sup data-n=\"6559\">70</sup> להפריד ולהבדיל בין טמא לטהור<sup data-n=\"6560\">71</sup> כו', לכך בשבת שעלי' המל' היא בחכ' ומוחין<sup data-n=\"6561\">72</sup> כידוע אז נבדלו ונפרדו יניקת החיצוני' ונבדל החול מן הקדש ואנפהא נהירין<sup data-n=\"6562\">73</sup> כו' וזהו ענין רחיצת הרגלים הנז' בזהר ויקהל<sup data-n=\"6563\">74</sup> כנ\"ל וד\"ל. ועד\"ז יובן<sup data-n=\"6564\">75</sup>",[["6539","50","<b>או\"ח מלמעלה</b>: אגט: או\"י. דטו: כבפנים. במאמרי אדה\"א כאן ע' תרמה: או\"ח למעלה."],["6540","51","<b>ואולך אתכם קוממיות</b>: בחוקותי כו, יג. ב\"ב עה, א. ראה גם לעיל פ' שמות יג, ד. מאמרי אדה\"א שמות ח\"ב כאן ע' תרמו. וש\"נ."],["6541","52","<b>ב' כפלים</b>: גחטו: בכפלים."],["6542","53","<b>לפקודיהם</b>: תשא ל, יב."],["6543","54","<b>במחצית השקל. . הקרבנות</b>: ראה רש\"י תרומה כה, ב. תשא ל, טו. ירושלמי שקלים פ\"א, ה\"א. מגילה כט, ב."],["6544","55","<b>במחצית השקל. . תרומה לה'</b>: תשא ל, יג."],["6545","56","<b>תרומה. . בזהר </b>[דח: ליתא]<b> ארמות\"א להוי'</b>: לעיל פ' יתרו רסח, ד: בזהר בפ' תרומה — ראה שם קמז, א."],["6546","57","<b>יפקד מקום דוד</b>: גח: ויפקד. טו: נפקד — נסמן לעיל שפב, ג הערה 132."],["6547","58","<b>בזהר ויקהל איך שבשבת הוא עליי' המל' מק\"נ</b>: ראה זהר שם רג, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370502\" data-slug=\"torah-or\" data-id=\"3901370502\">תו\"א כאן קיב, ד</a> [ושם: בע\"ש]."],["6548","59","<b>ויתפרדו</b>: אד: ניתוסף: כל פועלי און — ע\"פ תהלים צב, י. ראה גם פע\"ח (שער השבת) שי\"ח, פ\"ג."],["6549","60","<b>ורחיצת</b>: דחטו: ורוחצ[ו]ת."],["6550","61","<b>רחצתי את רגלי</b>: שה\"ש ה, ג. ראה גם פע\"ח שם."],["6551","62","<b>כי הרי</b>: דח: ליתא."],["6552","63","<b>שהמל' היא ראש לשועלים</b>: ראה ז\"ח (מדהנ\"ע) שה\"ש עא, א. הנסמן לעיל פ' וארא נד, ב."],["6553","64","<b>ותתן טרף לביתה</b>: משלי לא, טו."],["6554","65","<b>מאחר</b>: דח: ליתא."],["6555","66","<b>הע' שרים</b>: ראה זהר בראשית מו, סע\"ב. לעיל פ' שמות לז, ג הערה 52. שע\"ת עד, א הערה 2."],["6556","67","<b>יותר</b>: דחטו: [מ]מותרי."],["6557","68","<b>ועשתה את צפרני'</b>: תצא כא, יב. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקלז ובהנסמן (בריש המאמר שם) בע' תקלח."],["6558","69","<b>הערבוביא דטו\"ר</b>: ראה גם ע\"ח (שער הקליפות) שמ\"ח, פ\"ג. שערי קדושה — להרח\"ו — ח\"א שער א. מאמרי אדה\"א ויקרא ח\"ב ע' תדש. וש\"נ. מאמרי אדה\"א הנחות תקע\"ז ע' פג. וש\"נ."],["6559","70","<b>ובחכ' דוקא אתברירו</b>: נסמן לעיל פ' יתרו רסו, ד."],["6560","71","<b>ולהבדיל בין טמא לטהור</b>: ע\"פ שמיני יא, מז."],["6561","72","<b>בשבת שעלי' המל' היא בחכ' ומוחין</b>: ראה פע\"ח (שער השבת) שי\"ח, פ\"ז. פ\"י. וראה גם מאמרי אדה\"ז על מאמרז\"ל ע' רמד."],["6562","73","<b>ואנפהא נהירין</b>: זהר תרומה קלה, ב."],["6563","74","<b>רחיצת הרגלים הנז' בזהר ויקהל</b>: ראה שם רד, א. מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע שסא ואילך (נוסחא שני') ושם: בע\"ש. ראה פע\"ח שם פ\"ג. מ\"ח מסכת יום הששי פ\"ח, מ\"א."],["6564","75","<b>ועד\"ז יובן</b>: דח: ועתה יובן ג\"כ."]]],[2300550192,"ענין מחצית השקל שהי' ג\"כ ענין<sup data-n=\"6565\">76</sup> עליי' המל' ארמות\"א לה' כנ\"ל ואז נפרדו כל החיצוני' ויצא הטוב מן הרע נקי מכל פסולת וסי\"ג אפי' בדק שבדקין כנ\"ל. וזהו ונתנו [איש] כופר נפשו<sup data-n=\"6566\">77</sup> פי' כופ\"ר להסיר ולהבדיל כל חלק[י] הרע מכל וכל כו', והיינו לפקודיה\"ם לה[ח]סי\"ר יניקת החיצוני' מותרות<sup data-n=\"6567\">78</sup> השפע מפני שיבד[י]ל המותרות והשמרים ויהי' תכלית הבירור ע\"י תרומת השקלים כנ\"ל וד\"ל. וזהו כי תשא את ראש בנ\"י<sup data-n=\"6568\">79</sup> פי' הגבהת והתנשאות דהיינו עליות המל' בחב\"ד שלה הוא ע\"י משה דוקא שהוא הרועה ומפרנס האמונה כנ\"ל, וזהו להיותו מבחי' יסוד אבא ואבא יסד ברתא<sup data-n=\"6569\">80</sup> פי' מחכ' שבמאציל עצמו נמשך תמיד מוחין [חדשים] לזו\"נ [ו]לחזקם, מתחלה יומשך מ\"ד כדי לברר הפסול[ת] והיינו בח\"כ' אתברירו הנ\"ל והוא לעשות הכנה להעלאת מ\"נ כנ\"ל ואח\"כ יומשך מ\"ד מהארת יסוד אבא בשביל הולדה כנ\"ל וד\"ל.\n<b>ומכל</b> הנ\"ל יובן בב' מיני המשכות מ\"ד [ה]נ\"ל שעיקר ההפרש ביניהם הוא זה, להיות כי החכ' הנק' קדש עילאה כשנמשכת מבחי' עצמותה היא המבררת כל הבירורים ויתפרד כל סי\"ג מחמתה והיינו כענין<sup data-n=\"6570\">81</sup> שמי\"ם לא זכו בעיניו<sup data-n=\"6571\">82</sup> [ה]נ\"ל וכן מצרף לכסף<sup data-n=\"6572\">83</sup> כו', וזהו<sup data-n=\"6573\">84</sup> שבעמקות החכמה יתברר כל טעות ויפרד ויהי' השכל נקי כו', משא\"כ בחיצוני' חכ' יתערב הטעות הדק כו' וד\"ל, והוא המשכת מ\"ד בחכ' אתבריר\"ו והיינו לעורר את האהבה כנ\"ל שימצא חיים בעיניו כנ\"ל<sup data-n=\"6574\">85</sup>. אבל המשכת מ\"ד להולדה שאחרי העלאת מ\"נ אינו מעצמיות החכ' כ\"א המשכתו והשפעתו בדרך ירידה והשתל' מטה מטה כמשל כף ימיני היורד וכנ\"ל, ובכל השפעה ימצא הפסולת בהעלם כידוע ע\"כ מזה סיבת התערובות בהשתלשלו' העולמות מטו\"ר את זה לעו\"ז עשה<sup data-n=\"6575\">86</sup> כו' כידוע. משא\"כ במ\"ד הראשון לא יגור במגורו רע<sup data-n=\"6576\">87</sup> שום מקור למציאות פסולת מצד עוצם [בחי'] ההתנשאות בבחי' עצמיות שהוא טהור עינים<sup data-n=\"6577\">88</sup> כו' ע\"ד ששמי\"ם לא זכ\"ו כו', וזהו את\"ה מרו\"ם [לעולם] ה'<sup data-n=\"6578\">89</sup> אויביך [יאבדו] יתפרד\"ו<sup data-n=\"6579\">90</sup> אפי'",[["6565","76","<b>ענין</b>: שם: ליתא."],["6566","77","<b>ונתנו [איש] כופר נפשו</b>: תשא ל, יב."],["6567","78","<b>מותרות</b>: דחטו: ממותרי."],["6568","79","<b>כי תשא את ראש בנ\"י </b>[אד: ליתא. טו: כו']: תשא ל, יב."],["6569","80","<b>ואבא יסד ברתא</b>: ראה זהר (רע\"מ) פינחס רנו, ב. רמח, א. רנח, א. מאמרי אדה\"א קונטרסים ס\"ע תקמז ואילך. וש\"נ. לעיל פ' שמות יב, א."],["6570","81","<b>כענין</b>: דח: ליתא."],["6571","82","<b>שמי\"ם לא זכו בעיניו</b>: איוב טו, ט."],["6572","83","<b>מצרף לכסף</b>: נסמן לעיל שפא, ד."],["6573","84","<b>כו' וזהו</b>: גח: וכמו."],["6574","85","<b>חיים בעיניו כנ\"ל</b>: ג: חייב בו. ט: חיוב בו. טו: חייב בעיניו כו'."],["6575","86","<b>את זה לעו\"ז עשה</b>: קהלת ז, יד."],["6576","87","<b>לא יגור במגורו רע </b>[דח: ליתא]: ראה שבת קמט, ב."],["6577","88","<b>טהור עינים</b>: חבקוק א, יג."],["6578","89","<b>את\"ה מרו\"ם [לעולם] ה'</b>: תהלים צב, ט [ושם: ואתה]."],["6579","90","<b>אויביך [יאבדו] יתפרד\"ו</b>: תהלים שם, י."]]],[2300550224,"הדוקי\"ן שבעין כנ\"ל לפי שבח\"כ' העצמיי' אתברירו <span data-k=\"pg\">תקע</span> ּ לגמרי מכל וכל וד\"ל. ועליו נא' ורע\"ה אמונ\"ה שהוא בחי' יסוד אבא שיורד במל' לברר בירורים בכל יום<sup data-n=\"6580\">91</sup> כמבואר בע\"ח וד\"ל.",[["6580","91","<b>יסוד אבא שיורד. . בירורים בכל יום</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' שפ. וש\"נ."]]],[2300550065,"<b>בעזה\"ש ביאור השני בע\"א</b>\n<b>להבין</b> בתוס' ביאור שרשי הדברים הנ\"ל<sup data-n=\"6581\">1</sup>, הנה<sup data-n=\"6582\">2</sup> יש להבין תחלה פי' מאמר הרע\"מ ריש [פ'] כי תשא<sup data-n=\"6583\">3</sup> וז\"ל מאן מחצית השקל כגון<sup data-n=\"6584\">4</sup> חצי ההי\"ן ודא וי\"ו ממוצע בין שני ההי\"ן אבנא למשקל בה דא יו\"ד [עשרים גרה השקל<sup data-n=\"6585\">5</sup> דא יו\"ד] כו' ע\"ש עד סוף המאמר. ויש להקדים תחלה כללות ענין מ\"נ ומ\"ד, הנה מבואר בספרי הרפואה באיכות התהוות הולד מזרע איש ואשה שהוא כמו המחבץ שמניח עור הקיבה בכלי מלא חלב אז הקיבה החמוצה מפרדת חלק הטוב שבחלב ומתכווץ בפ\"ע והקום הנק' מי חלב יתפרד לעצמו כידוע, כן זרע האשה מתקבץ תחלה הנק' מ\"נ וטפת [ה]מ\"ד אבא<sup data-n=\"6586\">6</sup> אח\"כ עושה פירוד להפריד במ\"נ חלק הטוב שמתכווץ בפ\"ע וממנו עיקר פנימי' הולד כו', והפסולת שבמ\"נ מתפרד בפ\"ע וממנו נעשה עור הולד הנק' שליא<sup data-n=\"6587\">7</sup> וכל מיני פסולת כדם הנדה כו' וד\"ל<sup data-n=\"6588\">8</sup> ע\"ש, וכמארז\"ל אודם שבאשה<sup data-n=\"6589\">9</sup> [ש]ממנו [נעשה] בשר [וגידין<sup data-n=\"6590\">10</sup> ] כו' אבל מן הלובן אינו אלא עצמות וצפרנים כו' הרי עיקר מהות הולד הוא מזרע האשה, אך [ש]לא הי' מתחלק ונפרד בו<sup data-n=\"6591\">13</sup> הפנימי' מן החיצוניות כ\"א אחרי המשכת המ\"ד שכח הטפה של המ\"ד הוא המעמיד ומכווץ את הטוב מהמ\"נ כנ\"ל, ומה שנק' עיקר הולד ע\"ש טפת דכורא המוליד היינו לפי שהוא עיקר המעמיד והמקיים אבל לא שמהות הולד ממנו<sup data-n=\"6592\">11</sup> כו' וכמ\"ש במ\"א וד\"ל.\n<b>ויובן</b> כיוצא בזה בהולדה רוחני' מאין ליש נשמות ומלאכים עליונים ממ\"נ דנוק' דאצי' כידוע שעיקר מהותם הוא<sup data-n=\"6593\">12</sup> מהמ\"נ דוקא, אבל המ\"ד דאצי' הוא המברר והמפריד את חלק התמצית שממנו פנימי' הנשמה והמלאך, והפסולת שבמ\"נ נעשה",[["6581","1","<b>להבין בתוס' ביאור שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי מדרוש אביו כ\"ק אדה\"ז. נדפס גם במאמרי אדה\"ז תקס\"ג ח\"א ע' קפג. ושם: ישנו קטע נוסף וניתוסף כאן [חלק מקטע זה נדפס בשינויים בתו\"א תשא קיב, ד]. ובשינויים בס' דרך מצותיך ע' סז ואילך. באוה\"ת תשא ע' א'תתקג אומר: ביאור ב, ותוכן המאמר לבאר ענין מ\"ד ב' שאחר המ\"ן שלא נת' עדיין בביאור א', ובזה יובן היטב מעלת המ\"ן שהוא בחי' אתעדל\"ת בעבודת ה' שממנו כל עיקר הולדת נשמות ומלאכים ובחי' מוחי' חדשים, והוא ענין המחצית השקל תרומה לה' כנ\"ל. ולאח\"ז באים שם קיצורים להמאמר. וראה גם ביאוה\"ז להצ\"צ כרך ב' ע' תתכ. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["6582","2","<b>הנה</b>: דחטו: ליתא."],["6583","3","<b>הרע\"מ. . תשא</b>: קפז, ב."],["6584","4","<b>כגון</b>: ברע\"מ שם: איהו כגון."],["6585","5","<b>עשרים גרה השקל</b>: תשא ל, יג."],["6586","6","<b>אבא</b>: דחטו: הבא."],["6587","7","<b>והפסולת שבמ\"נ. . שליא</b>: ראה גם לעיל פ' שמות ט, ד. וש\"נ."],["6588","8","<b>הנדה כו' וד\"ל</b>: שם: הלידה וכו'."],["6589","9","<b>אודם שבאשה</b>: ראה נדה לא, א."],["6590","10","<b>שבאשה. . [וגידין]</b>: ראה גם לעיל פ' שמות ט, ג ובהערה 429."],["6591","13","<b>ונפרד בו</b>: שם: ומתפרד."],["6592","11","<b>עיקר מהות הולד. . האשה. . לא. . ממנו</b>: ראה לעיל ט, ג. וש\"נ."],["6593","12","<b>הוא</b>: דח: ליתא."]]],[2300550097,"ממנו בחי' עור הולד הנק' שליא [וכו'], והוא ענין הלבושים של הנשמה אלקי' הנק' צלם<sup data-n=\"6594\">14</sup> כנז' בזהר בענין הצלמים<sup data-n=\"6595\">15</sup> כו'. וביאור הדבר הוא מה שאנו רואים בנפש האלקי' שכבר נתחברה בחומר הרוחני' של נפש הבהמי' שמד' יסודות כו'<sup data-n=\"6596\">16</sup> והרי המה ב' הפכי' בערך שהאלקי' מובדל בערך מן גשמיות הנפש הבהמי' ואיך תוכל לירד כ\"כ להתחבר בנה\"ב, אך הענין הוא שיש בנה\"א צלמים הנק' לבוש ועור המכסה עלי' מעת הולדה מאין ליש ואותו הלבוש הוא כח רוחני הנמוך מכל מדרגות הנפש כערך לבוש גשמי לגוף גשמי'<sup data-n=\"6597\">17</sup> לכך ביכולתו לירד ולימשך להתחבר ולהתלבש<sup data-n=\"6598\">18</sup> בחומר נפש הבהמית וע\"י הלבושים הנק' צלם מתחברת גם פנימי' נר\"נ ח\"י של הנה\"א בגוף הגשמי וכמ\"ש במ\"א באריכות<sup data-n=\"6599\">19</sup> וד\"ל, או כמו<sup data-n=\"6600\">20</sup> שאנו רואים בכל ניצוץ אלקי אפי' דעשי' בעוה\"ז<sup data-n=\"6601\">21</sup> יש פנימי' וחיצוניות כמו רעותא דלבא<sup data-n=\"6602\">22</sup> מנקודה פנימי' ה[י]א תמצית של הנפש<sup data-n=\"6603\">23</sup> מפנימי' המ\"נ דנוק' דאצי' שנברר ע\"י המ\"ד כנ\"ל, [ו]בחי' החיצוניות הוא פעולת ועשה טוב במח' דבור ומעשה כל היום שלא מחמת התפעלות פנימי' הוא מבחי' פסולת המ\"נ דנוק' שיוצא ונדבק סביב לולד כו' ועד\"ז גם בנשמות הגבוהים דבריאה ויצי' בהשגות אלקות והתפעלו' אהוי\"ר כו' ויש להן לבושי' חיצוני' <span data-k=\"pg\">1142</span> ּ שמבחי' שלי\"א העליונה בעודם בבטן מל' דאצי' כו' ובאותן הלבושי' עומדים בג\"ע<sup data-n=\"6604\">24</sup> העליון ותחתון כמבואר בזהר וע\"ח וד\"ל. ומזה יוכל המשכיל להבין בכללות ההשתלשלו' דכל<sup data-n=\"6605\">25</sup> העולמות מאין ליש מבחי' מ\"נ כו' עד חיצוניות דחיצוניות דק\"נ דבי\"ע הוא מד\"ם נדות פסולת המ\"נ שנשאר בלתי בירור בשעת עיבור ולידה כו' וד\"ל.\n<b>והנה</b> התהוות המ\"נ בנוק' הוא מן המאכלים שאוכלת שנהפך המאכל לדם ובא למוח ונתחזק המוח עי\"ז ואז בכוחה להוריד ממוחה המ\"נ כו', והרי ידוע שהמאכל שאדם אוכל הוא גבוה בשרשו מנפש האדם מפני שנפל המאכל בשבירה [מ]שם ס\"ג<sup data-n=\"6606\">26</sup> כו' וכמ\"ש במ\"א באורך בענין כי לא על הלחם לבדו<sup data-n=\"6607\">27</sup> כו', דמאחר שאנו רואים שהאדם יחי' ומתקיים ע\"י המאכל מוכרח שהמאכל גבוה ממנו [ו]לכך מחייהו כנ\"ל<sup data-n=\"6608\">28</sup>. וכנראה בחוש",[["6594","14","<b>הלבושים של הנשמה. . צלם</b>: ראה גם לעיל פ' בשלח רו, ב ואילך. וש\"נ."],["6595","15","<b>בזהר בענין הצלמים </b>[דחטו: הצללים]: שה\"ש ב, יז. ראה זהר ויחי רכ, א. ויקרא יג, ב. תזריע מג, א."],["6596","16","<b>כו'</b>: דח: ליתא."],["6597","17","<b>גשמי'</b>: דח: ליתא. טו: גשמי."],["6598","18","<b>ולהתלבש</b>: דח: ליתא."],["6599","19","<b>באריכות</b>: שם: ליתא. טו: בארוכה."],["6600","20","<b>או כמו</b>: דח: וכמו."],["6601","21","<b>בעוה\"ז</b>: דחטו: בע\"ה בעם הארץ."],["6602","22","<b>רעותא דלבא</b>: זהר וירא ק, א."],["6603","23","<b>של הנפש</b>: דח: נפש אלקית. טו ניתוסף: האלקית."],["6604","24","<b>ובאותן הלבושי' עומדים בג\"ע</b>: ראה גם לעיל פ' וארא סב, ג. וש\"נ."],["6605","25","<b>דכל</b>: דח: ליתא."],["6606","26","<b>בשבירה [מ]שם ס\"ג</b>: ראה מבו\"ש ש\"ב ח\"א, פ\"א. מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 9. לקמן שפד, סע\"ד ואילך."],["6607","27","<b>כי לא על הלחם לבדו</b>: ראה גם לעיל פ' וארא נה, ב. וש\"נ."],["6608","28","<b>כנ\"ל</b>: דח: ליתא. טו: כו'."]]],[2300550129,"שיתוסף שכל חדש<sup data-n=\"6609\">29</sup> באדם ע\"י המאכל מה שלא הי' יכול לחדשו מקודם שאכל כענין עד לא אכילנא בישרא דתורא<sup data-n=\"6610\">30</sup> כו' חמרא פקחא<sup data-n=\"6611\">31</sup> כו', וא\"כ הי' שכל זה החדש במאכל דוקא בבחי' העלם שנפל מטעמים העליונים דס\"ג כו' מאחר שמצד עצמיות הנפש לא הי' מחדש שכל זה כו', והגם שאינו יכול להמציא שכל זה העמוק מנפשו שנלקחה מחכ' שבאצי' עפ\"י סדר ההשתל' כו'<sup data-n=\"6612\">32</sup>, אבל מצד המאכל ששרשו קודם שנפל בשבירה הוא בבחי' נקודים<sup data-n=\"6613\">33</sup> שלפני האצי' אשר החכ' דשם הוא הגבה מאד נעלה מחכמה דאצי' שבברודים<sup data-n=\"6614\">34</sup> אחר התיקון כידוע, לכך ממציא השכל ע\"י בישרא דתורא מה שלא הי' יכול להשיג מקודם וכמבואר כ\"ז במ\"א וד\"ל.\n<b>ומאחר</b> שכן גם במל' דאצי' יובן כן להיות כי ידוע ענין המאכלים שהמל' אוכלת היינו מה שהיא מלקטת ניצוצות הקדושות מרפ\"ח ניצוצין<sup data-n=\"6615\">35</sup> שנפלו בשבירה כי בכל לילה כתיב ותקם בעוד לילה ותתן טרף לביתה<sup data-n=\"6616\">36</sup> כו', פי' מסתתרת בכל העולמות דבי\"ע ומשפיע להם מזון גם להיכלות דנוג\"ה מאחר שיורדת בסתר המדרגות להחיות רוח שפלים<sup data-n=\"6617\">37</sup> הכל מקבלים כידוע, ובעת התפלה הוא שעת העלי' שלה<sup data-n=\"6618\">38</sup> כמבואר בפע\"ח. וביאור הדבר היינו שהעלאת מ\"נ של כל הנבראי' פנימי' וחיצוני' דבי\"ע שמעלין לה בעת קבלת[ם] השפע הוא כדוגמת המאכלים וכשיתבררו אח\"כ בחב\"ד דנוק' ונעשים מוחין חדשי' מהן בכל בוקר בזאת היא עולה בעלייתה בשעת התפלה כו', והטעם לחיזוק וחידוש המוחין דנוק' הוא ע\"י אכילתה ולקיטת\"ה בהיכלות נוג\"ה דבי\"ע המעורבים טו\"ר<sup data-n=\"6619\">39</sup> דוקא, לפי שהן בשרשן קודם השבירה משם ס\"ג שלפני האצי' [ו]כמו המאכל גשמי שיוליד שכל חדש במוח כנ\"ל במשל. כמו\"כ מאחר שסיבת ירידת ההשתל' כ\"כ עד מציאת נוגה הוא מחמת השביר\"ה דס\"ג דנקודים כידוע, א\"כ יש בחלק הטוב שהיא מבררת בנוג\"ה ועולה למ\"נ דנוק' דאצי' יתרון מעלה מן המ\"נ עצמן<sup data-n=\"6620\">40</sup> עד שיתן לה תוס' [ו]חיזוק ותוס' מוחי' חדשים ונעלי' מן הראשוני' בכל בוקר כו' וד\"ל. וכשנתחזק ונתחדש המוחין דנוק' ע\"י הבירורי' בכל לילה אז קמ\"ה בשח\"ר ומעלה מ\"נ שלה שנמשכי' מחב\"ד שלה שנתחדשו מן המאכלים שאכלה כו', וזהו הבירור הראשון שהוא עלי[ו]ת המל' בשעת התפלה בחב\"ד <span data-k=\"pg\">תקעא</span> ּ שלה שממשיכים מ\"נ ועולין אח\"כ למעלה לקבל מ\"ד כמבואר",[["6609","29","<b>חדש</b>: חד: ליתא. טו: כבפנים."],["6610","30","<b>עד לא אכילנא בישרא דתורא</b>: ראה ב\"ק עב, רע\"א. מאמרי אדה\"א הנחות תקע\"ז ע' קמט. שמות ח\"א ע' ה. וש\"נ."],["6611","31","<b>חמרא </b>[ד: ניתוסף: וריחנא]<b> פקחא</b>: ראה יומא עו, ב. תניא פ\"ז ובמהדו\"ק שם ע' נא."],["6612","32","<b>כו'</b>: דח: כנ\"ל."],["6613","33","<b>נקודים</b>: א: חסר. ח: העקודים."],["6614","34","<b>שבברודים</b>: אגדח: שבבירורים."],["6615","35","<b>מרפ\"ח ניצוצין</b>: נסמן לעיל פ' יתרו ערב, ד."],["6616","36","<b>ותקם. . ותתן טרף לביתה</b>: משלי לא, טו."],["6617","37","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["6618","38","<b>ובעת התפלה. . העלי' שלה</b>: ראה פע\"ח (שער התפלה) ש\"א, פ\"ו. פ\"ז. וראה גם מאמרי אדה\"ז על ענינים ע' תמט."],["6619","39","<b>בהיכלות נוג\"ה דבי\"ע המעורבים טו\"ר</b>: ראה גם לעיל פ' וארא נח, ד."],["6620","40","<b>המ\"נ עצמן</b>: ד: המל'. אגח: המל' עצמה. טו: כבפנים."]]],[2300550161,"בזהר דאשדי מיין למקבלי'<sup data-n=\"6621\">41</sup> כו' וד\"ל. והמשכת המ\"ד הבא מלמעלה אחרי עלי[י]תה הוא הבירור השני לברר את שכבר נברר דהיינו לברר את המ\"נ שעולה כו'.\n<b>וביאור</b> הדבר היינו כמשל המחבץ הנ\"ל שאינו אלא להפריד התמצית מן הפסולת כו', כמ\"כ עד\"מ המשכת טפת דכורא דאצי' הוא כדי לברר את המ\"נ דנוק'<sup data-n=\"6622\">42</sup> דאצי' ויובדל חלק הטוב והתמצית בפ\"ע ויתפרדו כל פסולת בפ\"ע כו', וזהו עיקר היסוד<sup data-n=\"6623\">43</sup> [ה]עליון דהיינו כדי להוליד נשמות ומלאכי' פנימי' וחיצוני', דהיינו מפנימי' המ\"נ שנ[ת]ברר ע\"י המ\"ד נולדו [משם] נשמות הגבוהות ומחיצוניו' הנדחה לחוץ יומשך שפע מותרות לחיצוני' עד הע' שרים דעשי' כנ\"ל. [והנה הבירור שאחר הבירור הזה<sup data-n=\"6624\">44</sup> הגם שאין הנולדים מתהווים ממהות המ\"ד כנ\"ל] עכ\"ז הוא עיקר המקור ועל שמו יקראו כמו<sup data-n=\"6625\">45</sup> פלוני הוליד פלוני שהולד נק' ע\"ש האב דוקא המוליד כידוע. והטעם שהרי המעמיד הוא העיקר והכל הולך אחר המעמיד<sup data-n=\"6626\">46</sup> כמו שאנו רואים שאור שבעיסה או שמרים הטובים שמעמידים כל עיקר העיסה והיין וכדומיהן ובלעדם יאבדו ויתקלקלו לגמרי מפני שנותן כח גדול להתקיים וגם סיבת הפירוד הנ\"ל ימצא מפני כח של<sup data-n=\"6627\">47</sup> המעמיד כו' וכל מה שימצא טעם בעיסה ו[ב]יין הוא רק מן השמרים או השאור כו'. וכמו\"כ יובן איך שטפת דכורא הוא הכח העיקרי שמעמיד ומקיים כל מ\"נ דנוק' וגם יפריד בו כנ\"ל ונק' היולי בלשון החכמים<sup data-n=\"6628\">48</sup> כו' וד\"ל, ואעפ\"כ אין מהות<sup data-n=\"6629\">49</sup> הולד ממנו כנ\"ל<sup data-n=\"6630\">50</sup> וכמ\"ש כ\"ז<sup data-n=\"6631\">51</sup> במ\"א וד\"ל, ומטעם זה נשמת משה ויוסף שהי' עיקרם מחלקי המ\"ד היו בחי' אלקות ממש כמ\"ש במ\"א וד\"ל.\n<b>והנה</b> ידוע דמ\"ה וב\"ן דא\"ק הוא שרש מ\"ה וב\"ן דאצי'<sup data-n=\"6632\">52</sup> שאחר התיקון שהן מ\"ן ומ\"ד הנ\"ל, ושרש מ\"ה החדש דא\"ק ממצחא שהוא מלך הח' הדר<sup data-n=\"6633\">53</sup> כו' הוא שם ע\"ב דחכמה שבמצחא כו' ושרש ב\"ן דא\"ק הוא ס\"ג דבינה דא\"ק כו' ובחכ' אתברירו<sup data-n=\"6634\">54</sup> [היינו חכ' דא\"ק שמאיר במצחא ומשתלשל עד שם מ\"ה שבז\"א דאצי' שהוא המ\"ד הנ\"ל. ויש להבין כ\"ז, וגם למה דוקא בחכמ\"ה אתבריר\"ו] כו', להיות שהרי ידוע דבינה הוא ההשגה והבנת המושכל שהוא יש ודבר מה ולכך ה[ו]א בס\"ג<sup data-n=\"6635\">55</sup> אותיות ג\"ס<sup data-n=\"6636\">56</sup> כו' ומחמת הרגשת דבר מה שבבינה יפול הנופל",[["6621","41","<b>דאשדי מיין למקבלי' </b>[דח: מיא לקבלי'. ד: ניתוסף: מ\"ד]: ראה זהר נח ס, ב. ביאוה\"ז שם ו, ב."],["6622","42","<b>המ\"נ דנוק'</b>: אדח: המל'."],["6623","43","<b>היסוד</b>: שם: היחוד."],["6624","44","<b>הזה</b>: טו ניתוסף: מהמ\"ד."],["6625","45","<b>כמו</b>: דח: ליתא."],["6626","46","<b>והכל הולך אחר המעמיד</b>: לשון הגמ' שבת טו, ב."],["6627","47","<b>של</b>: דח: ליתא."],["6628","48","<b>ונק' היולי בלשון החכמים</b>: ראה רמב\"ן תזריע יב, ב. וראה גם הקדמת הראב\"ד לס\"י: הפילוסופים האלקיים. . חומר. . הנקרא בלשון יון היולי. פי' מהמלות זרות לס' האמונת והדיעות־ מו\"נ. ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"א"],["6629","49","<b>מהות</b>: דח: ליתא."],["6630","50","<b>כנ\"ל</b>: דח: ליתא."],["6631","51","<b>כ\"ז</b>: דח: ליתא."],["6632","52","<b>דמ\"ה וב\"ן דא\"ק. . מ\"ה וב\"ן דאצי'</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ב ואילך."],["6633","53","<b>מ\"ה החדש. . מלך הח' הדר</b>: ראה ע\"ח שם פ\"ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370456\" data-slug=\"torah-or\" data-id=\"3901370456\">תו\"א ויחי קג, ב</a>. לעיל פ' שמות מג, ד. וש\"נ."],["6634","54","<b>ובחכ' אתברירו</b>: נסמן לעיל פ' יתרו רסו, ד."],["6635","55","<b>דבינה. . בס\"ג</b>: ראה גם לעיל פ' וארא פד, ד הערה 810."],["6636","56","<b>בס\"ג אותיות ג\"ס</b>: מובא גם לעיל פ' בשלח קסא, ג. וש\"נ."]]],[2300550193,"בבחי' פירוד השפע בחלקים רבים עד שיהי' הטעות נולד ג\"כ בשביל<sup data-n=\"6637\">57</sup> זה המורגש וכדומה, והוא משל להבין סיבת השבירה בס\"ג דוקא כו' וד\"ל. ואמנם בח\"כ' ש[היא] למעלה מן ההשגה לגמרי לא יפול הנופל בשום טעות זר כו', מפני שהח\"כ' היינו נקודת ההשכלה ותמציתה בלתי תמשך עדיין לאורך ורוחב באותיות ההשגה כידוע, [ו]הוא תכלית הביטול והפשטת יש ודבר כו' ולכך נק' כ\"ח מ\"ה<sup data-n=\"6638\">58</sup> לומר מה פשפשת<sup data-n=\"6639\">59</sup> כו'. וכמו\"כ עד\"מ לא הי' סיבת השבירה משם ע\"ב שבחכ' כח מ\"ה, להיות כי הוא בבחי' תכלית הביטול משום שאין שם התגלות<sup data-n=\"6640\">*60</sup> יש ודבר מ\"ה כי היא קרובה יותר לאור א\"ס [ב\"ה], כידוע שאוא\"ס אין בחי' גילוי השראתו כ\"א בדבר שהוא תכלית הביטול וההשפעה<sup data-n=\"6641\">60</sup> מיש ודבר מה כו', ולכך התלבשות אור א\"ס בח\"כ'<sup data-n=\"6642\">61</sup> כ\"ח מ\"ה דוקא. וזהו הטעם שלא היתה השבירה משם ע\"ב דחכמה כי <span data-k=\"pg\">1144</span> ּ השבירה ה[י]א ירידה הגדולה מאור א\"ס [ב\"ה] להתהוות מציאות נפרדים לגמרי כו' כמו נוגה דאבי\"ע כו', וכל שאור א\"ס מאיר בכלי החכמה מפני הארת אור א\"ס לא יתערב זר [ו]חיצוני' כלל בחכמה מפני תכלית הביטול [והפשטה מיש ודבר מה] כו'. וזהו הטעם ג\"כ שהח\"כ' מבררת דוקא להיות כי נדח\"ה ממנה כל פסולת ויוצא מופרד לעצמו בלתי יתערב בנקי, וכמו בעמקות השכל יבורר כל טעות ויצא לאור כל שכל שנפל בטעות כו' מפני שלפני אור החכ' [י]מצא גם הדקות של חושך הטעות כמו שהאור הגשמי' יאיר את החשך ולכך נק' החכ' אור כידוע בענין יהי או\"ר<sup data-n=\"6643\">62</sup> כו' וד\"ל.\n<b>וזהו</b> הטעם של כח המ\"ד דז\"א דאצי' שיברר בירור אחר בירור במ\"נ דנוק' כנ\"ל לפי שבחכמ\"ה אתברירו דוקא והוא שם מ\"ה כידוע והמתברר דשם ב\"ן דנוק' כנ\"ל שרשו קודם השבירה מס\"ג דא\"ק שממנו סיבת השבירה כנ\"ל ומ\"ה החדש דממצחא דא\"ק הוא המברר כו'. וביאור הדבר כי הנה ענין א\"ק ידוע שהוא כמו בחי' יחיד\"ה<sup data-n=\"6644\">63</sup> שבנפש שבה יש ג\"כ כל מה שמסתעף ממנ[ה] בנר\"נ דהיינו שכל ומדות והשכל שבה נק' חכמה קדומ\"ה כו' כמ\"ש במ\"א בארוכה. והנה החכ' הקדומה במאציל עצמו הוא שם ע\"ב הגנוז במצחא דא\"ק ויוצא הארתו דרך כלי המצח בשם מ\"ה לברר את הב\"ן<sup data-n=\"6645\">64</sup> כו', ונוכל להבין מזה איך שהמתברר גבוה באמת הגבה מאד נעלה מן המברר<sup data-n=\"6646\">65</sup> כו' שהרי המצח הוא מסתיר לגמרי אור השכל שבמוח וההארה שיאיר במצחא כמו חכמת אדם שתאיר פניו<sup data-n=\"6647\">66</sup> כו' אינו רק בחי' חיצוניות ההארה לבד, משא\"כ ס\"ג דא\"ק שמאוזן כו' שהוא המבחין בין",[["6637","57","<b>בשביל</b>: חטו: בשכל."],["6638","58","<b>שהח\"כ'. . כ\"ח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["6639","59","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["6640","*60","<b>שאין שם התגלות</b>: אגדחטו: הרגשת."],["6641","60","<b>וההשפעה</b>: דטו: וההפשטה. ח: וההפשטות."],["6642","61","<b>התלבשות אור א\"ס בח\"כ'</b>: ראה גם לעיל פ' שמות ז, ד. וש\"נ."],["6643","62","<b>החכ' אור. . יהי או\"ר</b>: בראשית א, ג. ראה זהר בראשית ל, ב. שעה\"י קכז, ב הערה 38. שערי אורה ד, א הערה 10. לקמן פ' פקודי תמג, ג. תנג, ד."],["6644","63","<b>א\"ק. . יחיד\"ה</b>: ראה שע\"ק — להרח\"ו — ש\"ג, השער הב'. ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381204\" data-slug=\"likkutei-torah\" data-id=\"4001381204\">לקו\"ת שה\"ש יח, ד</a>. וראה גם דרך מצותיך כאן ע' סח."],["6645","64","<b>הב\"ן</b>: ד: המל'. ח: המ\"ן. טו ובדר\"מ: כבפנים."],["6646","65","<b>שהמתברר גבוה. . מן המברר</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קצ. דרך מצותיך ע' קעא."],["6647","66","<b>חכמת אדם שתאיר פניו</b>: קהלת ח, א."]]],[2300550225,"טב לביש במוח הבינה הוא בחי' פנימיות דא\"ק<sup data-n=\"6648\">67</sup> הרבה יותר כו'. ויובן זה עד\"מ אדם שמגלה איזה שכל עמוק שהי' צריך לביאור[ה] ריבוי דברים מאד והוא אומר[ה] וכולל[ה] בתיבה א[חת], הנה הסתיר והעלים כל עומק השכל בתיבה זו ולא נגלה ממנ[ה] רק אפס קצהו דהיינו מה שמובן קצת [מ]אותיות התיבה לבד, והרי זה דומה לאור הגדול שבבית שיאיר דרך נקב קטן לחוץ שאותו האור שמאיר דרך הנקב הגם שהוא מעצמיות האור שבבית אבל הוא [מאד] מעט מזעיר אך שיכולים להכיר כל האור כו'<sup data-n=\"6649\">68</sup> מן המעט יבינו את הריבוי מאחר שמהות א' הם. [ו]כמ\"כ [ה]השכלה המעוטה שמשיגי' בתיבה א'<sup data-n=\"6650\">69</sup> זו הוא כמו הנקב מן העומק של כל השכל הנעלם בה, אך יכולים להשיג כל השכל ע\"י תיבה זו מאחר שהשפעת השכל בתיבה זו הוא מעצם א' עם השכל כו'. משא\"כ אם מעלים כל עומק השכל באיזה משל וחידה או בסיפורי מעשיות, כמו סיפורי מעשיות שבתורה<sup data-n=\"6651\">70</sup> שנרמזים בה[ם] כל רזין דאורייתא כידוע ה\"ז אינו דומה כלל למשל נקב שבבית, שהרי אין מובן כלל מעצם השכל הנעלם במשל וחידה כי המשל ענין זר לגמרי הוא והנקב יש בו מהארת העצם כנ\"ל<sup data-n=\"6652\">71</sup>. אך אין זה דומה אלא לכלי מסך מבדיל כמו [ה]פרוכת <span data-k=\"pg\">תקעב</span> ּ העב שמחשיך ומעלים<sup data-n=\"6653\">72</sup> האור לגמרי ועכ\"ז הארה בעלמא יכולים להכיר מתוכו כידוע, והארה זו אינה מעצמיות הארה שלפני הפרוכת כלל רק הארה דהארה כו' וד\"ל.\n<b>ועד\"ז</b> יובן ההפרש בין נקבי העינים ואח\"פ דא\"ק להארת המצחא כי הלא הנקב שבעין יומשך בו מפנימיות המוחי' שבמוח כידוע<sup data-n=\"6654\">73</sup> בענין בת היענה<sup data-n=\"6655\">74</sup> כו', וה\"ז כמשל האור המאיר דרך נקב שבבית, וכמבואר בע\"ח<sup data-n=\"6656\">75</sup> וכן נקבי האח\"פ כמבואר שם, שהוא כמשל הנ\"ל בתיבה א' שנגלה בה מעצם השכל משא\"כ הארת המצחא מאחר שהמצח כלי מסך להסתיר לגמרי אור השכל שבמוח גם כשיבקע האור בו אינו אלא בחי' הארה דהארת המוחין ולא הארת המוחין עצמן כו'. ועוד יובן זה עד\"מ המתעורר מעצמו מצד התבוננו' שכלו ותבונתו שזהו הארת עצמיות שכלו משא\"כ [מי] שמתעורר מהתעוררו' אחרים שאותן אחרים נתפעלו משכלם שאצלו<sup data-n=\"6657\">76</sup> רק הארה דהארה כו' וד\"ל. ועד\"ז יובן ממש ענין שם מ\"ה החדש שממצחא דא\"ק הגם שמאיר פניו ומחזק את הנמוך ממנו עד דב\"נ<sup data-n=\"6658\">77</sup> דאצי' אינו אלא הארה דהארה הגם שהוא המברר דוקא כי בחכ' דשם מ\"ה אתברירו כנ\"ל, אמנם המתברר שהוא ב\"ן דנוק'<sup data-n=\"6659\">78</sup> שממנו השבירה ע\"ד<sup data-n=\"6660\">79</sup> ב\"ן דנוק' ושרשו ס\"ג דאוזן הרי",[["6648","67","<b>דא\"ק</b>: דח: ליתא."],["6649","68","<b>כו'</b>: דחטו: כי."],["6650","69","<b>א'</b>: שם: ליתא."],["6651","70","<b>סיפורי מעשיות שבתורה</b>: ראה זהר בהעלותך קמט, ב. קנב, א. קנה, סע\"ב."],["6652","71","<b>כנ\"ל</b>: דח: כו'."],["6653","72","<b>העב שמחשיך ומעלים</b>: אגדח: הזהב [א: תיקן עה\"ג: העב] שמעלים ומסתיר ומחשיך."],["6654","73","<b>המוחי' שבמוח כידוע</b>: שם: המוח וכידוע."],["6655","74","<b>בת היענה</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"א."],["6656","75","<b>וכמבואר בע\"ח</b>: ראה גם (שער התיקון) ש\"י, פ\"ב."],["6657","76","<b>שאצלו</b>: דחטו: הוא. ובדרמ\"צ: שאצלו הוא."],["6658","77","<b>דב\"נ</b>: תיבה זו אינה ברורה. דח: בזו\"נ. טו: זו\"נ."],["6659","78","<b>דנוק'</b>: שם: דא\"ק."],["6660","79","<b>ע\"ד</b>: שם: עד."]]],[2300550256,"ה[ו]א מבחי' פנימיות דא\"ק מפנימיות מוח בינה דא\"ק כו' וד\"ל. וזה הטעם יובן למה תהי' א\"ח עט\"ב לאחר שיתברר שם ב\"ן<sup data-n=\"6661\">81</sup>, כי הגם לאחר שנפל בשבירה המ\"ה<sup data-n=\"6662\">82</sup> הוא המברר כנ\"ל, אבל לאחר שנתברר הוגבהה לשרשו בפנימי' א\"ק כנ\"ל וכמשל המאכל שלאחר שנתברר ונתעלה למוח הוא מחזק את המוח כו' וד\"ל<sup data-n=\"6663\">80</sup>.\n<b>ועתה</b> יובן המאמר הנ\"ל אבנא למשקל [בי'] דא יו\"ד, פי' עד\"מ האבן אשר למשקל הרי האבן בעצמו אינו כלום כי הסחורה היא העיקר וכוונתו אינו אלא לידע משקל הסחורה כמה היא וע\"י האבן ששוקל כנגדה הוא יודע משקל הסחורה, מפני שמשקל האבן ידוע, וכשיהי' משקל הסחורה כמשקל האבן ה\"ז טוב ואם יפחות משקלה יגרע ערכה כו', וא\"כ אין האבן אלא לתועלת היד[י]ע[ה] שיתברר ע\"י משקל הסחורה אם לפחות או לגרוע כו'. וכמו\"כ עד\"מ הנה החכמה נק' יו\"ד<sup data-n=\"6664\">83</sup> כידוע, וכשהבירור דמ\"ד הנ\"ל ע\"י החכמה<sup data-n=\"6665\">84</sup> דשם ע\"ב שבמצחא כנ\"ל שהוא אז<sup data-n=\"6666\">85</sup> כמשל האבן השוקל הסחורה כו' כן המ\"ד הוא שוקל ומברר המ\"נ להפריד בו הבירור מן הפסולת ואז<sup data-n=\"6667\">86</sup> ידע ערכו ולא יהי' ב[ה] ערבובי' טו\"ר שלא ידע ערכ[ה] כנ\"ל, וא\"כ המ\"נ הוא העיקר שממנו נולד הולד כנ\"ל שהוא מפנימי' [ד]א\"ק יותר כו' שעליו [הכוונה] לידע ערך הטוב שבו כו', אך מפני חסרון ידיעה בא משקל המ\"ד לשוקלו ולהכריע בו את הטוב שיעלה למעלה והרע יפול [למטה הימנו] כי זה עיקר הבירור להעלות הטוב ולהפיל את הרע למטה, וכנז' בע\"ח בכל הבירורים כמו בירורים דע\"י<sup data-n=\"6668\">87</sup> מה שלא יוכל להתברר ולעלות [בע\"י יפול למטה הימנו דהיינו שיוברר עוד הפעם ע\"י א\"א ויעלה הטוב לא\"א, ומה שלא יוכל להתברר ולעלות] לא\"א יפול למטה הימנו באו\"א, דהיינו שיתברר ע\"י או\"א ויעלה בהם ועד\"ז עד סוף כל [הבירורים ו]המדרגות דהיינו מהפסולת האחרון שא\"א להתברר הטוב ממנו גם בעולם היצי' יפול למטה <span data-k=\"pg\">1146</span> ּ להתברר בחכ' דעשי', ומה שגם בחכמה דעשי' לא יתברר הוא הפסולת הגס מכולם שאין לו בירור לעולם והן הגבורות<sup data-n=\"6669\">88</sup> קשות דז' מדורי גיהנם<sup data-n=\"6670\">89</sup> כו', וזהו שנק' בשם אבנא למשקל מפני שאין הנולד ממהות המ\"ד אלא ממהות המ\"נ שהוא העיקר והמ\"ד אינו בא<sup data-n=\"6671\">90</sup> אלא להכריע את הטוב שבמ\"נ שיעלה מעלה כו' וד\"ל. ועכ\"ז הרי עיקר כח המעמיד [הוא רק] בטפת דכורא כי נק' היולי כו' וכנ\"ל במשל שאור שבעיסה כו', וכמו משקל האבן שכל המשקל שימצא בסחורה ימצא באבן וזהו תכלית העילוי<sup data-n=\"6672\">91</sup> כשמשקלה שוה אליו והרי האבן מכריע ומעמיד",[["6661","81","<b>א\"ח עט\"ב. . ב\"ן</b>: משלי יב, ד. ראה גם לעיל פ' וארא ע, ג הערה 74."],["6662","82","<b>המ\"ה</b>: טו: המ\"ד."],["6663","80","<b>וזה </b>[יטו: ומזה]<b>. . וד\"ל</b>: אגדח: ליתא."],["6664","83","<b>החכמה נק' יו\"ד</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן במראי מקומות לשם."],["6665","84","<b>ע\"י החכמה</b>: דח: דחכמה."],["6666","85","<b>שהוא אז</b>: דחטו: אז הוא."],["6667","86","<b>ואז</b>: שם: ועי\"ז."],["6668","87","<b>בירורים דע\"י</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש ד. (שער כללות אבי\"ע) שמ\"ב, פ\"ג. לקמן פ' ויקהל תה, סע\"ג ואילך. מאמרי אדה\"ז תקס\"ו ע' שעו."],["6669","88","<b>הגבורות</b>: ד: שורש הגבורות."],["6670","89","<b>דז' מדורי גיהנם</b>: ראה ערובין יט, א. זהר תרומה קנ, ב. (היכלות) פקודי רסג, א."],["6671","90","<b>שהוא. . בא</b>: דח: כי עיקר המ\"ד אינו."],["6672","91","<b>העילוי</b>: טו: פעולה."]]],[2300550286,"משקל הסחורה בכף שכנגדו ע\"י כובדו כו', [ו]מזה מובן הנמשל שעיקר המוליד הוא טפת דכורא אך שאין מהות הנולד ממנו כנ\"ל וד\"ל. וזהו שנמשל לאבן כי המים שבאים בבחי' דומם האבן הם באים במדה כמ\"ש אבנים שחקו מים<sup data-n=\"6673\">92</sup> כו', כמו\"כ החכ' שבמ\"ד נק' טפת דכורא שבאה במדה כלומר שמתחלקת לברר כל פרטי המדות כמו המדה של הנצח יבורר בחכ' שבנצח וכדומה חכ' שבהוד יברר ההוד וקודם שירדה החכ' בדומם האבן היו כל המדות כלולים בה ונק' נצח והוד שבחכ' כו' ועד\"ז בחכ' שבמל' הבירור הראשון דמ\"נ הנ\"ל וד\"ל.\n<b>עשרים</b> גרה השקל דא יו\"ד, הנה מתחלה אמר מחצית השקל הוא הוי\"ו הממוצע כו' וחוזר ומפרש איך כשהי' מחצית זה בהעלם בבחי' מילוי ביו\"ד<sup data-n=\"6674\">93</sup> והוא השקל השלם עשרים גרה הי'<sup data-n=\"6675\">94</sup> יו\"ד. ומתחלה יש להבין כללות ענין המילוי בכל מקום, להיות כי [הנה] ידוע ענין העיבור שהולד כלול בהעלם בבטן אמו דהיינו שישנו במציאות רק שאינו בגילוי כו', כך ענין המילוי הוא כשהמתגלה הי' תחלה בהעלם נק' אז בשם מילוי, כמו עד\"מ הדבור הוא מן השכל אבא יסד ברתא<sup data-n=\"6676\">95</sup> כידוע, והרי האותיות הדבור מה שירצה לדבר ע\"פ השכל הי' צריך תחלה לחושבן במחשבת שכלו איך לדברם וכשהיו אותיות הדבור שידבר תחלה בשכלו הי[ו] כלולים בהעלם בתוך השכל כעובר במעי אמו, [ו]כמו אותיות יו\"ד שהוא<sup data-n=\"6677\">96</sup> ראשית הכוונה על נקודת יו\"ד לבד בלא וי\"ו דלי\"ת, וכשבא לדבור יתפרש בוי\"ו דלי\"ת, אך גם כשהי' במחשבתו הי' כלול מוי\"ו דלי\"ת שיפרש בדבור רק שהי' בהעלם וזה נק' מילוי וד\"ל. ועד\"ז בכל גילוי התהוות מגבוה לנמוך כמו משכל ומדות<sup data-n=\"6678\">97</sup> הגילוי של המדות הי' בהעלם כלולים<sup data-n=\"6679\">98</sup> בתחלה בתוך השכל בבחי' מילוי וכיוצא בזה וד\"ל. וגם כאן הוא מפרש שוי\"ו דלי\"ת הוא מ\"ה וב\"ן דאצי' הוא מחצית השקל ממוחין דאו\"א עצמם שבאו לידי גילוי היו כבר בהעלם בבחי' מילוי בי' דנקודת [ה]חכמה שקל השלם שהוא שם ע\"ב דחכ' כשהי' במילוי יודי\"ן שאותו היו\"ד בלא וי\"ו דל\"ת בגילוי והן<sup data-n=\"6680\">99</sup> רק בהעלם כנ\"ל וד\"ל. וזהו שמתחלה קראו בשם אבנ\"א דאיהו יו\"ד לבד והיינו נקודת טפת אבא עצמו כנ\"ל [ש]שרשו משם ע\"ב דא\"ק<sup data-n=\"6681\">100</sup> שבתוך המצחא כו' וממנו נשתלשל למטה בגילוי במ\"ד דז\"א דאיהו וי\"ו ממוצע בין ה' עילאה לתתאה שיהי' כחו ג\"כ לברר <span data-k=\"pg\">תקעג</span> ּ המ\"נ דנוק' כידוע, וכמו עד\"מ המים שבאבן בהעלם מפני חלק הדומם וכשיתגלה יהי' מים דדכורא כו' שנמשכים מוי\"ו דלי\"ת בחי' דומם שבחכ' עילאה טפת אבא",[["6673","92","<b>אבנים שחקו מים</b>: איוב יד, יט."],["6674","93","<b>ביו\"ד</b>: דח: כו'."],["6675","94","<b>הי'</b>: ד: הוא. ח: דא."],["6676","95","<b>אבא יסד ברתא</b>: נסמן לעיל שפג, ד."],["6677","96","<b>שהוא</b>: דחט: שהי'."],["6678","97","<b>ומדות</b>: דח: למדות. טו: מדות."],["6679","98","<b>בהעלם כלולים</b>: שם: כלולים בהעלם."],["6680","99","<b>והן</b>: שם: ליתא."],["6681","100","<b>דא\"ק</b>: דח: ליתא."]]],[2300550313,"הנק' אבנא כו' וד\"ל (וזהו הכל הי' מן העפר<sup data-n=\"6682\">101</sup> פי'<sup data-n=\"6683\">102</sup> הדומם שבחכמה [כו']).\n<b>והנה</b> עשרים גרה השקל הם י\"ס דאו\"י וע\"ס דאו\"ח כי בח\"כ' דיו\"ד דע\"ב עיקר הבירור, וידוע דבכל בירור יש ב' אופנים הא' בחי' או\"י דהמברר שיורד [מ]למעלה למטה בי\"ס, והב' מה שמכח המברר נברר ועולה מלמטה למעלה בבחי' או\"ח בי\"ס ג\"כ והוא אותו כח עצמו של המברר כו', כי נעוץ תחב\"ס וסוב\"ת<sup data-n=\"6684\">103</sup> פי' כמו שהארת הראשית שהוא החכ' בסוף שהוא המל' כן הסוף נעוץ בתחלה מלמטה למעלה כשעולה בבחי' או\"ח, רק שסדרן מה[ו]פך שהתחלה נעוץ בסוף מעילה לעילה בירידות המדרגות מכתר לחכמה כו' ובחי' האו\"ח מהסוף לתחילה הוא בהיפך שהכת\"ר עולה ראשונה ואח\"כ החכ' כו'. וביאור דבר זה הנה מבואר במ\"א ע\"פ משל או\"ח של השמש<sup data-n=\"6685\">104</sup> בארץ שהרי אנו רואים תחילת הזריחה מגוף השמש מלמעלה למטה הוא יורד ומתקרר בסוף כו' וכשמכה האור בארץ ועולה בבחי' או\"ח יהי' החום בארץ יותר מכמו שהוא באמצע שכל שעולה יותר מתקרר כמבואר בספרי התכונה שבאמצעות הגובה האויר קר כו' וד\"ל. ועתה יובן ענין מחצית השקל פי' מן אבנא הנ\"ל, שקל השלם בעשרים גרה [השקל] או\"י ואו\"ח יותר<sup data-n=\"6686\">105</sup> המחצית לידי גילוי בוי\"ו דז\"א כנ\"ל לעשות [תחלה] תרומ\"ה לה', פי' לברר המ\"נ דנוק' לעלות הטוב שבה להוי' בבחי' אצי' והמותרות יפול ויפרד למטה כנ\"ל. וזהו ארמות\"א [לה' הנ\"ל] שהוא עליות המל' מחיצוני' שלה כי [ה]מלבושי' החיצוני' דנוג\"ה דבי\"ע נלקחים מפסולת המ\"נ כ[נ\"ל ב]משל המחבץ הנ\"ל, ובשעת עלי' בכל שחר הנה היא אפשיטת מכל פסולת ומתברר ועולה הטוב והנקי להוי' בבחי' אצי' ממש ומזה הוא הולדת נשמות ומלאכים פנימי' כנ\"ל, וכמו בכל שבת הוא עליות המל' היינו שנפרדים ממנה כל החיצוני' כידוע וד\"ל, וכשה[י]א עולה בבחי' או\"ח הכתר עולה ראשונה כו' וד\"ל.",[["6682","101","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["6683","102","<b>פי'</b>: דח: מן."],["6684","103","<b>נעוץ תחב\"ס וסוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["6685","104","<b>משל או\"ח של השמש</b>: ראה גם לעיל פ' בשלח רו, ג. וש\"נ."],["6686","105","<b>יותר</b>: דחטו: יורד."]]],[2300550338,"<b>וזהו</b><sup data-n=\"6687\">106</sup> ונתנו איש כפר נפשו לה'<sup data-n=\"6688\">107</sup>, פי' כפר הוא הפדיון שפודה נפשו משחת וכל פודה הענין הוא שנותן חליפין במקום<sup data-n=\"6689\">108</sup> נפשו שהוא הממון ונפשו ישאר לו כו'. וכמ\"כ הנה באמת יש מקום ליניקת החיצוני' בקרבנות המזבח מבחי' אחוריי' דאחוריי' דקדושה, שהרי ידוע בזוהר בעשן המערכה<sup data-n=\"6690\">109</sup> שהי' מתעכב ברקיעי' דעשי' ונדחה<sup data-n=\"6691\">110</sup> ומתעכב לצפון להיכלות דנוג\"ה להחיותם וליתן להם טרף ומזון כו' ע\"ש, והיינו הבירור של הפסולת דוקא כשיש להם יניקה מן הפסולת כמו העשן כו' שאז הריח ניחוח לה' מן הקרבן עצמו עד רום המעלות מפני שנתברר כו' וגם חטא האדם מתכפר עי\"ז כשנותן כופר נפשו לחיצוני' בעשן הקרבן, וכמו שהשלמים היו למזון גם ליניקת החיצוני'<sup data-n=\"6692\">111</sup> מן הפסולת כו'. וזהו הפדיון כמו<sup data-n=\"6693\">112</sup> שאומר זה חליפתי<sup data-n=\"6694\">113</sup> כו' כן אומר זה כפרתי פי' מה שהחיצוני' יונקים מפסולת קרבנות הוא לכופ\"ר ו[ל]פדיון לנפשו מרדת שחת<sup data-n=\"6695\">114</sup> אל החיצוני' ונשאר נפשו<sup data-n=\"6696\">115</sup> נקי<sup data-n=\"6697\">116</sup> לעלות לה' לבדו ואין זר איתו כו'. וכן נעשה בכללות כל העולמות שנפרדו החיצוני' מן הפנימיות, דהיינו כנ\"ל שהחיצוני' יניקתם ממותרי פסולת המ\"נ כמו השליא ודם נדות כו' וכשנותנין<sup data-n=\"6698\">117</sup> להם יניקתם נתפרדו בפ\"ע, ואז ארמותא להוי'<sup data-n=\"6699\">118</sup> שהוא עליית פנימית המ\"נ בתכלית הבירור מכל סי\"ג כו' ותרומ\"ה זו נעשה ע\"י המ\"ד המברר כי בחכמ\"ה אתברירו כנ\"ל וד\"ל. וענין אין טפה יורד מלמעלה<sup data-n=\"6700\">119</sup> כו' היינו במחצית שקל זה שיורד מ\"ד כדי לברר והוא טפת יסוד ז\"א ששרשו טפת אבא כנ\"ל טפיים<sup data-n=\"6701\">120</sup> עולין כנגדן בעליות המל', כי מבואר למעלה דס\"ג דא\"ק הוא העיקר והארת המצחא דשם מ\"ה אינו אלא הארה דהארה כו' וא\"כ לאחר שנתברר הב\"ן גדול כוחו בכפליים ממ\"ה כמ\"ש עטר\"ת בעלה וד\"ל. וענין ורעה אמונה<sup data-n=\"6702\">121</sup> היינו לעשות כח להעלאת מ\"נ כנ\"ל וכמ \"ל אנשים ללמוד<sup data-n=\"6703\">122</sup> לקבל<sup data-n=\"6704\">123</sup> בבחי' או\"פ ונשים לשמוע שמתפעלים מכללות הענין כו' שהוא בבחי' מקיף לבד כו' [וד\"ל].",[["6687","106","<b>וזהו</b>: מכאן ניתוסף ממאמרי אדה\"ז תקס\"ג כאן ע' קפט."],["6688","107","<b>ונתנו איש כפר נפשו לה'</b>: תשא ל, יב."],["6689","108","<b>במקום</b>: ח: במחיר. ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370502\" data-slug=\"torah-or\" data-id=\"3901370502\">תו\"א כאן (קיב, ד</a>) כבפנים."],["6690","109","<b>בעשן המערכה </b>[ח: הקרבנות]: ראה גם זהר תרומה קל, א. קמא, א. לעיל פ' בא קכז, א הערה 660."],["6691","110","<b>ונדחה</b>: גדח: ליתא."],["6692","111","<b>שהשלמים. . ליניקת החיצוני'</b>: ראה גם זהר פקודי רלח, סע\"ב ובהגהת מהרח\"ו אות ד."],["6693","112","<b>כמו</b>: ח: כפרות."],["6694","113","<b>זה חליפתי</b>: נוסח סדר כפרות."],["6695","114","<b>מרדת שחת</b>: איוב לג, כד."],["6696","115","<b>נפשו</b>: ג: ליתא. ח: האדם."],["6697","116","<b>נקי</b>: ג: זך ונקי."],["6698","117","<b>וכשנותנין</b>: ג: וכמו\"כ כשנותנין."],["6699","118","<b>ארמותא להוי'</b>: ראה זהר תרומה קמז, א."],["6700","119","<b>אין טפה יורד מלמעלה</b>: ראה גם לעיל שפג, ב. וש\"נ."],["6701","120","<b>טפיים</b>: גד: טיפין טיפין. ט: טפיים טפיים."],["6702","121","<b>ורעה אמונה</b>: תהלים לז, ג."],["6703","122","<b>אנשים ללמוד</b>: חגיגה ג, א."],["6704","123","<b>לקבל</b>: גדח: ליתא."]]],[2300550066,"<b>בע\"ה פ' ויקהל</b>\n<span data-k=\"pg\">1148</span> ּ<b>ויקהל</b> משה<sup data-n=\"6705\">1</sup> את כל עדת בנ\"י ויאמר אליהם אלה הדברים<sup data-n=\"6706\">2</sup> כו', ששת ימים תעשה מלאכה<sup data-n=\"6707\">3</sup> וביום השביעי וגו', וסמיך לי' ויאמר משה אל כל עדת בנ\"י זה הדבר אשר צוה ה'<sup data-n=\"6708\">4</sup>, קחו מאתכם תרומה לה'<sup data-n=\"6709\">5</sup> וגו' זהב וכסף כו', וכל חכם לב בכם יבואו ויעשו כל אשר צוה ה'<sup data-n=\"6710\">6</sup>, את המשכן את אהלו ואת מכסהו קרסיו וקרשיו<sup data-n=\"6711\">7</sup> כו' הארון<sup data-n=\"6712\">8</sup> והשולחן<sup data-n=\"6713\">9</sup> וכו' עד סוף הפרשה. ויש להבין מה שהקדים תחלה מצות השבת ואח\"כ מצות המשכן מה שייכות יש להם זע\"ז. ועוד יש להבין דלמה שינה כאן הסדר להקדים מצות שבת למצות מעשה המשכן ובפ' כי תשא הקדים מצות מעשה המשכן למצות השבת כמ\"ש שם וידבר ה' אל משה<sup data-n=\"6714\">10</sup>, ראה קראתי בשם<sup data-n=\"6715\">11</sup> בצלאל בן אורי כו' ונתתי אתו את אהליאב כו' ועשו את אשר צויתיך<sup data-n=\"6716\">12</sup>, את האהל ואת הארון<sup data-n=\"6717\">13</sup>, והשולחן<sup data-n=\"6718\">14</sup> כו' וכל פרטי כל כלי המשכן וסמיך לי' וידבר ה' אל משה<sup data-n=\"6719\">15</sup> כו', אך את שבתותי תשמרו<sup data-n=\"6720\">16</sup> כי אות היא כו', ושמרתם את השבת<sup data-n=\"6721\">17</sup> וגו' עד סוף הפרשה. ועוד יש להבין למה בפ' תרומה תצוה הקדים לצוות למשה תחלה על מעשה הארון וכפורת ושולחן ומנורה שהן כלי המשכן כמ\"ש שם ועשו ארון<sup data-n=\"6722\">18</sup> כו', ועשית כפורת<sup data-n=\"6723\">19</sup>, וכמו\"כ ועשית שולחן<sup data-n=\"6724\">20</sup>, ועשית מנורת זהב<sup data-n=\"6725\">21</sup> כו', ואח\"כ אמר ואת המשכן תעשה עשר יריעות<sup data-n=\"6726\">22</sup> כו' עד סוף הענין ועשית את הקרשים<sup data-n=\"6727\">23</sup> כו', ועשית פרוכת<sup data-n=\"6728\">24</sup> כו', ועשית מזבח<sup data-n=\"6729\">25</sup> עד חצר המשכן<sup data-n=\"6730\">26</sup>, וכאן הקדים<sup data-n=\"6731\">27</sup> ענין המשכן ויריעות אהלו וקרשיו ועמודיו ואדניו ואח\"כ הארון וכפורת ושולחן ומנורה ומזבח כו'.\n<b>ולהבין</b> את כל הנ\"ל יש להקדים לבאר תחלה שרש ענין המשכן וכליו כו', דהנה ענין המשכן בכללות הוא מ\"ש ועשו לי מקדש ושכנתי בתוכם<sup data-n=\"6732\">28</sup> דהיינו שבמקדש יהי'",[["6705","1","<b>ויקהל משה</b>: מיוסד על מאמר ד\"ה זה שנדפס במאמרי אדה\"א שמות ח\"ב ע' תרס. וכן על חלק ראשון מד\"ה ענין וסדר העבודה בעסק החסידות נדפס במאמרי אדה\"ז תק\"ע ע' מד. עוד ע\"ד המאמר ראה להלן ברשימת הכת\"י."],["6706","2","<b>ויקהל. . אלה הדברים</b>: ויקהל לה, א."],["6707","3","<b>ששת ימים תעשה מלאכה</b>: ויקהל שם, ב."],["6708","4","<b>ויאמר משה. . צוה ה'</b>: שם לה, ד [בדילוג]."],["6709","5","<b>קחו מאתכם תרומה לה'</b>: ויקהל שם, ה."],["6710","6","<b>וכל חכם לב. . ה'</b>: שם לה, י [ושם: את כל]. השוה לקמן על יד הערה 295."],["6711","7","<b>את המשכן. . וקרשיו</b>: שם שם, יא [ושם: את קרסיו ואת קרשיו]."],["6712","8","<b>הארון</b>: ויקהל לה, יב."],["6713","9","<b>והשלחן</b>: ויקהל שם, יג [ושם: את השלחן]."],["6714","10","<b>וידבר ה' אל משה</b>: תשא לא, א."],["6715","11","<b>ראה קראתי בשם</b>: שם לא, ב."],["6716","12","<b>ונתתי אתו. . צויתיך</b>: שם שם, ו [ושם: ואני הנה נתתי. . את כל]."],["6717","13","<b>את האהל ואת הארון</b>: תשא לא, ז [ושם: את אהל מועד]."],["6718","14","<b>והשולחן</b>: תשא שם, ח [ושם: ואת השלחן]."],["6719","15","<b>וידבר ה' אל משה</b>: תשא שם, יב [ושם: ויאמר]."],["6720","16","<b>אך את שבתותי תשמרו</b>: שם לא, יג."],["6721","17","<b>ושמרתם את השבת</b>: שם שם, יד."],["6722","18","<b>ועשו ארון</b>: תרומה כה, י."],["6723","19","<b>ועשית כפורת</b>: תרומה שם, יז."],["6724","20","<b>ועשית שולחן</b>: שם כה, כג."],["6725","21","<b>ועשית מנורת זהב</b>: שם שם, לא."],["6726","22","<b>ואת המשכן תעשה עשר יריעות</b>: תרומה כו, א."],["6727","23","<b>ועשית את הקרשים</b>: שם כו, טו."],["6728","24","<b>ועשית פרוכת</b>: תרומה שם, לא."],["6729","25","<b>ועשית מזבח</b>: תרומה כז, א [ושם: ועשית את המזבח]."],["6730","26","<b>חצר המשכן</b>: תרומה שם, ט ואילך."],["6731","27","<b>וכאן הקדים</b>: ראה ויקהל לה, יא ואילך."],["6732","28","<b>ועשו לי מקדש ושכנתי בתוכם</b>: תרומה כה, ח."]]],[2300550098,"השראת והמשכת עצמו' אוא\"ס שלפני הקו כו' והוא ענין דירה בתחתונים ממש, ולזאת צוה ה' לעשות תבנית המשכן וכל פרטי כליו להיות כי ע\"י המשכן וכליו דוקא יוכל להיות השראתו ודירתו למטה בגילוי גמור וז\"ש ועשו לי מקדש ועי\"ז אוכל לשכון למטה מבחי' עצמותו כמ\"ש ושכנת\"י. ואע\"פ דבלא\"ה מלא כה\"כ<sup data-n=\"6733\">29</sup> היינו רק בחי' הארת הקו המאיר בבחי' ממלא כ\"ע כידוע, והשראה זאת היא מבחי' עצמות אוא\"ס ממש שלפני כל ההשתל' הנק' סובב כ\"ע כידוע. והנה כל פרטי הכלים של המשכן הארון והשולחן והמנורה כו' היינו לנגד בחי' ע\"ס<sup data-n=\"6734\">30</sup> דאצי' למעלה שבהן שורה עצמות המאציל דאיהו וחיוהי חד<sup data-n=\"6735\">31</sup> בהון כידוע, והארון שבו שני לוחות הברית הנה הוא לנגד בחי' אור חכ'<sup data-n=\"6736\">32</sup> דאצי' המלובש בכלי וכך הארון בחי' כלי לאור חכמה עילא' שבלוחות העדות שבהם שרש כללות התורה וידוע דאורייתא מח\"ע נפקת<sup data-n=\"6737\">33</sup> (כידוע) (ובחי' אור הכת\"ר אינו נמנה<sup data-n=\"6738\">34</sup> עם הע\"ס כי הוא בחי' ממוצע<sup data-n=\"6739\">35</sup> בין המאציל לנאצלים כידוע) וכמו ר\"י כה\"ג שראה<sup data-n=\"6740\">36</sup> בחי' כת\"ר עליון מעל <span data-k=\"pg\">תקעד</span> ּ הכפורת כו' וא\"ל ישמעאל בני ברכני<sup data-n=\"6741\">37</sup> שהוא בחי' כת\"ר דמל' דאצי' שהוא שורה למעלה מן הארון בהיכל ק\"ק כו'). ובחי' המנורה והשולחן היינו בחי' חסד וגבורה<sup data-n=\"6742\">38</sup> דאצי' המסתעפי' בבחי' ב' קוין ימין ושמאל חסד לימין כו' כידוע, כי הרי המנורה בדרום והשולחן בצפון<sup data-n=\"6743\">39</sup> וידוע דדרום סטרא דחסד וצפון סטרא דגבורה<sup data-n=\"6744\">40</sup> כמ\"ש מצפון זהב יאתה<sup data-n=\"6745\">41</sup> כו' וארז\"ל הרוצה להחכי\"ם ידרי\"ם<sup data-n=\"6746\">42</sup> והרוצה להעשי\"ר יצפי\"ן כו', פי' כי בחי' הקו של החסד עליון שבסט' דדרום שרשו נמשך הוא מבחי' החכ' (כמ\"ש בזהר בענין ובא לו לקרן דרומי\"ת מזרחי\"ת<sup data-n=\"6747\">43</sup> כו' וכמ\"ש במ\"א), ע\"כ הרוצה להחכי\"ם להמשיך אור החכמה ידרי\"ם בבחי' אור החסד שבדרום כו' והרוצה להעשי\"ר יצפי\"ן כי השולח\"ן בצפו\"ן, מפני שמבחי' הגבורה דוקא נמשך כל ריבוי שפע עוש\"ר ומזו\"ן והעושר נמשך מבחי' תגבורת ההשפעה ששרשה בבחי' גבורה שבחסד<sup data-n=\"6748\">44</sup> כמ\"ש",[["6733","29","<b>מלא כה\"כ</b>: ישעי' ו, ג."],["6734","30","<b>הכלים של המשכן. . ע\"ס</b>: ראה גם לעיל פ' תרומה דש, ג. וש\"נ."],["6735","31","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["6736","32","<b>והארון. . חכ'</b>: ראה גם לקמן שצ, ג. תיב, ב. תכ, ג. תלד, א. תמ, א. מאמרי אדה\"ז תקס\"ז ע' קצט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380398\" data-slug=\"likkutei-torah\" data-id=\"4001380398\">לקו\"ת נשא כב, ג</a>. מאמרי אדה\"א שמות כאן ע' תרסא. הנחות תקע\"ז ע' יט."],["6737","33","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."],["6738","34","<b>הכת\"ר אינו נמנה</b>: ראה גם לעיל פ' בא פט, ג. וש\"נ."],["6739","35","<b>הכת\"ר. . ממוצע</b>: ראה גם לעיל פ' שמות יא, ג. וש\"נ."],["6740","36","<b>ר\"י כה\"ג שראה</b>: ראה גם לעיל צז, ג. וש\"נ."],["6741","37","<b>ישמעאל בני ברכני</b>: ברכות ז, א."],["6742","38","<b>המנורה והשולחן. . חסד וגבורה</b>: ראה ע\"ח (שער ציור עולמות) שמ\"ג, פ\"א. לקמן תיב, ב. תכ, ג. תלד, א. תמ, א. מאמרי אדה\"א הנחות תקע\"ז ע' יט. וש\"נ."],["6743","39","<b>המנורה בדרום והשולחן בצפון</b>: פקודי מ, כב. כד. יומא כא, ב."],["6744","40","<b>דדרום סטרא דחסד. . דגבורה</b>: ראה גם לעיל פ' תרומה שז, ג. וש\"נ."],["6745","41","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["6746","42","<b>הרוצה להחכי\"ם ידרי\"ם</b>: ראה ב\"ב כה, ב."],["6747","43","<b>ובא לו לקרן דרומי\"ת מזרחי\"ת</b>: זבחים נג, א (במשנה). ראה זהר במדבר קכ, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרט ואילך. ביאוה\"ז במדבר [והוא מחודש אייר תקס\"ו] קמה, ב. מאמרי אדה\"ז הנחות הר\"פ ע' נג."],["6748","44","<b>תגבורת ההשפעה. . גבורה שבחסד</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תכט ואילך. ביאוה\"ז פקודי נז, א. לעיל פ' בשלח קסז, ד ובהערה 196."]]]]});
